	public class ApplyWindowInsetsListener : Java.Lang.Object, View.IOnApplyWindowInsetsListener, IJavaObject, IDisposable, IJavaPeerable
	{
		private readonly MainActivity _activity;

		public ApplyWindowInsetsListener(MainActivity activity)
		{
			_activity = activity;
		}

		public WindowInsets OnApplyWindowInsets(View v, WindowInsets insets)
		{
			_activity.DetectSafeAreaInsets();
			return insets;
		}
	}
