	}
	public class AnimatedTextView : FrameLayout
	{
		private TextView _text;

		private bool _isValueChanged;

		private long _value;

		private int? _color;

		public long Value
		{
			get
			{
				return _value;
			}
			set
			{
				if (!_isValueChanged)
				{
					_isValueChanged = true;
				}
				else
				{
					string valueText = ((value - Value < 0) ? $"-{SpecSymbol}{Math.Abs(value - Value):N0}" : $"+{SpecSymbol}{Math.Abs(value - Value):N0}");
					this.ValueChanged?.Invoke(this, new AnimatedTextValueChangedEventArgs(valueText));
				}
				_value = value;
				_text.Text = ((SpecSymbol == "€") ? $"{_value:N0}{SpecSymbol}" : $"{_value:N0}");
			}
		}

		public int? Color
		{
			get
			{
				return _color;
			}
			set
			{
				_color = value;
				if (_color.HasValue)
				{
					_text.SetTextColor(_color.Value.ToColor(base.Context));
				}
				else
				{
					_text.SetTextColor(2131034200.ToColor(base.Context));
				}
			}
		}

		public string SpecSymbol { get; set; }

		public event EventHandler<AnimatedTextValueChangedEventArgs> ValueChanged;

		public AnimatedTextView(Context context)
			: base(context)
		{
			Initialize();
		}

		public AnimatedTextView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public AnimatedTextView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize();
		}

		public AnimatedTextView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
			Initialize();
		}

		protected AnimatedTextView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
			Initialize();
		}

		private void Initialize()
		{
			_text = new TextView(base.Context)
			{
				LayoutParameters = new LayoutParams(-2, -2)
				{
					Gravity = GravityFlags.CenterVertical
				}
			};
			_text.SetTextAppearance(2131886563);
			AddView(_text);
		}
	}
