	public class ImageTextCellView : FrameLayout, ICellView
	{
		private ImageView _image;

		private TextView _text;

		public ImageTextCellView(Context context)
			: base(context)
		{
			Initialize();
		}

		public ImageTextCellView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public ImageTextCellView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize();
		}

		public ImageTextCellView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
			Initialize();
		}

		protected ImageTextCellView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493032, this, attachToRoot: true);
			_image = view.FindViewById<ImageView>(2131297016);
			_text = view.FindViewById<TextView>(2131297687);
		}

		public void Update(TableCell tableCell)
		{
			if (tableCell is ImageTextCell imageTextCell)
			{
				if (!string.IsNullOrEmpty(imageTextCell.ImageName))
				{
					_image.SetImageResource(imageTextCell.ImageName.GetImageId(base.Context));
					_image.Visibility = ViewStates.Visible;
				}
				else
				{
					_image.Visibility = ViewStates.Gone;
				}
				if (!string.IsNullOrEmpty(imageTextCell.Text))
				{
					_text.Text = imageTextCell.Text;
					_text.Gravity = imageTextCell.Alignment.ToGravity();
					_text.SetTextColor(imageTextCell.Color.ToColor(base.Context));
					_text.Visibility = ViewStates.Visible;
				}
				else
				{
					_text.Visibility = ViewStates.Gone;
				}
			}
		}
	}
	public class ScrollTapItemView : FrameLayout
	{
		private GTImageView _imageView;

		private TextView _nameView;

		private TextView _numberView;

		private int _number;

		private string _name;

		private bool _isSelected;

		public string Image
		{
			get
			{
				return _imageView.ImageName;
			}
			set
			{
				_imageView.ImageName = value;
			}
		}

		public int Number
		{
			get
			{
				return _number;
			}
			set
			{
				_number = value;
				_numberView.Text = _number.ToString();
				_numberView.Visibility = ViewStates.Visible;
			}
		}

		public string Name
		{
			get
			{
				return _name;
			}
			set
			{
				_name = value;
				_nameView.Text = _name;
			}
		}

		public bool IsSelected
		{
			get
			{
				return _isSelected;
			}
			set
			{
				_isSelected = value;
				OnViewClicked();
			}
		}

		public ICommand Command
		{
			get
			{
				return _imageView.Command;
			}
			set
			{
				_imageView.Command = value;
			}
		}

		public ScrollTapItemView(Context context)
			: base(context)
		{
			Initialize();
		}

		public ScrollTapItemView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public ScrollTapItemView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize();
		}

		public ScrollTapItemView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
			Initialize();
		}

		protected ScrollTapItemView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493151, this, attachToRoot: true);
			_imageView = view.FindViewById<GTImageView>(2131296287);
			_nameView = view.FindViewById<TextView>(2131296344);
			_numberView = view.FindViewById<TextView>(2131296347);
			_nameView.Alpha = 0f;
		}

		private void OnViewClicked()
		{
			if (IsSelected)
			{
				_imageView.Animate().TranslationY(-50f).SetDuration(150L);
				if (_numberView.Visibility == ViewStates.Visible)
				{
					_numberView.Animate().TranslationY(-50f).SetDuration(150L);
				}
				else
				{
					_nameView.Animate().Alpha(1f).SetDuration(250L);
				}
			}
			else
			{
				if (_numberView.Visibility == ViewStates.Visible)
				{
					_numberView.Animate().TranslationY(0f).SetDuration(150L);
				}
				else
				{
					_nameView.Animate().Alpha(0f).SetDuration(100L);
				}
				_imageView.Animate().TranslationY(0f).SetDuration(150L);
			}
		}
	}
