	public class PlayerModelView : FrameLayout
	{
		private ImageView _headView;

		private ImageView _bodyView;

		private ImageView _glovesView;

		private ImageView _shoesView;

		private ImageView _trikotView;

		private ImageView _medipackView;

		private TextView _injuredView;

		private GTButton _healButtonView;

		private LinearLayout _numbers;

		private SquadPlayerData _playerData;

		private string _trikot;

		public SquadPlayerData PlayerData
		{
			get
			{
				return _playerData;
			}
			set
			{
				_playerData = value;
				if (_playerData == null)
				{
					return;
				}
				SetImage(_headView, _playerData.Head);
				SetImage(_bodyView, _playerData.Body);
				SetImage(_shoesView, _playerData.Shoes);
				SetImage(_glovesView, (_playerData.Position == 0) ? _playerData.Gloves : null);
				_numbers.RemoveAllViews();
				if (_playerData.Shirt >= 0)
				{
					char[] array = _playerData.Shirt.ToString().ToCharArray();
					foreach (char c in array)
					{
						ImageView imageView = new ImageView(base.Context)
						{
							LayoutParameters = new LinearLayout.LayoutParams(-2, -1)
							{
								LeftMargin = 1,
								RightMargin = 1
							}
						};
						imageView.SetImageResource($"shirt_number_{c}".GetImageId(base.Context));
						imageView.SetScaleType(ImageView.ScaleType.CenterInside);
						imageView.SetColorFilter(_playerData.IsShirtLight ? Color.Black : Color.White);
						_numbers.AddView(imageView);
					}
				}
				if (_playerData.Injured > 0)
				{
					_medipackView.Visibility = ViewStates.Visible;
					_injuredView.Visibility = ViewStates.Visible;
					_injuredView.Text = TimeSpan.FromDays(_playerData.Injured).ToLocalizedString(onlyDays: true);
					_healButtonView.Visibility = ShowHealButton.ToVisibility();
				}
				else
				{
					_medipackView.Visibility = ViewStates.Gone;
					_injuredView.Visibility = ViewStates.Gone;
					_healButtonView.Visibility = ViewStates.Gone;
				}
			}
		}

		public bool ShowHealButton { get; set; }

		public string Trikot
		{
			get
			{
				return _trikot;
			}
			set
			{
				if (string.IsNullOrEmpty(value))
				{
					_trikot = "trikot0";
				}
				else
				{
					_trikot = value;
				}
				SetImage(_trikotView, _trikot, "01_");
			}
		}

		public ICommand HealButtonCommand
		{
			get
			{
				return _healButtonView.Command;
			}
			set
			{
				_healButtonView.Command = value;
			}
		}

		public PlayerModelView(Context context)
			: base(context)
		{
			Initialize();
		}

		public PlayerModelView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public PlayerModelView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize();
		}

		public PlayerModelView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
			Initialize();
		}

		protected PlayerModelView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493117, this, attachToRoot: true);
			_headView = view.FindViewById<ImageView>(2131296912);
			_bodyView = view.FindViewById<ImageView>(2131296581);
			_glovesView = view.FindViewById<ImageView>(2131296898);
			_shoesView = view.FindViewById<ImageView>(2131297494);
			_trikotView = view.FindViewById<ImageView>(2131297750);
			_medipackView = view.FindViewById<ImageView>(2131296341);
			_injuredView = view.FindViewById<TextView>(2131296289);
			_healButtonView = view.FindViewById<GTButton>(2131296286);
			_numbers = view.FindViewById<LinearLayout>(2131297325);
		}

		private void SetImage(ImageView imageView, string name, string addName = null)
		{
			imageView.SetImageResource(("Skins_" + addName + name).Replace("-", "_").GetImageId(base.Context));
		}
	}
