	public class PlayerSpecifications : FrameLayout
	{
		private TextView _nameView;

		private TextView _talentView;

		private TextView _ageView;

		private TextView _originView;

		private GTImageView _flagView;

		private TextView _salaryView;

		private TextView _marketValueView;

		private TextView _positionView;

		private TextView _strengthView;

		private GTStrengthStarsView _starsView;

		private TextView _qualityView;

		private TextView _contractUntilView;

		private TextView _contractTextView;

		private View _oldPlayerWarning;

		private SquadPlayerData _playerData;

		public SquadPlayerData PlayerData
		{
			get
			{
				return _playerData;
			}
			set
			{
				_playerData = value;
				if (_playerData != null)
				{
					_nameView.Text = _playerData.Name;
					_talentView.Text = _playerData.Talent.ToString();
					_talentView.SetTextColor((_playerData.IsGoodTalent ? 2131034180 : 2131034164).ToColor(base.Context));
					_ageView.Text = _playerData.Age.ToString();
					_ageView.SetTextColor((_playerData.IsBadAge ? 2131034206 : 2131034164).ToColor(base.Context));
					_originView.Text = _playerData.Origin;
					_flagView.ImageName = "flag_" + _playerData.Country;
					_salaryView.Text = string.Format("{0:N0} {1}", _playerData.Salary, "€");
					_marketValueView.Text = string.Format("{0:N0} {1}", _playerData.MarketValue, "€");
					_positionView.Text = _playerData.GetShortPositionName();
					_strengthView.Text = _playerData.Strength.ToString("N2");
					_starsView.Strength = _playerData.Strength;
					_qualityView.Text = _playerData.Strength.GetStrengthName();
					_contractUntilView.Text = _playerData.EndDateValue.ToGTShortDateString();
					_oldPlayerWarning.Visibility = _playerData.OldAge.ToVisibility();
					WarningCommand = _playerData.ShowWarningCommand;
				}
			}
		}

		public ICommand WarningCommand { get; set; }

		public PlayerSpecifications(Context context)
			: base(context)
