		protected override void OnNewIntent(Intent intent)
		{
			ProcessNewIntent(intent).FireAndForgetSafeAsync();
		}

		private async Task ProcessNewIntent(Intent intent)
		{
			if (!(await ProcessDeeplink(intent)))
			{
				OpenAppFromNotification(intent);
			}
		}

		private async Task<bool> ProcessDeeplink(Intent intent)
		{
			if (intent?.Data == null)
			{
				return false;
			}
			string encodedAuthority = intent.Data.EncodedAuthority;
			string queryParameter = intent.Data.GetQueryParameter("id");
			if (string.IsNullOrEmpty(encodedAuthority) || !Guid.TryParse(queryParameter, out var result))
			{
				return false;
			}
			if (!(encodedAuthority == "acceptchallenge"))
			{
				if (encodedAuthority == "addfriend")
				{
					await AcceptFriendship(result);
					return true;
				}
				return false;
			}
			string queryParameter2 = intent.Data.GetQueryParameter("teamname");
			await AcceptChallenge(result, queryParameter2);
			return true;
		}

		private async Task AcceptChallenge(Guid id, string teamName)
		{
			GT.Core.Log.Info($"deeplink acceptchallenge: id = {id}, teamName = {teamName}");
			if (await ComponentFactory.Resolve<IPopupService>().ShowYesNoMessageAsync("ChallengesAcceptTitle".Translate(), string.Format("ChallengesAcceptQuestion".Translate(), teamName), GT.Core.Character.CoachCheer))
			{
				StartProgress();
				await ComponentFactory.Resolve<IFriendsService>().ReplyChallenge(id, accept: true);
				StopProgress();
				_navigationService.NavigateBack();
			}
		}

		private async Task AcceptFriendship(Guid id)
		{
			GT.Core.Log.Info($"deeplink addfriend: id = {id}");
			StartProgress();
			FriendsResponse friendsResponse = await ComponentFactory.Resolve<IFriendsService>().Accept(id);
			StopProgress();
			if (friendsResponse.Status == ResponseStatus.OK)
			{
				await ComponentFactory.Resolve<IPopupService>().ShowOkMessageAsync("Friends".Translate(), string.Format("AddedFriend".Translate(), friendsResponse.FriendName), GT.Core.Character.AnnaCheer);
			}
			_navigationService.NavigateBack();
		}

		private void OpenAppFromNotification(Intent intent)
		{
			if (intent?.Extras != null)
			{
				string stringExtra = intent.GetStringExtra("id");
				GT.Core.Log.Info(">>> OpenAppFromNotification: " + stringExtra);
				ComponentFactory.Resolve<INotificationManager>()?.CancelNotification(stringExtra);
			}
		}

