		private void OnLoggedOut(object sender, EventArgs e)
		{
			PerformAfterDelay(delegate
			{
				Intent intent = new Intent((Context)(object)this, typeof(MainActivity));
				int requestCode = 123456;
				PendingIntent activity = PendingIntent.GetActivity((Context)(object)this, requestCode, intent, GetFlags());
				((AlarmManager)((Context)(object)this).GetSystemService("alarm")).Set(AlarmType.Rtc, JavaSystem.CurrentTimeMillis() + 1000, activity);
				Exit();
			}, 3000L);
		}

		private PendingIntentFlags GetFlags()
		{
			if (Build.VERSION.SdkInt < BuildVersionCodes.S)
			{
				return PendingIntentFlags.CancelCurrent;
			}
			return PendingIntentFlags.CancelCurrent | PendingIntentFlags.Immutable;
		}

		private void Exit()
		{
			JavaSystem.Exit(0);
		}

