		private void OnShellViewModelPropertyChanged(object sender, PropertyChangedEventArgs e)
		{
			string propertyName = e.PropertyName;
			if (!(propertyName == "ContextMenuItems"))
			{
				if (propertyName == "ContextMenuImage")
				{
					if (string.IsNullOrEmpty(_shellViewModel.ContextMenuImage))
					{
						_contextMenuButton.Visibility = ViewStates.Invisible;
						return;
					}
					_contextMenuButton.SetImageResource(_shellViewModel.ContextMenuImage.GetImageId((Context)(object)this));
					_contextMenuButton.Visibility = ViewStates.Visible;
				}
				return;
			}
			_isContextMenuOpened = false;
			if (_contextMenuContainer.ChildCount > 0)
			{
				for (int i = 0; i < _contextMenuContainer.ChildCount; i++)
				{
					((Button)_contextMenuContainer.GetChildAt(i)).Click -= OnContextMenuItemClick;
				}
				_contextMenuContainer.RemoveAllViews();
			}
			if (_shellViewModel.ContextMenuItems == null)
			{
				return;
			}
			foreach (ContextMenuItem contextMenuItem in _shellViewModel.ContextMenuItems)
			{
				Button button = (Button)LayoutInflater.From((Context)(object)this).Inflate(2131492919, _contextMenuContainer, attachToRoot: false);
				button.Text = contextMenuItem.Title;
				button.Click += OnContextMenuItemClick;
				button.SetSoundEffect();
				_contextMenuContainer.AddView(button);
				button.TranslationX = _contextMenuContainer.Width;
				if (!string.IsNullOrEmpty(contextMenuItem.TutorialControlId))
				{
					button.Tag = contextMenuItem.TutorialControlId;
				}
			}
		}

		private void OnContextMenuItemClick(object sender, EventArgs e)
		{
			if (sender is Button button)
			{
				ToggleContextMenu(forceClose: true);
				int index = _contextMenuContainer.IndexOfChild(button);
				ICommand command = _shellViewModel.ContextMenuItems[index].Command;
				object commandParameter = _shellViewModel.ContextMenuItems[index].CommandParameter;
				command?.Execute(commandParameter);
				if (!string.IsNullOrEmpty(button.Tag?.ToString()))
				{
					TutorialManager.Instance.ControlActivated(button.Tag?.ToString());
				}
			}
		}

