		private void ToggleContextMenu(bool forceClose = false)
		{
			_isContextMenuOpened = !_isContextMenuOpened;
			if (forceClose)
			{
				_isContextMenuOpened = false;
			}
			int num = ((!_isContextMenuOpened) ? (-1) : 0);
			for (int i = 0; i < _contextMenuContainer.ChildCount; i++)
			{
				Button button = (Button)_contextMenuContainer.GetChildAt(i);
				button.Animate().SetDuration(200L).TranslationX((num < 0) ? button.Width : num)
					.SetInterpolator(_interpolator)
					.SetStartDelay(50 * i);
			}
		}

		private void MenuButtonClick(object sender, EventArgs e)
		{
			Action afterOpen = null;
			if (TutorialManager.Instance.InProgress)
			{
				afterOpen = delegate
				{
					int menuScrollIndex = TutorialManager.Instance.GetMenuScrollIndex();
					if (menuScrollIndex > 0)
					{
						_mainMenu.SmoothScrollToPosition(menuScrollIndex);
					}
				};
			}
			ToggleMenu(forceClose: false, forceOpen: false, null, afterOpen);
			TutorialManager.Instance.ControlActivated(_menuButton.Tag?.ToString());
		}

		private void ToggleMenu(bool forceClose = false, bool forceOpen = false, Action afterClose = null, Action afterOpen = null)
		{
			if ((forceClose && !_isMenuOpened) || (forceOpen && _isMenuOpened))
			{
				return;
			}
			if (forceClose)
			{
				_isMenuOpened = true;
			}
			if (forceOpen)
			{
				_isMenuOpened = false;
			}
			bool willOpen = !_isMenuOpened;
			int num = ((!_isMenuOpened) ? ((Context)(object)this).Resources.GetDimensionPixelSize(2131099936) : 0);
			ViewStates endVisibility = (_isMenuOpened ? ViewStates.Gone : ViewStates.Visible);
			float value = (_isMenuOpened ? 0.8f : 1f);
			float value2 = (_isMenuOpened ? 0f : 1f);
			_mainMenu.Visibility = ViewStates.Visible;
			_menuBlocker.Visibility = ViewStates.Visible;
			_menuBlocker.BringToFront();
			if (!_isMenuOpened)
			{
				_mainMenu.ScaleX = 0.8f;
				_mainMenu.ScaleY = 0.8f;
				_mainMenu.Alpha = 0f;
			}
			_gameContainer.Animate().SetDuration(300L).TranslationX(num)
				.SetInterpolator(_interpolator);
			_mainMenu.Animate().SetDuration(300L).Alpha(value2)
				.ScaleX(value)
				.ScaleY(value)
				.WithEndAction(new Runnable(delegate
				{
					_mainMenu.Visibility = endVisibility;
					if (willOpen)
					{
						afterOpen?.Invoke();
					}
					else
					{
						afterClose?.Invoke();
					}
				}));
			_menuBlocker.Animate().SetDuration(300L).Alpha(value2)
				.WithEndAction(new Runnable(delegate
				{
					_menuBlocker.Visibility = endVisibility;
				}));
			_isMenuOpened = !_isMenuOpened;
		}

		private void InitMainMenu()
		{
			_mainMenu.ItemTemplate = 2131493049;
			_mainMenu.Bind(2131297199, "Text", "Text", (object x) => x?.ToString().ToUpper());
