		private MainMenuCell GetMenuCell(string text, string image, ScreenIdentifier screen = ScreenIdentifier.None, string section = null, ICommand command = null, string tutorialControlId = null)
		{
			bool isSelected = _navigationService.GetCurrentScreen() == screen;
			return new MainMenuCell
			{
				Section = section,
				Text = text,
				Image = image,
				Command = (command ?? GotoScreenCommand),
				CommandParameter = screen,
				IsSelected = isSelected,
				TutorialControlId = tutorialControlId
			};
		}

