		private void OnAnimatedValueChanged(object sender, AnimatedTextValueChangedEventArgs e)
		{
			AnimatedTextView animatedTextView = sender as AnimatedTextView;
			Rect rect = new Rect();
			animatedTextView.GetGlobalVisibleRect(rect);
			TextView text = new TextView((Context)(object)this)
			{
				Text = e.ValueText,
				LayoutParameters = new RelativeLayout.LayoutParams(-2, -2)
				{
					LeftMargin = rect.Left,
					TopMargin = rect.Top
				},
				Alpha = 0f
			};
			if (Build.VERSION.SdkInt >= BuildVersionCodes.M)
			{
				text.SetTextAppearance(2131886357);
			}
			if (animatedTextView.Color.HasValue)
			{
				text.SetTextColor(animatedTextView.Color.Value.ToColor((Context)(object)this));
			}
			else
			{
				text.SetTextColor(2131034200.ToColor((Context)(object)this));
			}
			_gameContainer.AddView(text);
			_soundManager.PlaySound(Sounds.Money);
			text.Animate().SetInterpolator(_interpolator).ScaleXBy(0.25f)
				.ScaleYBy(0.25f)
				.TranslationY(-80f)
				.Alpha(1f)
				.SetDuration(1000L)
				.WithEndAction(new Runnable(delegate
				{
					text.Animate().TranslationY(-90f).Alpha(0f)
						.SetDuration(1000L)
						.WithEndAction(new Runnable(delegate
						{
							_gameContainer.RemoveView(text);
							text = null;
						}));
				}));
		}

