		private void HideCurrentScreen()
		{
			View currentView = _currentView;
			if (currentView != null && currentView.Visibility != ViewStates.Gone)
			{
				_character.ImageName = string.Empty;
				_topBar.Text = string.Empty;
				currentView.Visibility = ViewStates.Gone;
				if (currentView is ICleanView cleanView)
				{
					cleanView.OnDisappearing();
				}
			}
		}

		public void AddView(View view)
		{
			MainThread.BeginInvokeOnMainThread(delegate
			{
				_main.AddView(view);
			});
		}

		private void ShowScreen(View view)
		{
			_currentView = view;
			if (view.Parent == null)
			{
				_container.AddView(view);
			}
			view.Visibility = ViewStates.Visible;
			_menuBlocker.BringToFront();
			if (view is ICleanView cleanView)
			{
				cleanView.OnAppearing();
			}
		}

		public void NavigateTo(Type screenType, bool isGameScreen, bool toModalScreen)
		{
			MainThread.BeginInvokeOnMainThread(delegate
			{
				if (_isChatOpen)
				{
					HideChat();
				}
				HideCurrentScreen();
				GT.Core.Log.Info($"-> navigate to screen: {screenType}");
				if (!isGameScreen || !_screens.TryGetValue(screenType, out var value))
				{
					value = Activator.CreateInstance(screenType, this);
					if (isGameScreen)
					{
						_screens[screenType] = value;
					}
				}
				if (value is View currentView)
				{
					UpdateContent(currentView);
				}
				_backButton.Visibility = ((!toModalScreen) ? ViewStates.Gone : ViewStates.Visible);
				_menuButton.Visibility = (toModalScreen ? ViewStates.Gone : ViewStates.Visible);
				UpdateMenu();
				ToggleMenu(forceClose: true);
			});
		}

		public void SelectTab(int tabIndex)
		{
			if (_currentView is ITabbedView tabbedView)
			{
				tabbedView.SelectTab(tabIndex);
			}
		}

		private void UpdateContent(View currentView)
		{
			ScreenIdentifier currentScreen = _navigationService.GetCurrentScreen();
			ShowTopBar(currentScreen.IsGameScreen());
			ShowScreen(currentView);
			_shellBiniding?.Start();
			_shellViewModel.ApplyBinding();
			if (currentScreen.IsGameScreen())
			{
				ShowNavigationBar();
				UpdateResources().FireAndForgetSafeAsync();
			}
			else
			{
				HideNavigationBar();
			}
		}

		private async Task UpdateResources()
		{
			_resourcesBinding?.Start();
			await _resourcesViewModel.Update();
			_resourcesViewModel.ApplyBinding();
		}

		private void BackButtonClick(object sender, EventArgs e)
		{
			GT.Core.Log.Info("<- clicked");
			GoBack();
			TutorialManager.Instance.ControlActivated(_backButton.Tag?.ToString());
		}

		protected override void OnPause()
		{
			((Activity)(object)this).OnPause();
			_pausedTime = DateTime.Now;
			_soundManager.PauseMusic();
			IronSource.OnPause((Activity)(object)this);
		}

		protected override void OnResume()
		{
			((Activity)(object)this).OnResume();
			if (ComponentFactory.Resolve<IPreferencesService>().IntroVideoPlayed)
			{
				_soundManager.PlayMusic();
			}
			ComponentFactory.Resolve<ChatViewModel>().Reinit().FireAndForgetSafeAsync();
			if (!(DateTime.Now - _pausedTime < _silentRestoreTime))
			{
				if (_navigationService.GetCurrentScreen() != ScreenIdentifier.None)
				{
					UpdateContent(_currentView);
					return;
				}
				Authenticate().FireAndForgetSafeAsync();
				IronSource.OnResume((Activity)(object)this);
			}
		}

		private async Task Authenticate()
		{
			if (!_progress)
			{
				_progress = true;
				StartProgress();
				AuthResponse authResponse = await ComponentFactory.Resolve<IAuthService>().Login();
				if (authResponse == null)
				{
					_progress = false;
				}
				else if (authResponse.Status == ResponseStatus.OK)
				{
					GT.Core.Log.Info("token = " + authResponse.Token);
					_navigationService.NavigateTo(ScreenIdentifier.Club);
					_progress = false;
				}
				else
				{
					await ComponentFactory.Resolve<ICommonService>().GetCountries();
					_navigationService.NavigateTo(ScreenIdentifier.QuickStart);
					_progress = false;
				}
			}
		}

