		{
			FadeInView(_bottomBar);
		}

		private void FadeInView(View view)
		{
			if (view.Visibility != ViewStates.Visible || !(view.Alpha >= 1f))
			{
				view.Alpha = 0f;
				view.Visibility = ViewStates.Visible;
				view.FadeIn();
			}
		}

		public override void OnBackPressed()
		{
			GT.Core.Log.Info(" <- back pressed <-");
			if (ClosePopup())
			{
				GT.Core.Log.Info(" - tap close button");
				return;
			}
			if (!TutorialManager.Instance.InProgress)
			{
				if (_isMenuOpened)
				{
					GT.Core.Log.Info(" - close menu");
					ToggleMenu();
					return;
				}
				if (_isChatOpen)
				{
					GT.Core.Log.Info(" - close chat");
					HideChat();
					return;
				}
				if (CancelView())
				{
					GT.Core.Log.Info(" - tap cancel button");
					return;
				}
				if (ButtonClicked(_backButton))
				{
					GT.Core.Log.Info(" - tap back button");
					return;
				}
				ScreenIdentifier currentScreen = _navigationService.GetCurrentScreen();
				bool flag = currentScreen != ScreenIdentifier.GTLadder || ComponentFactory.Resolve<LadderViewModel>().CanLeave;
				if (currentScreen != ScreenIdentifier.Club && currentScreen.IsGameScreen() && ComponentFactory.Resolve<ClubViewModel>().IsInited && flag)
				{
					_navigationService.NavigateTo(ScreenIdentifier.Club);
					return;
				}
			}
			if (CloseApp())
			{
				GT.Core.Log.Info(" - close app");
			}
			else
			{
				ShowNotification(new NotificationData("TapToExit".Translate()));
			}
		}

		private bool CloseApp()
		{
			if (_notificationView != null && _notificationView.Visibility == ViewStates.Visible && _notificationView.IsSpecial)
			{
				Exit();
				return true;
			}
			return false;
		}

		private bool ClosePopup()
		{
			return EnumerateAndClick(_main, "close_button");
		}

		private bool CancelView()
		{
			return EnumerateAndClick(_container, "cancel_button");
		}

		private bool EnumerateAndClick(ViewGroup viewGroup, string tag)
		{
			for (int num = viewGroup.ChildCount - 1; num > -1; num--)
			{
				View childAt = viewGroup.GetChildAt(num);
				if (childAt != null && childAt.Visibility == ViewStates.Visible)
				{
					View button = childAt.FindViewWithTag(tag);
					if (ButtonClicked(button))
					{
						return true;
					}
				}
			}
			return false;
		}

		private bool ButtonClicked(View button)
		{
			if (button == null || button.Visibility != ViewStates.Visible || !button.Enabled)
			{
				return false;
			}
			button.CallOnClick();
			return true;
		}

		private void GoBack()
		{
			_navigationService.NavigateBack();
		}

		private void OnChatButtonCLick(object sender, EventArgs e)
