		public void ShowNotification(NotificationData notification)
		{
			if (notification.IsSpecial)
			{
				DisplayNotification(notification);
				return;
			}
			if (_isAdOpened)
			{
				_delayedAdNotification = notification;
				return;
			}
			PendingNotifications.Enqueue(notification);
			ShowNextNotification();
		}

		private void ShowNextNotification()
		{
			if (PendingNotifications.Count != 0 && _notificationView.Visibility != ViewStates.Visible && PendingNotifications.TryDequeue(out var result))
			{
				DisplayNotification(result);
			}
		}

		private void DisplayNotification(NotificationData notification)
		{
			MainThread.BeginInvokeOnMainThread(delegate
			{
				_notificationView.Show(notification);
			});
			if (!string.IsNullOrEmpty(notification.Parameter))
			{
				ResourceService.Current.Update();
			}
		}

		private void OnNotificationViewFinished(object sender, EventArgs e)
		{
			ShowNextNotification();
		}

		public void UpdateBadge(MenuItemIdentifier id)
