		}

		public void Lock()
		{
			GT.Core.Log.Info("... LOCK");
			MainThread.BeginInvokeOnMainThread(delegate
			{
				_blockerView.Visibility = ViewStates.Visible;
				UpdateCloseButtonVisibility();
				_skipTutorialButton.BringToFront();
				_loadingImage.BringToFront();
			});
		}

		public void Unlock()
		{
			GT.Core.Log.Info("... UNLOCK");
			MainThread.BeginInvokeOnMainThread(delegate
			{
				_blockerView.Visibility = ViewStates.Gone;
				UpdateCloseButtonVisibility();
			});
		}

		private void UpdateCloseButtonVisibility()
		{
			_skipTutorialButton.Visibility = TutorialManager.Instance.CanSkip.ToVisibility();
		}

		public void OpenMainMenu()
		{
		}

		public void EntryGotFocus(object view)
		{
			GT.Core.Log.Info("Entry Got Focus");
			_textField = view as TextField;
			_entryWatcher.Visibility = ViewStates.Visible;
			_entryWatcher.BringToFront();
		}

		public void EntryDone()
		{
			HideKeyboard();
		}

		private void OnEntryWatcherClicked(object sender, EventArgs e)
		{
			HideKeyboard();
		}

		private void HideKeyboard()
		{
			if (((Context)(object)this).GetSystemService("input_method") is InputMethodManager inputMethodManager)
			{
				GT.Core.Log.Info("Hide Soft Input From Window");
				inputMethodManager.HideSoftInputFromWindow(_entryWatcher.WindowToken, HideSoftInputFlags.None);
				_textField?.ClearFocus();
				_entryWatcher.Visibility = ViewStates.Gone;
			}
		}

		public void OnRewardedVideoAdClosed()
		{
			GT.Core.Log.Info("VideoAd: closed");
			_isAdOpened = false;
			if (_delayedAdNotification.HasValue)
			{
				PerformAfterDelay(delegate
				{
					DisplayNotification(_delayedAdNotification.Value);
					_delayedAdNotification = null;
				}, 500L);
			}
		}

		public void OnRewardedVideoAdEnded()
		{
			GT.Core.Log.Info("VideoAd: ad ended");
		}

		public void OnRewardedVideoAdOpened()
		{
			GT.Core.Log.Info("VideoAd: ad opened");
			_isAdOpened = true;
		}

		public void OnRewardedVideoAdRewarded(Placement placement)
		{
			GT.Core.Log.Info($"VideoAd: rewarded +{placement.RewardAmount} {placement.RewardName}");
		}

		public void OnRewardedVideoAdShowFailed(IronSourceError error)
		{
			GT.Core.Log.Info("VideoAd: error " + error.ErrorMessage);
		}

		public void OnRewardedVideoAdStarted()
		{
			GT.Core.Log.Info("VideoAd: started");
		}

		public void OnRewardedVideoAvailabilityChanged(bool available)
		{
			GT.Core.Log.Info($"VideoAd: available = {available}");
			if (!TutorialManager.Instance.InProgress)
			{
				MainThread.BeginInvokeOnMainThread(UpdateMenu);
				ComponentFactory.Resolve<ShopViewModel>().SetVideoAdEnabled(available);
			}
		}

		public void OnRewardedVideoAdClicked(Placement placement)
		{
			GT.Core.Log.Info($"VideoAd: ad clicked +{placement.RewardAmount} {placement.RewardName}");
		}
	}
	public class BaseScrollPopup<T> : BasePopup<T> where T : BasePopupViewModel
	{
		protected LinearLayout _container;

		protected GTButton _doneButton;

		protected TextView _message;

		private HorizontalScrollView _scroll;

		private ImageView _arrowLeft;

		private ImageView _arrowRight;

		public BaseScrollPopup(Context context)
			: base(context)
		{
			Initialize();
		}

		public BaseScrollPopup(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public BaseScrollPopup(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			SetPopupContent(2131492900);
			_scroll = base.PopupContent.FindViewById<HorizontalScrollView>(2131296362);
			_container = base.PopupContent.FindViewById<LinearLayout>(2131296271);
			_doneButton = base.PopupContent.FindViewById<GTButton>(2131296801);
			_arrowLeft = base.PopupContent.FindViewById<ImageView>(2131296262);
			_arrowRight = base.PopupContent.FindViewById<ImageView>(2131296263);
			_arrowLeft.Click += OnArrowLeftClicked;
			_arrowLeft.SetSoundEffect();
			_arrowRight.Click += OnArrowRightClicked;
			_arrowRight.SetSoundEffect();
			_doneButton.Click += OnDoneButtonClicked;
			_message = base.PopupContent.FindViewById<TextView>(2131296342);
		}

		private void OnDoneButtonClicked(object sender, EventArgs eventArgs)
		{
			ClosePopup(PopupResult.Done);
		}

		private void OnCancelButtonClicked(object sender, EventArgs eventArgs)
		{
			ClosePopup(PopupResult.Canceled);
		}

		private void OnArrowRightClicked(object sender, EventArgs eventArgs)
		{
			_scroll.SmoothScrollBy((int)((double)_scroll.Width * 0.8), 0);
		}

		private void OnArrowLeftClicked(object sender, EventArgs eventArgs)
		{
			_scroll.SmoothScrollBy(-(int)((double)_scroll.Width * 0.8), 0);
		}
	}
