	public class BaseTimer : FrameLayout, ICellView
	{
		private string _timeFinishedText;

		private IDeviceService _deviceService;

		public System.Timers.Timer _timer;

		private DateTime _endDate;

		private TextView _timeView;

		protected virtual int CellLayoutId => 2131493189;

		protected virtual int TimeViewId => 2131297650;

		protected virtual string TimeLeftCaption => string.Empty;

		public DateTime EndDate
		{
			get
			{
				return _endDate;
			}
			set
			{
				_endDate = value;
				Refresh();
			}
		}

		public BaseTimer(Context context)
			: base(context)
		{
			Initialize();
		}

		public BaseTimer(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public BaseTimer(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize();
		}

		public BaseTimer(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
			Initialize();
		}

		protected BaseTimer(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
			Initialize();
		}

		private void Initialize()
		{
			_deviceService = ComponentFactory.Resolve<IDeviceService>();
			View view = LayoutInflater.From(base.Context).Inflate(CellLayoutId, this, attachToRoot: true);
			_timeView = view.FindViewById<TextView>(TimeViewId);
			_timer = new System.Timers.Timer
			{
				Interval = 1000.0
			};
			_timer.Elapsed += OnTick;
		}

		private void OnTick(object sender, ElapsedEventArgs e)
		{
			_deviceService.InvokeOnMainThread(Refresh);
		}

		private void Refresh()
		{
			DateTime utcNow = DateTime.UtcNow;
			bool isFininshed = utcNow >= EndDate;
			TimeSpan timeLeft = EndDate - utcNow;
			if (isFininshed)
			{
				_timer.Stop();
				timeLeft = TimeSpan.Zero;
				OnTimerFinished();
			}
			else if (!_timer.Enabled && !TutorialManager.Instance.InProgress)
			{
				_timer.Start();
			}
			if (_timeView != null)
			{
				MainThread.BeginInvokeOnMainThread(delegate
				{
					_timeView.Text = (isFininshed ? _timeFinishedText : (TimeLeftCaption + timeLeft.ToLocalizedString(onlyDays: true)));
				});
			}
		}

		protected virtual void OnTimerFinished()
		{
		}

		protected void SetVisibility(ViewStates viewStates)
		{
			_timeView.Visibility = viewStates;
		}

		public virtual void Update(TableCell tableCell)
		{
			TimerCell timerCell = tableCell as TimerCell;
			if (timerCell != null)
			{
				MainThread.BeginInvokeOnMainThread(delegate
				{
					_timeFinishedText = timerCell.Text;
					_timeView.Gravity = timerCell.Alignment.ToGravity();
				});
				EndDate = timerCell.EndDate;
			}
		}
	}
