	public class ComboBox : FrameLayout
	{
		private GTButton _button;

		private GTTableView _table;

		private bool _isOpened;

		private string _text;

		private ComboBoxItem _selectedItem;

		private object _selectedValue;

		private List<ComboBoxItem> _items;

		private int _selectedIndex = -1;

		public string Text
		{
			get
			{
				return _text;
			}
			set
			{
				_text = value;
				_button.Title = _text;
			}
		}

		public ComboBoxItem SelectedItem
		{
			get
			{
				return _selectedItem;
			}
			set
			{
				_selectedItem = value;
				OnItemSelected();
			}
		}

		public object SelectedValue
		{
			get
			{
				return _selectedValue;
			}
			set
			{
				_selectedValue = value;
				SelectedItem = Items?.FirstOrDefault((ComboBoxItem x) => x.Value == _selectedValue);
			}
		}

		public List<ComboBoxItem> Items
		{
			get
			{
				return _items;
			}
			set
			{
				_items = value;
				UpdateItems();
			}
		}

		public int SelectedIndex
		{
			get
			{
				return _selectedIndex;
			}
			set
			{
				if (_selectedIndex != value && Items != null && Items.Count != 0)
				{
					_selectedIndex = value;
					if (_selectedIndex >= 0 && _selectedIndex < Items.Count)
					{
						SelectedItem = Items[_selectedIndex];
					}
					else
					{
						SelectedItem = null;
					}
					this.SelectedIndexChanged?.Invoke(this, new SelectedIndexChangedEventArgs(_selectedIndex));
				}
			}
		}

		public override bool Enabled
		{
			get
			{
				return base.Enabled;
			}
			set
			{
				base.Enabled = value;
				_button.Enabled = value;
				if (!value)
				{
					CloseMenu();
				}
			}
		}

		public string TutorialControlId
		{
			get
			{
				return _button.Tag?.ToString();
			}
			set
			{
				_button.Tag = value;
			}
		}

		public event EventHandler<ComboBoxItemSelectedEventArgs> ItemSelected;

		public event EventHandler<SelectedIndexChangedEventArgs> SelectedIndexChanged;

		public event EventHandler<bool> FocusChanged;

		public ComboBox(Context context)
			: base(context)
		{
			Initialize();
		}

		public ComboBox(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public ComboBox(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131492915, this, attachToRoot: true);
			_button = view.FindViewById<GTButton>(2131296714);
			_button.Click += OnButtonClick;
			_table = view.FindViewById<GTTableView>(2131296715);
			_table.Visibility = ViewStates.Invisible;
			_table.HeaderRow = new HeaderRow(new HeaderCell());
			_table.RowHeight = 2131099775.ToSize(base.Context);
			_table.SetHeaderHeight(2131100251.ToSize(base.Context));
			_table.SetHeaderColor(2131034175);
		}

		private void OnButtonClick(object sender, EventArgs e)
		{
			this.FocusChanged?.Invoke(this, !_isOpened);
			ToggleMenu();
		}

		public void OpenMenu()
		{
			if (!_isOpened)
			{
				ToggleMenu();
			}
		}

		public void CloseMenu()
		{
			if (_isOpened)
			{
				ToggleMenu();
			}
		}

		private void ToggleMenu()
		{
			float value = -_table.Height;
			ViewStates visibility = ViewStates.Gone;
			if (!_isOpened)
			{
				_table.TranslationY = -_table.Height;
				_table.Visibility = ViewStates.Visible;
				value = 0f;
				visibility = ViewStates.Visible;
			}
			_table.Animate().SetDuration(300L).TranslationY(value)
				.SetInterpolator(new DecelerateInterpolator())
				.WithEndAction(new Runnable(delegate
				{
					_table.Visibility = visibility;
				}));
			_isOpened = !_isOpened;
		}

		private void UpdateItems()
		{
			List<ITableRow> list = new List<ITableRow>();
			if (Items != null)
			{
				foreach (ComboBoxItem item in Items)
				{
					list.Add(new TableRow(new TextCell(item.Text))
					{
						TutorialControlId = item.TutorialControlId,
						Command = new Command<ComboBoxItem>(OnItemClicked),
						CommandParameter = item
					});
				}
			}
			_table.Rows = list;
		}

		private void OnItemClicked(ComboBoxItem item)
		{
			ComponentFactory.Resolve<ISoundManager>().PlaySound(Sounds.Button);
			CloseMenu();
			SelectedItem = item;
			if (item.Command != null && item.Command.CanExecute(item.CommandParameter))
			{
				item.Command.Execute(item.CommandParameter);
			}
		}

		private void OnItemSelected()
		{
			_button.Title = SelectedItem?.Text ?? Text;
			this.ItemSelected?.Invoke(this, new ComboBoxItemSelectedEventArgs(SelectedItem));
			SelectedIndex = ((SelectedItem == null) ? (-1) : Items.IndexOf(SelectedItem));
		}
	}
	public class ComboBoxItemSelectedEventArgs : EventArgs
	{
		public ComboBoxItem SelectedItem { get; }

		public ComboBoxItemSelectedEventArgs(ComboBoxItem selectedItem)
		{
			SelectedItem = selectedItem;
		}
	}
