	public class GTButton : FrameLayout
	{
		private int _value;

		private bool _ispremium;

		private ButtonType _buttonType;

		private string _title;

		private TextView _titleLabel;

		private TextView _valueLabel;

		private ImageView _starImage;

		public int Value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
				Update();
			}
		}

		public bool IsPremium
		{
			get
			{
				return _ispremium;
			}
			set
			{
				_ispremium = value;
				SetBackground(_ispremium ? 2131165522 : 2131165516);
				_starImage.Visibility = _ispremium.ToVisibility();
				_valueLabel.SetTextColor((_ispremium ? 2131034199 : 2131034174).ToColor(base.Context));
			}
		}

		public ButtonType ButtonType
		{
			get
			{
				return _buttonType;
			}
			set
			{
				_buttonType = value;
				if (_buttonType == ButtonType.Premium)
				{
					IsPremium = true;
					return;
				}
				IsPremium = false;
				int background = 0;
				switch (_buttonType)
				{
				case ButtonType.Standart:
					return;
				case ButtonType.Inactive:
					background = 2131165513;
					break;
				case ButtonType.Cancel:
					background = 2131165497;
					break;
				}
				SetBackground(background);
			}
		}

		public Color TextColor
		{
			set
			{
				_titleLabel.SetTextColor(value);
			}
		}

		public string Title
		{
			get
			{
				return _title;
			}
			set
			{
				_title = value;
				Update();
			}
		}

		public bool CustomBackground { get; set; }

		public ICommand Command { get; set; }

		public object CommandParameter { get; set; }

		public GTButton(Context context)
			: base(context)
		{
			Initialize(null);
		}

		public GTButton(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize(attrs);
		}

		public GTButton(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize(attrs);
		}

		private void Initialize(IAttributeSet attrs)
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493140, this, attachToRoot: true);
			_titleLabel = view.FindViewById<TextView>(2131297363);
			_valueLabel = view.FindViewById<TextView>(2131297364);
			_starImage = view.FindViewById<ImageView>(2131297362);
			if (attrs != null)
			{
				TypedArray typedArray = base.Context.ObtainStyledAttributes(attrs, Resource.Styleable.GTButton);
				CustomBackground = typedArray.GetBoolean(1, defValue: false);
				IsPremium = typedArray.GetBoolean(2, defValue: false);
				Title = typedArray.GetString(3);
				Value = typedArray.GetInteger(4, 0);
				ButtonType integer = (ButtonType)typedArray.GetInteger(0, 0);
				if (integer != ButtonType.None)
				{
					ButtonType = integer;
				}
				typedArray.Recycle();
			}
			Update();
			base.Click += OnClick;
			this.SetSoundEffect();
		}

		private void SetBackground(int id)
		{
			if (!CustomBackground)
			{
				SetBackgroundResource(id);
			}
		}

		private void Update()
		{
			_titleLabel.Text = Title;
			if (Value <= 0)
			{
				_valueLabel.Visibility = ViewStates.Gone;
				_starImage.Visibility = ViewStates.Gone;
			}
			else
			{
				_starImage.Visibility = IsPremium.ToVisibility();
				_valueLabel.Visibility = ViewStates.Visible;
				_valueLabel.Text = (IsPremium ? string.Empty : "€") + Value.ToShortValue();
			}
		}

		private void OnClick(object sender, EventArgs e)
		{
			if (Command != null && Command.CanExecute(CommandParameter))
			{
				Command.Execute(CommandParameter);
			}
			if (!string.IsNullOrEmpty(Tag?.ToString()))
			{
				TutorialManager.Instance.ControlActivated(Tag.ToString());
			}
		}
	}
