		{
			if (attrs != null)
			{
				TypedArray typedArray = base.Context.ObtainStyledAttributes(attrs, Resource.Styleable.GTImageView);
				AutoHideNoImage = typedArray.GetBoolean(0, defValue: false);
				IsTouchable = typedArray.GetBoolean(1, defValue: false);
				typedArray.Recycle();
			}
			if (Background != null && IsTouchable)
			{
				this.AddTouchEffect();
			}
		}

		private void ExecuteCommand(object sender, EventArgs e)
		{
			if (Command != null && Command.CanExecute(null))
			{
				Command.Execute(null);
			}
			if (!string.IsNullOrEmpty(Tag?.ToString()))
			{
				TutorialManager.Instance.ControlActivated(Tag.ToString());
			}
		}

		private void SetImage(int id)
		{
			_imageResource = id;
			if (AutoHideNoImage)
			{
				Visibility = (id > 0).ToVisibility();
			}
			if (IsTouchable)
			{
				MakeTouchable(id);
			}
			else
			{
				SetImageResource(id);
			}
		}

		private void MakeTouchable(int id)
		{
			Background = base.Context.GetDrawable(id);
			this.AddTouchEffect();
		}
