	public class GTListViewHolder : RecyclerView.ViewHolder
	{
		private const string ModelBindingName = "this";

		private readonly Dictionary<int, View> _views;

		private readonly Dictionary<object, ICommand> _commands;

		private readonly Dictionary<object, object> _commandParameters;

		private readonly ICommand _selectionCommand;

		private object _model;

		private ICollectionCellView _collectionCellView;

		public GTListViewHolder(View itemView, ICommand selectionCommand = null)
			: base(itemView)
		{
			_views = new Dictionary<int, View>();
			_commands = new Dictionary<object, ICommand>();
			_commandParameters = new Dictionary<object, object>();
			_selectionCommand = selectionCommand;
			if (_selectionCommand != null)
			{
				itemView.Click += OnItemViewClicked;
			}
			AddSubViews(itemView);
			if (itemView is ICollectionCellView collectionCellView)
			{
				_collectionCellView = collectionCellView;
			}
		}

		private void OnItemViewClicked(object sender, EventArgs e)
		{
			if (_selectionCommand != null && _selectionCommand.CanExecute(_model))
			{
				_selectionCommand.Execute(_model);
			}
		}

		private void AddSubViews(View view)
		{
			if (view != null)
			{
				_views[view.Id] = view;
			}
			if (view is ViewGroup viewGroup)
			{
				for (int i = 0; i < viewGroup.ChildCount; i++)
				{
					AddSubViews(viewGroup.GetChildAt(i));
				}
			}
		}

		public void Update(Dictionary<string, List<ViewBindingInfo>> bindings, object model)
		{
			_model = model;
			_commands.Clear();
			if (_collectionCellView != null)
			{
				_collectionCellView.Update(model);
				return;
			}
			Dictionary<string, PropertyInfo> propertyDictionary = model.GetType().GetPropertyDictionary();
			foreach (string key in bindings.Keys)
			{
				foreach (ViewBindingInfo item in bindings[key])
				{
					object obj;
					if (key == "this")
					{
						obj = model;
					}
					else
					{
						if (!propertyDictionary.TryGetValue(key, out var value))
						{
							continue;
						}
						obj = value.GetValue(model);
					}
					View view = _views[item.Id];
					if (item.Converter != null)
					{
						obj = item.Converter(obj);
					}
					if (item.PropertyName == "Command")
					{
						_commands[view] = obj as ICommand;
						view.Click -= OnClick;
						view.Click += OnClick;
						view.SoundEffectsEnabled = false;
						continue;
					}
					if (item.PropertyName == "CommandParameter")
					{
						_commandParameters[view] = obj;
						continue;
					}
					if (view is TextView textView)
					{
						if (item.PropertyName == "TextColor")
						{
							textView.SetTextColor((Color)obj);
							continue;
						}
						if (item.PropertyName == "TextStyle")
						{
							textView.SetTextAppearance((int)obj);
							continue;
						}
					}
					if (item.PropertyName == "ImageResource")
					{
						if (obj != null)
						{
							if (view is ImageView imageView)
							{
								imageView.SetImageResource((int)obj);
								imageView.Visibility = ViewStates.Visible;
							}
							else
							{
								view.SetBackgroundResource((int)obj);
							}
						}
						else if (view is ImageView imageView2)
						{
							imageView2.Visibility = ViewStates.Gone;
						}
					}
					else
					{
						view.GetType().GetPropertyDictionary()[item.PropertyName].SetValue(view, obj);
					}
				}
			}
		}

		private void OnClick(object sender, EventArgs e)
		{
			if (!_commands.ContainsKey(sender))
			{
				return;
			}
			ICommand command = _commands[sender];
			if (command == null)
			{
				return;
			}
			_commandParameters.TryGetValue(sender, out var value);
			if (command.CanExecute(value))
			{
				command.Execute(value);
				if (sender is View view && !string.IsNullOrEmpty(view.Tag?.ToString()))
				{
					TutorialManager.Instance.ControlActivated(view.Tag.ToString());
				}
			}
		}
	}
	public class GTProgressBar : FrameLayout
	{
		private View _background;

		private View _progressImage;

		private float _currentProgress = -1f;

		private decimal _minValue;

		private decimal _maxValue = 1m;

		private decimal _progress;

		public decimal MinValue
		{
			get
			{
				return _minValue;
			}
			set
			{
				_minValue = value;
				UpdateProgressBar();
			}
		}

		public decimal MaxValue
		{
			get
			{
				return _maxValue;
			}
			set
			{
				_maxValue = value;
				UpdateProgressBar();
			}
		}

		public decimal Progress
		{
			get
			{
				return _progress;
			}
			set
			{
				_progress = value;
				UpdateProgressBar();
			}
		}

		public GTProgressBar(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTProgressBar(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTProgressBar(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.FromContext(base.Context).Inflate(2131493142, this, attachToRoot: true);
			_background = view.FindViewById<View>(2131297368);
			_progressImage = view.FindViewById<View>(2131297369);
		}

		protected void SetProgressImageResources(int backgroundImageResourceId, int foregroundImageResourceId)
		{
			_background.SetBackgroundResource(backgroundImageResourceId);
			_progressImage.SetBackgroundResource(foregroundImageResourceId);
		}

		private void UpdateProgressBar()
		{
			if (MinValue > MaxValue || MaxValue - MinValue == 0m || (MinValue == 0m && MaxValue == 0m && Progress == 0m))
			{
				return;
			}
			float num = (float)((Progress.Clamp(MinValue, MaxValue) - MinValue) / (MaxValue - MinValue));
			if (!(Math.Abs(num - _currentProgress) <= 1E-45f))
			{
				_currentProgress = num;
				if (_progressImage.LayoutParameters is ConstraintLayout.LayoutParams layoutParams)
				{
					layoutParams.MatchConstraintPercentWidth = num;
					_progressImage.LayoutParameters = layoutParams;
				}
			}
		}
	}
	public class GTRangeSlider : RelativeLayout
	{
		private int _thumbSize;

		private static readonly string _maxText = "Max".Translate();

		private View _thumbLeft;

		private View _thumbRight;

		private TextView _nameView;

		private TextView _rangeView;

		private View _track;

		private float _mLastTouchX;

		private bool _isLeftThumbCaptured;

		private bool _isRightThumbCaptured;

		private double _selectedMinValue;

		private double _selectedMaxValue;

		private double _minValue;

		private double _maxValue = 1.0;

		private bool _displayMax;

		private string _name;

		private double _initMinValue;

		private double _initMaxValue;

		private bool _setInitSelection;

		public double MinValue
		{
			get
			{
				return _minValue;
			}
			set
			{
				_minValue = value;
				SelectedMinValue = _minValue;
			}
		}

		public double MaxValue
		{
			get
			{
				return _maxValue;
			}
			set
			{
				_maxValue = value;
				SelectedMaxValue = _maxValue;
				UpdateText();
			}
		}

		public double SelectedMinValue
		{
			get
			{
				return _selectedMinValue;
			}
			set
			{
				_selectedMinValue = value;
				UpdateText();
				this.SelectedMinValueChanged?.Invoke(this, new SliderValueChanged(_selectedMinValue));
			}
		}

		public double SelectedMaxValue
		{
			get
			{
				return _selectedMaxValue;
			}
			set
			{
				_selectedMaxValue = value;
				UpdateText();
				this.SelectedMaxValueChanged?.Invoke(this, new SliderValueChanged(_selectedMaxValue));
			}
		}

		public bool DisplayMax
		{
			get
			{
				return _displayMax;
			}
			set
			{
				_displayMax = value;
				UpdateText();
			}
		}

		public string Name
		{
			get
			{
				return _name;
			}
			set
			{
				_name = value;
				_nameView.Text = _name;
			}
		}

		public event EventHandler<SliderValueChanged> SelectedMinValueChanged;

		public event EventHandler<SliderValueChanged> SelectedMaxValueChanged;

		public GTRangeSlider(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTRangeSlider(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTRangeSlider(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void UpdateText()
		{
			string arg = ((DisplayMax && SelectedMaxValue == MaxValue) ? _maxText : SelectedMaxValue.ToString("N0"));
			_rangeView.Text = $"{SelectedMinValue:N0} - {arg}";
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493146, this, attachToRoot: true);
			_nameView = view.FindViewById<TextView>(2131297391);
			_rangeView = view.FindViewById<TextView>(2131297393);
			_track = view.FindViewById<View>(2131297390);
			_thumbLeft = view.FindViewById<View>(2131297389);
			_thumbRight = view.FindViewById<View>(2131297392);
			_thumbSize = _thumbLeft.LayoutParameters.Width;
		}

		public override bool OnTouchEvent(MotionEvent e)
		{
			float x = e.GetX();
			float y = e.GetY();
			switch (e.ActionMasked)
			{
			case MotionEventActions.Down:
				CheckForCapturingOfThumb(x, y);
				base.Parent?.RequestDisallowInterceptTouchEvent(disallowIntercept: true);
				break;
			case MotionEventActions.Move:
				TryToMoveThumb(x);
				break;
			case MotionEventActions.Up:
				_isLeftThumbCaptured = (_isRightThumbCaptured = false);
				base.Parent?.RequestDisallowInterceptTouchEvent(disallowIntercept: false);
				break;
			}
			_thumbLeft.SetBackgroundResource(_isLeftThumbCaptured ? 2131165687 : 2131165686);
			_thumbRight.SetBackgroundResource(_isRightThumbCaptured ? 2131165687 : 2131165686);
			_mLastTouchX = x;
			return true;
		}

		private void CheckForCapturingOfThumb(float x, float y)
		{
			if (_isLeftThumbCaptured || _isRightThumbCaptured)
			{
				return;
			}
			Rect rect = new Rect();
			_thumbLeft.GetHitRect(rect);
			if (rect.Contains((int)x, (int)y))
			{
				_isLeftThumbCaptured = true;
				return;
			}
			Rect rect2 = new Rect();
			_thumbRight.GetHitRect(rect2);
			if (rect2.Contains((int)x, (int)y))
			{
				_isRightThumbCaptured = true;
			}
		}

		private void TryToMoveThumb(float x)
		{
			if (_isLeftThumbCaptured || _isRightThumbCaptured)
			{
				float dx = x - _mLastTouchX;
				if (_isLeftThumbCaptured)
				{
					MoveLeftThumb(dx);
				}
				else if (_isRightThumbCaptured)
				{
					MoveRightThumb(dx);
				}
				CalculateValues();
			}
		}

		private void MoveLeftThumb(float dx)
		{
			float num = _thumbLeft.GetX() + dx;
			if (num < 0f)
			{
				num = 0f;
			}
			else if (num > _thumbRight.GetX() - (float)_thumbSize)
			{
				num = _thumbRight.GetX() - (float)_thumbSize;
			}
			_thumbLeft.SetX(num);
			_track.SetX((int)((double)num + (double)_thumbSize / 2.0));
			ViewGroup.LayoutParams layoutParameters = _track.LayoutParameters;
			layoutParameters.Width = (int)(_thumbRight.GetX() - num);
			_track.LayoutParameters = layoutParameters;
		}

		private void MoveRightThumb(float dx)
		{
			float num = _thumbRight.GetX() + dx;
			if (num < _thumbLeft.GetX() + (float)_thumbSize)
			{
				num = _thumbLeft.GetX() + (float)_thumbSize;
			}
			else if (num > (float)(base.Width - _thumbSize))
			{
				num = base.Width - _thumbSize;
			}
			_thumbRight.SetX(num);
			ViewGroup.LayoutParams layoutParameters = _track.LayoutParameters;
			layoutParameters.Width = (int)(num - _thumbLeft.GetX());
			_track.LayoutParameters = layoutParameters;
		}

		private void CalculateValues()
		{
			float num = _thumbLeft.GetX() / (float)(base.Width - _thumbSize);
			SelectedMinValue = (MaxValue - MinValue) * (double)num + MinValue;
			float num2 = _thumbRight.GetX() / (float)(base.Width - _thumbSize);
			SelectedMaxValue = (MaxValue - MinValue) * (double)num2 + MinValue;
			GT.Core.Log.Info($"{SelectedMinValue} <=======> {SelectedMaxValue}");
		}

		public void Reset()
		{
			GT.Core.Log.Info("Reset slider");
			SelectedMinValue = MinValue;
			SelectedMaxValue = MaxValue;
			MoveLeftThumb(0f - _thumbLeft.GetX());
			MoveRightThumb(base.Width);
		}

		public void SetSelection(double minValue, double maxValue)
		{
			_initMinValue = minValue;
			_initMaxValue = maxValue;
			_setInitSelection = true;
		}

		private void SetSelection()
		{
			if (_setInitSelection)
			{
				double num = (_initMinValue - MinValue) / (MaxValue - MinValue);
				MoveLeftThumb((float)(num * (double)(base.Width - _thumbSize)));
				double num2 = (_initMaxValue - MaxValue) / (MaxValue - MinValue);
				MoveRightThumb((float)(num2 * (double)(base.Width - _thumbSize)));
				SelectedMinValue = _initMinValue;
				SelectedMaxValue = _initMaxValue;
			}
		}

		protected override void OnLayout(bool changed, int l, int t, int r, int b)
		{
			base.OnLayout(changed, l, t, r, b);
			if (changed && r - l > 0)
			{
				SetSelection();
			}
		}
	}
	public class GTRecyclerView : RecyclerView
	{
		private GTRecyclerViewAdapter _adapter;

		private readonly System.Collections.IList _dataSource = new List<object>();

		public int HeaderTemplate { get; set; }

		public int ItemTemplate { get; set; }

		public Type ItemType { get; set; }

		public System.Collections.IList DataSource
		{
			get
			{
				return _dataSource;
			}
			set
			{
				_dataSource.Clear();
				if (value != null)
				{
					foreach (object item in value)
					{
						_dataSource.Add(item);
					}
				}
				Update();
			}
		}

		public object HeaderModel { get; set; }

		public ICommand SelectionCommand { get; set; }

		public Dictionary<string, List<ViewBindingInfo>> Bindings { get; private set; }

		public GTRecyclerView(Context context)
			: base(context)
		{
			Initialize(null);
		}

		public GTRecyclerView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize(attrs);
		}

		public GTRecyclerView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize(attrs);
		}

		private void Initialize(IAttributeSet attrs)
		{
			Bindings = new Dictionary<string, List<ViewBindingInfo>>();
		}

		public void Bind(int viewId, string viewPropertyName, string vmPropertyName, Func<object, object> converter = null)
		{
			if (!Bindings.ContainsKey(vmPropertyName))
			{
				Bindings[vmPropertyName] = new List<ViewBindingInfo>();
			}
			Bindings[vmPropertyName].Add(new ViewBindingInfo(viewId, viewPropertyName, converter));
		}

		public void UpdateHeader()
		{
			if (IsAdapterSet())
			{
				_adapter.NotifyItemChanged(0);
			}
		}

		protected virtual void Update()
		{
			if (IsAdapterSet())
			{
				_adapter.NotifyDataSetChanged();
			}
		}

		private bool IsAdapterSet()
		{
			if (_adapter != null)
			{
				return true;
			}
			_adapter = new GTRecyclerViewAdapter(this);
			SetAdapter(_adapter);
			return false;
		}
	}
	public class GTRecyclerViewAdapter : RecyclerView.Adapter
	{
		private readonly GTRecyclerView _view;

		public override int ItemCount => ((_view.HeaderTemplate > 0) ? 1 : 0) + (_view.DataSource?.Count ?? 0);

		public GTRecyclerViewAdapter(GTRecyclerView view)
		{
			_view = view;
		}

		public override int GetItemViewType(int position)
		{
			if (position == 0 && _view.HeaderTemplate > 0)
			{
				return _view.HeaderTemplate;
			}
			return _view.ItemTemplate;
		}

		public override void OnBindViewHolder(RecyclerView.ViewHolder holder, int position)
		{
			if (holder is GTListViewHolder gTListViewHolder)
			{
				gTListViewHolder.Update(model: (position == 0 && _view.HeaderTemplate > 0) ? _view.HeaderModel : ((_view.HeaderTemplate <= 0) ? _view.DataSource[position] : _view.DataSource[position - 1]), bindings: _view.Bindings);
			}
		}

		public override RecyclerView.ViewHolder OnCreateViewHolder(ViewGroup parent, int viewType)
		{
			return new GTListViewHolder((_view.ItemType == null || viewType == _view.HeaderTemplate) ? LayoutInflater.From(parent.Context).Inflate(viewType, parent, attachToRoot: false) : (Activator.CreateInstance(_view.ItemType, _view.Context) as View), _view.SelectionCommand);
		}
	}
	public class GTSlider : RelativeLayout
	{
		private int _thumbSize;

		private View _thumb;

		private View _track;

		private View _trackBackground;

		private float _mLastTouchX;

		private bool _isThumbCaptured;

		private double _value;

		private double _minValue;

		private double _maxValue = 1.0;

		public double MinValue
		{
			get
			{
				return _minValue;
			}
			set
			{
				_minValue = value;
				ResetThumb();
			}
		}

		public double MaxValue
		{
			get
			{
				return _maxValue;
			}
			set
			{
				_maxValue = value;
				ResetThumb();
			}
		}

		public double Value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
			}
		}

		public bool ResetToMinimum { get; set; } = true;

		public event EventHandler<SliderValueChanged> ValueChanged;

		public GTSlider(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTSlider(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTSlider(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			_thumbSize = 40.FromDPToPx(base.Context);
			int h = 10.FromDPToPx(base.Context);
			LayoutParams layoutParams = new LayoutParams(0, h)
			{
				MarginStart = _thumbSize / 2,
				MarginEnd = _thumbSize / 2
			};
			layoutParams.AddRule(LayoutRules.CenterVertical);
			_track = new View(base.Context);
			_track.SetBackgroundResource(2131165357);
			LayoutParams layoutParams2 = new LayoutParams(-1, h)
			{
				MarginStart = _thumbSize / 2,
				MarginEnd = _thumbSize / 2
			};
			layoutParams2.AddRule(LayoutRules.CenterVertical);
			_trackBackground = new View(base.Context);
			_trackBackground.SetBackgroundResource(2131165356);
			_thumb = new View(base.Context);
			LayoutParams layoutParams3 = new LayoutParams(_thumbSize, _thumbSize);
			layoutParams3.AddRule(LayoutRules.CenterVertical);
			_thumb.SetBackgroundResource(2131165686);
			AddView(_trackBackground, layoutParams2);
			AddView(_track, layoutParams);
			AddView(_thumb, layoutParams3);
		}

		public override bool OnTouchEvent(MotionEvent e)
		{
			float x = e.GetX();
			float y = e.GetY();
			switch (e.ActionMasked)
			{
			case MotionEventActions.Down:
				_isThumbCaptured = IsThumbContains(x, y);
				base.Parent?.RequestDisallowInterceptTouchEvent(disallowIntercept: true);
				break;
			case MotionEventActions.Move:
				if (_isThumbCaptured)
				{
					MoveThumb(x);
				}
				break;
			case MotionEventActions.Up:
				_isThumbCaptured = false;
				base.Parent?.RequestDisallowInterceptTouchEvent(disallowIntercept: false);
				break;
			}
			_thumb.SetBackgroundResource(_isThumbCaptured ? 2131165687 : 2131165686);
			_mLastTouchX = x;
			return true;
		}

		private bool IsThumbContains(float x, float y)
		{
			Rect rect = new Rect();
			_thumb.GetHitRect(rect);
			return rect.Contains((int)x, (int)y);
		}

		private void MoveThumb(float x)
		{
			float num = x - _mLastTouchX;
			float num2 = _thumb.GetX() + num;
			SetThumbX((int)num2);
			CalculateValue();
		}

		private void CalculateValue()
		{
			float num = _thumb.GetX() / (float)(base.Width - _thumbSize);
			SetValue((MaxValue - MinValue) * (double)num + MinValue);
		}

		private void SetValue(double value)
		{
			_value = value;
			this.ValueChanged?.Invoke(this, new SliderValueChanged(_value));
		}

		private void ResetThumb()
		{
			SetThumbX((!ResetToMinimum) ? (base.Width - _thumb.Width) : 0);
		}

		private void SetThumbX(int thumbX)
		{
			if (thumbX < 0)
			{
				thumbX = 0;
			}
			else if (thumbX > base.Width - _thumb.Width)
			{
				thumbX = base.Width - _thumb.Width;
			}
			ViewGroup.LayoutParams layoutParameters = _track.LayoutParameters;
			layoutParameters.Width = thumbX;
			_track.LayoutParameters = layoutParameters;
			_thumb.SetX(thumbX);
		}
	}
	public class GTStrengthStarsView : LinearLayout
	{
		private const int SIZE = 18;

		private static readonly Dictionary<string, int> _starImageIds = new Dictionary<string, int>();

		private int _starSize;

		private bool _lastForPLayer;

		private decimal _lastStrength;

		private decimal _strength;

		private bool _forPlayer = true;

		public decimal Strength
		{
			get
			{
				return _strength;
			}
			set
			{
				_strength = value;
				UpdateStrengthStars();
			}
		}

		public bool ForPlayer
		{
			get
			{
				return _forPlayer;
			}
			set
			{
				_forPlayer = value;
				UpdateStrengthStars();
			}
		}

		public GTStrengthStarsView(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTStrengthStarsView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTStrengthStarsView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			_starSize = 18.FromDPToPx(base.Context);
			Strength = 0m;
		}

		private void UpdateStrengthStars()
		{
			if (_lastStrength == Strength && _lastForPLayer == ForPlayer)
			{
				return;
			}
			_lastForPLayer = ForPlayer;
			_lastStrength = Strength;
			string[] strengthStars = Strength.GetStrengthStars(ForPlayer);
			if (ChildCount != strengthStars.Length)
			{
				RemoveAllViews();
				for (int i = 0; i < strengthStars.Length; i++)
				{
					ImageView imageView = new ImageView(base.Context)
					{
						LayoutParameters = new LayoutParams(_starSize, _starSize)
					};
					imageView.SetScaleType(ImageView.ScaleType.FitXy);
					AddView(imageView);
				}
				RequestLayout();
			}
			for (int j = 0; j < strengthStars.Length; j++)
			{
				if (GetChildAt(j) is ImageView imageView2)
				{
					if (!_starImageIds.TryGetValue(strengthStars[j], out var value))
					{
						value = strengthStars[j].GetImageId(base.Context);
						_starImageIds.Add(strengthStars[j], value);
					}
					imageView2.SetImageResource(value);
				}
			}
		}
	}
	public class GTSwitcher : FrameLayout
	{
		private const long _animationDuration = 250L;

		private AccelerateDecelerateInterpolator _interpolator;

		private View _handle;

		private TextView _labelYes;

		private TextView _labelNo;

		private View _container;

		private int _translation;

		private bool _isOn = true;

		public bool IsOn
		{
			get
			{
				return _isOn;
			}
			set
			{
				if (_isOn != value)
				{
					_isOn = value;
					RunAnimation();
				}
				_container.SetBackgroundResource(_isOn ? 2131166073 : 2131166072);
				OnValueChanged();
			}
		}

		public event EventHandler<SwitcherEventArgs> IsOnChanged;

		public GTSwitcher(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTSwitcher(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTSwitcher(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			LayoutInflater.From(base.Context).Inflate(2131492951, this, attachToRoot: true);
			_translation = 2131099845.ToSizeDP(base.Context);
			_container = FindViewById<View>(2131297637);
			_handle = FindViewById<View>(2131297638);
			_labelYes = FindViewById<TextView>(2131297640);
			_labelNo = FindViewById<TextView>(2131297639);
			_labelNo.Alpha = 0f;
			_interpolator = new AccelerateDecelerateInterpolator();
			base.Click += OnClick;
			SoundEffectsEnabled = false;
		}

		private void OnClick(object sender, EventArgs e)
		{
			IsOn = !IsOn;
			ComponentFactory.Resolve<ISoundManager>().PlaySound(Sounds.Button);
		}

		private void RunAnimation()
		{
			_handle.Animate().SetDuration(250L).SetInterpolator(_interpolator)
				.TranslationX((!IsOn) ? _translation : 0);
			_labelNo.Animate().SetDuration(250L).Alpha((!IsOn) ? 1 : 0);
			_labelYes.Animate().SetDuration(250L).Alpha(IsOn ? 1 : 0);
		}

		private void OnValueChanged()
		{
			this.IsOnChanged?.Invoke(this, new SwitcherEventArgs(IsOn));
		}
	}
	public class GTTableRowView : LinearLayout
	{
		private TableRow _row;

		public TableRow Row
		{
			get
			{
				return _row;
			}
			set
			{
				Update(value);
			}
		}

		public GTTableRowView(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTTableRowView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTTableRowView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			Orientation = Android.Widget.Orientation.Horizontal;
			int num = 5.FromDPToPx(base.Context);
			SetPadding(num, 0, num, 0);
			base.Click += OnRowClick;
			base.LongClick += OnRowLongClick;
			SoundEffectsEnabled = false;
		}

		private void OnRowClick(object sender, EventArgs e)
		{
			if (_row != null)
			{
				if (_row.Command != null && _row.Command.CanExecute(_row.CommandParameter))
				{
					_row.Command.Execute(_row.CommandParameter);
				}
				if (!string.IsNullOrEmpty(_row.TutorialControlId) && _row.ActivateTutorialControlOnTap)
				{
					TutorialManager.Instance.ControlActivated(_row.TutorialControlId);
				}
			}
		}

		private void OnRowLongClick(object sender, EventArgs e)
		{
			if (_row != null && _row.LongPressCommand != null && _row.LongPressCommand.CanExecute(_row.CommandParameter))
			{
				_row.LongPressCommand.Execute(_row.CommandParameter);
			}
		}

		public void SetIsEven(bool isEven)
		{
			int backgroundResource;
			if (isEven)
			{
				if (!_row.IsSelected && _row.Background == TableRowBackground.Warning)
				{
					backgroundResource = 2131165867;
				}
				else if (!_row.IsSelected && _row.Background == TableRowBackground.Inactive)
				{
					backgroundResource = 2131165862;
				}
				else if (!_row.IsSelected && _row.Background == TableRowBackground.New)
				{
					backgroundResource = 2131165864;
				}
				else
				{
					if (_row.IsSelected)
					{
						goto IL_0108;
					}
					backgroundResource = 2131165861;
				}
			}
			else if (!_row.IsSelected && _row.Background == TableRowBackground.Warning)
			{
				backgroundResource = 2131165868;
			}
			else if (!_row.IsSelected && _row.Background == TableRowBackground.Inactive)
			{
				backgroundResource = 2131165863;
			}
			else if (!_row.IsSelected && _row.Background == TableRowBackground.New)
			{
				backgroundResource = 2131165865;
			}
			else
			{
				if (_row.IsSelected)
				{
					goto IL_0108;
				}
				backgroundResource = 2131165866;
			}
			goto IL_010e;
			IL_0108:
			backgroundResource = 2131165341;
			goto IL_010e;
			IL_010e:
			SetBackgroundResource(backgroundResource);
		}

		public void CreateCells(HeaderRow headerRow, bool isHeader, int rowHeight)
		{
			if (rowHeight > -1)
			{
				LayoutParameters = new ViewGroup.LayoutParams(-1, isHeader ? (-1) : rowHeight.FromDPToPx(base.Context));
			}
			SetMinimumHeight(30.FromDPToPx(base.Context));
			Enabled = !isHeader;
			if (headerRow.Cells == null)
			{
				return;
			}
			foreach (HeaderCell cell in headerRow.Cells)
			{
				View view = (isHeader ? LayoutInflater.From(base.Context).Inflate(2131493190, null, attachToRoot: false) : GetCellView(cell.CellType));
				if (cell.IsSquare)
				{
					int num = rowHeight.FromDPToPx(base.Context);
					view.SetMinimumWidth(num);
					view.LayoutParameters = new LayoutParams(num, -1);
				}
				else
				{
					view.LayoutParameters = new LayoutParams(0, -1, cell.Width);
				}
				if (isHeader && !string.IsNullOrEmpty(cell.Text) && view is TextView textView)
				{
					textView.Text = cell.Text;
					textView.Gravity = cell.Alignment.ToGravity();
				}
				AddView(view);
			}
		}

		private View GetCellView(CellType cellType)
		{
			return cellType switch
			{
				CellType.Avatar => new PlayerRoundAvatar(base.Context), 
				CellType.TextTimer => new TextTimer(base.Context), 
				CellType.Strength => new StrengthView(base.Context), 
				CellType.Button => new ButtonCellView(base.Context), 
				CellType.NameBid => new NameBidView(base.Context), 
				CellType.Timer => new BaseTimer(base.Context), 
				CellType.ImageButton => new ImageButtonCellView(base.Context), 
				CellType.PlayerInfo => new PlayerInfoCellView(base.Context), 
				CellType.TeamInfo => new TeamInfoCellView(base.Context), 
				CellType.TitleSubtitle => new TitleSubtitleCellView(base.Context), 
				CellType.MultiText => new MultiTextCellView(base.Context), 
				CellType.Image => new ImageCellView(base.Context), 
				CellType.ImageText => new ImageTextCellView(base.Context), 
				CellType.ButtonTimer => new ButtonTimerCellView(base.Context), 
				_ => new TextCellView(base.Context), 
			};
		}

		public void Update(TableRow row)
		{
			_row = row;
			Tag = ((!string.IsNullOrEmpty(row.TutorialControlId)) ? row.TutorialControlId : null);
			Enabled = _row.Command != null || _row.LongPressCommand != null;
			for (int i = 0; i < row.Cells.Count; i++)
			{
				if (GetChildAt(i) is ICellView cellView)
				{
					cellView.Update(row.Cells[i]);
				}
			}
		}
	}
	public class GTTableView : FrameLayout
	{
		private readonly List<ITableRow> _rows = new List<ITableRow>();

		private FrameLayout _header;

		private RecyclerView _listView;

		private TextView _messageLabel;

		private GTTableViewAdapter _adapter;

		public HeaderRow HeaderRow { get; set; }

		public int RowHeight { get; set; } = 40;

		public List<ITableRow> Rows
		{
			get
			{
				return _rows;
			}
			set
			{
				_rows.Clear();
				if (value != null)
				{
					_rows.AddRange(value);
				}
				Update();
				UpdateNoDataMessage();
			}
		}

		public string NoDataMessage
		{
			get
			{
				return _messageLabel.Text;
			}
			set
			{
				_messageLabel.Text = value;
				UpdateNoDataMessage();
			}
		}

		public GTTableView(Context context)
			: base(context)
		{
			Initialize();
		}

		public GTTableView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GTTableView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493188, this, attachToRoot: true);
			_header = view.FindViewById<FrameLayout>(2131297651);
			_messageLabel = view.FindViewById<TextView>(2131297654);
			_listView = view.FindViewById<RecyclerView>(2131297653);
			_listView.SetLayoutManager(new GTListViewLayoutManager(base.Context, IsInEditMode));
		}

		public void ScrollToPosition(int index)
		{
			_listView.SmoothScrollToPosition(index);
		}

		private void Update()
		{
			if (HeaderRow == null)
			{
				throw new NullReferenceException("Header row should not be null - it is used to calculate cells width");
			}
			if (_header.ChildCount == 0)
			{
				GTTableRowView gTTableRowView = new GTTableRowView(base.Context);
				gTTableRowView.CreateCells(HeaderRow, isHeader: true, RowHeight);
				_header.AddView(gTTableRowView);
			}
			if (_adapter == null)
			{
				_adapter = new GTTableViewAdapter(this);
				_listView.SetAdapter(_adapter);
			}
			else
			{
				_adapter.NotifyDataSetChanged();
			}
		}

		public void SetHeaderHeight(int value)
		{
			_header.LayoutParameters = new LinearLayout.LayoutParams(_header.Width, value.FromDPToPx(base.Context));
		}

		public void SetHeaderColor(int colorId)
		{
			_header.SetBackgroundResource(colorId);
		}

		private void UpdateNoDataMessage()
		{
			_messageLabel.Visibility = (!string.IsNullOrEmpty(_messageLabel.Text) && (Rows == null || Rows.Count == 0)).ToVisibility();
		}

		public void GetItemLocation(ITableRow row, int[] location)
		{
			for (int i = 0; i < _listView.ChildCount; i++)
			{
				View childAt = _listView.GetChildAt(i);
				if (childAt is GTTableRowView gTTableRowView && gTTableRowView.Row == row)
				{
					childAt.GetLocationOnScreen(location);
					break;
				}
			}
		}
	}
	public class GTTableViewAdapter : RecyclerView.Adapter
	{
		private readonly List<ITableRow> _rows;

		private readonly Context _context;

		private readonly HeaderRow _headerRow;

		private readonly int _rowHeight;

		public override int ItemCount => _rows?.Count ?? 0;

		public GTTableViewAdapter(GTTableView tableView)
		{
			_context = tableView.Context;
			_headerRow = tableView.HeaderRow;
			_rows = tableView.Rows;
			_rowHeight = tableView.RowHeight;
		}

		public override void OnBindViewHolder(RecyclerView.ViewHolder holder, int position)
		{
			if (position >= 0 && position < _rows.Count)
			{
				if (holder is GTTableViewHolder gTTableViewHolder)
				{
					gTTableViewHolder.Update(_rows[position] as TableRow, position % 2 == 0);
				}
				else if (holder is GTTableSectionViewHolder gTTableSectionViewHolder)
				{
					gTTableSectionViewHolder.Update(_rows[position] as SectionRow);
				}
			}
		}

		public override RecyclerView.ViewHolder OnCreateViewHolder(ViewGroup parent, int viewType)
		{
			if (viewType == 0)
			{
				GTTableRowView gTTableRowView = new GTTableRowView(_context);
				gTTableRowView.CreateCells(_headerRow, isHeader: false, _rowHeight);
				return new GTTableViewHolder(gTTableRowView);
			}
			return new GTTableSectionViewHolder(LayoutInflater.From(_context).Inflate(2131493187, null, attachToRoot: false));
		}

		public override int GetItemViewType(int position)
		{
			if (_rows[position] is SectionRow)
			{
				return 1;
			}
			return 0;
		}
	}
