	public class PageScrollView : ViewPager
	{
		private class PageScrollAdapter : PagerAdapter
		{
			private readonly List<View> _children;

			public override int Count => _children.Count;

			public PageScrollAdapter(List<View> children)
			{
				_children = children;
			}

			public override bool IsViewFromObject(View view, Java.Lang.Object obj)
			{
				return view == obj;
			}

			public override Java.Lang.Object InstantiateItem(ViewGroup container, int position)
			{
				View view = _children[position];
				container.AddView(view);
				return view;
			}

			public override void DestroyItem(ViewGroup container, int position, Java.Lang.Object view)
			{
				container.RemoveView((View)view);
			}
		}

		private List<View> _children;

		private PageScrollAdapter _adapter;

		public int TabsCount => _children?.Count ?? 0;

		public bool HasLeftInset { get; set; }

		public bool HasRightInset { get; set; }

		public PageScrollView(Context context)
			: base(context)
		{
			Initialize();
		}

		public PageScrollView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		private void Initialize()
		{
			_children = new List<View>();
			_adapter = new PageScrollAdapter(_children);
			Adapter = _adapter;
			_ = IsInEditMode;
		}

		public void UpdateInsets()
		{
			if (!HasLeftInset && !HasRightInset)
			{
				return;
			}
			EdgeInsets safeAreaInsets = ComponentFactory.Resolve<IDeviceService>().SafeAreaInsets;
			if (safeAreaInsets.Left == 0f && safeAreaInsets.Right == 0f)
			{
				return;
			}
			foreach (View view in GetViews())
			{
				if (view is ViewGroup viewGroup)
				{
					viewGroup.SetPadding(HasLeftInset ? ((int)safeAreaInsets.Left) : 0, viewGroup.PaddingTop, HasRightInset ? ((int)safeAreaInsets.Right) : 0, viewGroup.PaddingBottom);
				}
			}
		}

		public void AddTab(View view)
		{
			_children.Add(view);
			Adapter.NotifyDataSetChanged();
		}

		public void RemoveTab(int index)
		{
			if (index >= 0 && index < _children.Count)
			{
				_children.RemoveAt(index);
				Adapter.NotifyDataSetChanged();
			}
		}

		public List<View> GetViews()
		{
			return _children;
		}
	}
	public class PlayerInfoCellView : FrameLayout, ICellView
	{
		private TextView _playerName;

		private GTStrengthStarsView _playerStars;

		private MultiImageView _playerYellowCards;

		private ImageView _playerRedCard;

		private ImageView _playerInjured;

		private ImageView _playerForSell;

		private ImageView _shirt;

		private TextView _number;

		private TextView _strengthText;

		private bool _isSmallScreen;

		public PlayerInfoCellView(Context context)
			: base(context)
		{
			Initialize();
		}

		public PlayerInfoCellView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public PlayerInfoCellView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize();
		}

		public PlayerInfoCellView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
			Initialize();
		}

		protected PlayerInfoCellView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493116, this, attachToRoot: true);
			_playerName = view.FindViewById<TextView>(2131297326);
			_playerStars = view.FindViewById<GTStrengthStarsView>(2131297327);
			_playerYellowCards = view.FindViewById<MultiImageView>(2131297336);
			_playerRedCard = view.FindViewById<ImageView>(2131297333);
			_playerInjured = view.FindViewById<ImageView>(2131297331);
			_playerForSell = view.FindViewById<ImageView>(2131297330);
			_shirt = view.FindViewById<ImageView>(2131297334);
			_number = view.FindViewById<TextView>(2131297332);
			_strengthText = view.FindViewById<TextView>(2131297335);
			_playerStars.ForPlayer = true;
			int item = base.Context.GetScreenSize().Item1;
			_isSmallScreen = item < 1000;
			GT.Core.Log.Info($"Screen width = {item} (Small = {_isSmallScreen})");
		}

		public void Update(TableCell tableCell)
		{
			if (tableCell is PlayerInfoCell playerInfoCell)
			{
				string text = string.Empty;
				if (!playerInfoCell.IsShirtVisible && playerInfoCell.ShirtNumber >= 0)
				{
					text = $"{playerInfoCell.ShirtNumber}. ";
				}
				_playerName.Text = text + playerInfoCell.Name;
				_playerStars.Strength = playerInfoCell.Strength;
				_strengthText.Text = $"{playerInfoCell.Strength:N1}";
				_strengthText.Visibility = (playerInfoCell.IsStrengthNumberVisible && !_isSmallScreen).ToVisibility();
				_playerRedCard.Visibility = playerInfoCell.HasRedCard.ToVisibility();
				_playerInjured.Visibility = ((playerInfoCell.Injured <= 0) ? ViewStates.Gone : ViewStates.Visible);
				_playerForSell.Visibility = playerInfoCell.IsForSale.ToVisibility();
				_playerName.SetTextColor(playerInfoCell.NameColor.ToColor(base.Context));
				if (playerInfoCell.YellowCards > 0)
				{
					_playerYellowCards.Visibility = ViewStates.Visible;
					_playerYellowCards.ImageName = "live_yellowcard";
					_playerYellowCards.Repeats = playerInfoCell.YellowCards;
				}
				else
				{
					_playerYellowCards.Visibility = ViewStates.Gone;
				}
				ImageView shirt = _shirt;
				ViewStates visibility = (_number.Visibility = (playerInfoCell.IsShirtVisible && playerInfoCell.ShirtNumber >= 0).ToVisibility());
				shirt.Visibility = visibility;
				_shirt.SetImageResource(playerInfoCell.ShirtName.GetTrikotId(base.Context));
				_number.Text = playerInfoCell.ShirtNumber.ToString();
			}
		}
	}
