	public class TabHeaderView : FrameLayout
	{
		private List<TabButton> _tabs;

		public event Action<int> TabClicked;

		public TabHeaderView(Context context)
			: base(context)
		{
			Initialize();
		}

		public TabHeaderView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public TabHeaderView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			_tabs = new List<TabButton>();
			LinearLayout linearLayout = LayoutInflater.FromContext(base.Context).Inflate(2131493185, this, attachToRoot: true).FindViewById<LinearLayout>(2131297655);
			for (int i = 0; i < linearLayout.ChildCount; i++)
			{
				TabButton tabButton = linearLayout.GetChildAt(i) as TabButton;
				_tabs.Add(tabButton);
				tabButton.Visibility = ViewStates.Gone;
				tabButton.Click += Button_Click;
			}
		}

		private void Button_Click(object sender, EventArgs e)
		{
			if (!(sender is TabButton { Selected: false } tabButton))
			{
				return;
			}
			int obj = _tabs.IndexOf(tabButton);
			foreach (TabButton tab in _tabs)
			{
				tab.Selected = false;
			}
			tabButton.Selected = true;
			this.TabClicked?.Invoke(obj);
			if (!string.IsNullOrEmpty(tabButton.Tag?.ToString()))
			{
				TutorialManager.Instance.ControlActivated(tabButton.Tag.ToString());
			}
		}

		private bool BadIndex(int index)
		{
			if (index >= 0)
			{
				return index >= _tabs.Count;
			}
			return true;
		}

		public void SetActive(int index, bool value)
		{
			if (!BadIndex(index))
			{
				_tabs[index].Selected = value;
			}
		}

		public void SetTitle(int index, string text)
		{
			if (!BadIndex(index))
			{
				_tabs[index].Title = text;
				ShowTab(index);
			}
		}

		public void SetNotificationsCount(int index, int count)
		{
			if (!BadIndex(index))
			{
				_tabs[index].NotificationsCount = count;
				ShowTab(index);
			}
		}

		public void SetTag(int index, string tag)
		{
			if (!BadIndex(index))
			{
				_tabs[index].Tag = tag;
			}
		}

		public void ShowTab(int index)
		{
			if (!BadIndex(index))
			{
				_tabs[index].Visibility = ViewStates.Visible;
			}
		}

		public void HideTab(int index)
		{
			if (!BadIndex(index))
			{
				_tabs[index].Visibility = ViewStates.Gone;
			}
		}
	}
