	public class TabsView : FrameLayout
	{
		private TabHeaderView _tabHeader;

		private PageScrollView _tabScrollView;

		private INavigationService _navigationService;

		private int _previousTabIndex;

		public bool HasLeftInset
		{
			get
			{
				return _tabScrollView.HasLeftInset;
			}
			set
			{
				_tabScrollView.HasLeftInset = value;
			}
		}

		public bool HasRightInset
		{
			get
			{
				return _tabScrollView.HasRightInset;
			}
			set
			{
				_tabScrollView.HasRightInset = value;
			}
		}

		public int TabsCount { get; private set; }

		public TabsView(Context context)
			: base(context)
		{
			Initialize();
		}

		public TabsView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public TabsView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			LayoutInflater.FromContext(base.Context).Inflate(2131493191, this, attachToRoot: true);
			_tabHeader = FindViewById<TabHeaderView>(2131297645);
			_tabScrollView = FindViewById<PageScrollView>(2131297647);
			_tabHeader.TabClicked += OnTabClicked;
			_tabScrollView.PageSelected += OnPageSelected;
			if (!IsInEditMode)
			{
				_navigationService = ComponentFactory.Resolve<INavigationService>();
			}
		}

		private void OnPageSelected(object sender, ViewPager.PageSelectedEventArgs e)
		{
			OnScrolledToPage(e.Position);
		}

		private void OnTabClicked(int page)
		{
			_tabScrollView.SetCurrentItem(page, smoothScroll: true);
			_navigationService.ReportTabChanged(page);
		}

		public void AddTab(string text, View view, string tag = null)
		{
			_tabScrollView.AddTab(view);
			if (!string.IsNullOrEmpty(tag))
			{
				_tabHeader.SetTag(TabsCount, tag);
			}
			_tabHeader.SetTitle(TabsCount, text);
			_tabHeader.SetActive(TabsCount, TabsCount == 0);
			TabsCount++;
		}

		public void RemoveTab(int index)
		{
			if (index >= 0 && index < TabsCount)
			{
				if (index == _tabScrollView.CurrentItem && index != 0)
				{
					SelectTab(0);
				}
				_tabHeader.HideTab(index);
				_tabScrollView.RemoveTab(index);
				TabsCount--;
			}
		}

		public void SetTabTitle(int index, string text)
		{
			_tabHeader.SetTitle(index, text);
		}

		public void SetTabNotificationsCount(int index, int count)
		{
			_tabHeader.SetNotificationsCount(index, count);
		}

		public void SelectTab(int page)
		{
			_tabScrollView.SetCurrentItem(page, smoothScroll: false);
			OnScrolledToPage(page);
		}

		public List<View> GetViews()
		{
			return _tabScrollView.GetViews();
		}

		public View GetSelectedTab()
		{
			List<View> views = GetViews();
			if (views != null && views.Any() && GetViews().Count > _tabScrollView.CurrentItem)
			{
				return GetViews()[_tabScrollView.CurrentItem];
			}
			return null;
		}

		private void OnScrolledToPage(int page)
		{
			for (int i = 0; i < TabsCount; i++)
			{
				_tabHeader.SetActive(i, i == page);
			}
			_navigationService.ReportTabChanged(page);
			OnTabSelected(page);
		}

		private void OnTabSelected(int selectedTabIndex)
		{
			List<View> views = GetViews();
			if (_previousTabIndex != selectedTabIndex && views.Count > _previousTabIndex && views[_previousTabIndex] is ITabView tabView)
			{
				tabView.OnTabDisappearing();
			}
			_previousTabIndex = _tabScrollView.CurrentItem;
		}
	}
