		public static void AddTouchEffect(this View view)
		{
			Drawable background = view.Background;
			if (background != null)
			{
				Drawable drawable = background.WithFade(128);
				StateListDrawable stateListDrawable = new StateListDrawable();
				stateListDrawable.AddState(new int[1] { 16842919 }, drawable);
				stateListDrawable.AddState(new int[0], background);
				view.Background = stateListDrawable;
			}
		}

		public static string GetBase64(this View view)
		{
			return BitmapToBase64(GetBitmapFromView_2(view));
		}

		private static string BitmapToBase64(Bitmap bitmap)
		{
			MemoryStream memoryStream = new MemoryStream();
			bitmap.Compress(Bitmap.CompressFormat.Png, 100, memoryStream);
			return Base64.EncodeToString(memoryStream.ToArray(), Base64Flags.Default);
		}

		private static Bitmap GetBitmapFromView_2(View view)
		{
			int size = 0;
			int size2 = 0;
			MeasureSpecMode mode = MeasureSpecMode.Unspecified;
			if (view.LayoutParameters != null)
			{
				size = view.LayoutParameters.Width;
				size2 = view.LayoutParameters.Height;
				mode = MeasureSpecMode.Exactly;
			}
			view.Measure(View.MeasureSpec.MakeMeasureSpec(size, mode), View.MeasureSpec.MakeMeasureSpec(size2, mode));
			int measuredWidth = view.MeasuredWidth;
			int measuredHeight = view.MeasuredHeight;
			Bitmap bitmap = Bitmap.CreateBitmap(measuredWidth, measuredHeight, Bitmap.Config.Argb8888);
			Canvas canvas = new Canvas(bitmap);
			view.Layout(0, 0, measuredWidth, measuredHeight);
			view.Background?.Draw(canvas);
			view.Draw(canvas);
			return bitmap;
		}
	}
