	public class PopupService : IPopupService
	{
		private readonly MainActivity _mainActivity;

		private IShell _shell;

		private ViewManager _viewManager;

		private View _currentTutorialPopup;

		private string TextInfo => "Info".Translate();

		private string TextOk => "Ok".Translate();

		private string TextOops => "Oops".Translate();

		private string TextNoGTStars => "NoGTStarsMessage".Translate();

		private string TextBuyGTStars => "Stars".Translate();

		private string TextNoMedipacks => "NoMedipacksMessage".Translate();

		private string TextBuyMedipacks => "BuyMedipacks".Translate();

		private string TextNoMoney => "NoMoneyMessage".Translate();

		private string TextErrorMessage => "ErrorMessage".Translate();

		private string TextYes => "Yes".Translate();

		private string TextNo => "No".Translate();

		private IShell Shell => _shell ?? (_shell = ComponentFactory.Resolve<IShell>());

		private ViewManager ViewManager => _viewManager ?? (_viewManager = ComponentFactory.Resolve<ViewManager>());

		public PopupService(MainActivity mainActivity)
		{
			_mainActivity = mainActivity;
		}

		public void DisplayNoGTStars()
		{
			ShowDialogPopup(TextOops, TextNoGTStars, TextBuyGTStars, TextOk, delegate
			{
				GoToShop(0);
			}, null, GT.Core.Character.Anna, ButtonType.Standart).FireAndForgetSafeAsync();
		}

		public void DisplayNoMedipacks()
		{
			ShowDialogPopup(TextOops, TextNoMedipacks, TextBuyMedipacks, TextOk, delegate
			{
				GoToShop(2);
			}, null, GT.Core.Character.Anna, ButtonType.Standart).FireAndForgetSafeAsync();
		}

		public void DisplayNoMoney()
		{
			ShowInfoPopup(TextOops, TextNoMoney, null, GT.Core.Character.Anna).FireAndForgetSafeAsync();
		}

		public async Task ShowErrorIfAny(IResponseObject response, GT.Core.Character character = GT.Core.Character.Coach)
		{
			if (response != null && response.Status != ResponseStatus.OK && response.Status != ResponseStatus.AuthenticationError && !string.IsNullOrEmpty(response.ErrorMessage) && response.ErrorMessage.ToLower() != "failed")
			{
				GT.Core.Log.Info("Will show error = " + response.ErrorMessage);
				await ShowInfoPopup(TextOops, response.ErrorMessage, null, character);
			}
		}

		public void ShowErrorMessage(string message = "", GT.Core.Character character = GT.Core.Character.Coach)
		{
			ShowErrorMessageAsync(message, character).FireAndForgetSafeAsync();
		}

		public async Task ShowErrorMessageAsync(string message = "", GT.Core.Character character = GT.Core.Character.Coach)
		{
			if (string.IsNullOrEmpty(message))
			{
				message = TextErrorMessage;
			}
			await ShowInfoPopup(TextOops, message, null, character);
		}

		public void ShowOkMessage(string message, GT.Core.Character character = GT.Core.Character.Coach)
		{
			ShowOkMessage(TextInfo, message, character);
		}

		public void ShowOkMessage(string title, string message, GT.Core.Character character = GT.Core.Character.Coach)
		{
			ShowInfoPopup(title, message, null, character).FireAndForgetSafeAsync();
		}

		public void ShowOkMessage(string title, string message, string buttonText, Action buttonAction, GT.Core.Character character = GT.Core.Character.Coach)
		{
			ShowInfoPopup(title, message, buttonText, character, buttonAction).FireAndForgetSafeAsync();
		}

		public async Task ShowOkMessageAsync(string title, string message, GT.Core.Character character = GT.Core.Character.Coach)
		{
			await ShowInfoPopup(title, message, TextOk, character);
		}

		public async Task ShowOkMessageAsync(string title, string message, string buttonText, GT.Core.Character character = GT.Core.Character.Coach)
		{
			await ShowInfoPopup(title, message, buttonText, character);
		}

		public void ShowYesNoMessage(string title, string message, Action yesEvent)
		{
			ShowYesNoMessage(title, message, TextYes, TextNo, yesEvent, null);
		}

		public void ShowYesNoMessage(string title, string message, string yesText, string noText, Action yesEvent, Action noEvent, GT.Core.Character character = GT.Core.Character.Coach)
		{
			ShowDialogPopup(title, message, yesText, noText, yesEvent, noEvent, character).FireAndForgetSafeAsync();
		}

		public async Task<bool> ShowYesNoMessageAsync(string title, string message, GT.Core.Character character = GT.Core.Character.Coach)
		{
			return await ShowDialogPopup(title, message, TextYes, TextNo, null, null, character) == PopupResult.Done;
		}

		public async Task<PopupResult> ShowPopupAsync<T>(T popupViewModel) where T : BasePopupViewModel
		{
			Type viewType = ViewManager.GetViewType(typeof(T));
			if ((object)viewType != null)
			{
				if (popupViewModel.IsLoadingVisible)
				{
					Shell.StartProgress();
				}
				object obj = Activator.CreateInstance(viewType, _mainActivity);
				if (obj is BasePopup<T> basePopup)
				{
					if (popupViewModel.IsTutorialControlContainer)
					{
						SetTutorialPopup(basePopup);
					}
					basePopup.SetBindingContext(popupViewModel);
					await popupViewModel.Update();
					popupViewModel.ApplyBinding();
					Shell.StopProgress();
					_mainActivity.AddView(basePopup);
					PopupResult result = await basePopup.Show();
					if (popupViewModel.IsTutorialControlContainer)
					{
						ClearTutorialPopup();
					}
					return result;
				}
				Shell.StopProgress();
			}
			return PopupResult.None;
		}

		private void SetTutorialPopup(View popup)
		{
			_currentTutorialPopup = popup;
		}

		private void ClearTutorialPopup()
		{
			_currentTutorialPopup = null;
		}

		public object GetTutorialPopup()
		{
			return _currentTutorialPopup;
		}

		public void ShowToast(string message)
		{
			Toast.MakeText((Context)(object)_mainActivity, message, ToastLength.Short).Show();
		}

		private async Task<PopupResult> ShowInfoPopup(string title, string message, string buttonText = null, GT.Core.Character character = GT.Core.Character.Coach, Action buttonCallback = null)
		{
			PopupResult num = await ShowPopupAsync(new InfoPopupViewModel
			{
				Title = title,
				Message = message,
				ConfirmButtonTitle = (string.IsNullOrEmpty(buttonText) ? TextOk : buttonText),
				Character = character
			});
			if (num == PopupResult.Done)
			{
				buttonCallback?.Invoke();
			}
			return num;
		}

		private async Task<PopupResult> ShowDialogPopup(string title, string message, string yesText, string noText, Action yesEvent, Action noEvent, GT.Core.Character character = GT.Core.Character.Coach, ButtonType noButtonType = ButtonType.Cancel)
		{
			PopupResult popupResult = await ShowPopupAsync(new DialogPopupViewModel
			{
				Title = title,
				Message = message,
				ConfirmButtonTitle = yesText,
				CancelButtonTitle = noText,
				CancelButtonType = noButtonType,
				Character = character
			});
			switch (popupResult)
			{
			case PopupResult.Done:
				yesEvent?.Invoke();
				break;
			case PopupResult.Canceled:
				noEvent?.Invoke();
				break;
			}
			return popupResult;
		}

		private void GoToShop(int tabIndex)
		{
			ComponentFactory.Resolve<INavigationService>().NavigateTo(ScreenIdentifier.Shop, tabIndex);
		}

		public async Task<string> ShowEntryPopupAsync(string title, string message, string buttonTitle)
		{
			EntryPopupViewModel entryPopup = new EntryPopupViewModel
			{
				Title = title,
				ConfirmButtonTitle = buttonTitle,
				Message = message
			};
			if (await ShowPopupAsync(entryPopup) != PopupResult.Done)
			{
				return string.Empty;
			}
			return entryPopup.EnteredText.Trim();
		}
	}
