			{
				Orientation = Android.Widget.Orientation.Horizontal,
				LayoutParameters = new LinearLayout.LayoutParams(-1, -2)
			};
			_stackItems.AddView(linearLayout);
			return linearLayout;
		}

		private void AddShelf(int bottom = 0)
		{
			ImageView imageView = new ImageView(base.Context)
			{
				LayoutParameters = new LinearLayout.LayoutParams(-1, (bottom == 0) ? _stackShelves.Width : bottom)
			};
			imageView.SetImageResource((bottom == 0) ? 2131165874 : 2131165875);
			imageView.SetScaleType(ImageView.ScaleType.CenterCrop);
			_stackShelves.AddView(imageView);
		}

		private void Update()
		{
			if (_stackShelves.Width <= 0 || Accomplishments == null)
			{
				return;
			}
			int width = _stackShelves.Width;
			int num = (int)((double)width * 0.07);
			int top = (int)((double)width * 0.05);
			int bottom = (int)((double)width * 0.01);
			int num2 = (int)((double)((width - num * 2) / 6) * 0.7);
			int num3 = width / 3;
			int height = num2 * 17 / 12;
			int num4 = (int)((double)width * (1.0 / 32.0));
			_stackItems.SetPadding(num, 0, num, 0);
			_stackShelves.RemoveAllViews();
			_stackItems.RemoveAllViews();
			int num5 = 3;
			int num6 = 6;
			LinearLayout linearLayout = null;
			foreach (AccomplishmentData accomplishment in Accomplishments)
			{
				if (num6 == 6)
				{
					linearLayout = AddRow();
					num6 = 1;
					if (num5 == 3)
					{
						AddShelf();
						num5 = 1;
					}
					else
					{
						num5++;
					}
				}
				else
				{
					num6++;
				}
				View view = LayoutInflater.From(base.Context).Inflate(2131492892, linearLayout, attachToRoot: false);
				view.LayoutParameters = new LinearLayout.LayoutParams(0, num3, 1f);
				view.SetPadding(0, top, 0, bottom);
				ImageView imageView = view.FindViewById<ImageView>(2131296257);
				imageView.LayoutParameters = new LayoutParams(num2, height)
				{
					Gravity = (GravityFlags.Bottom | GravityFlags.AxisSpecified)
				};
				imageView.SetImageResource(accomplishment.Image.GetAccomplishmentId(base.Context));
				view.FindViewById<TextView>(2131296258).Text = accomplishment.Name;
				linearLayout.AddView(view);
			}
			_height = (_stackShelves.ChildCount - 1) * width + num5 * num3 + num4;
			if (num5 == 3)
			{
				AddShelf(num4);
			}
			_needFix = _stackShelves.ChildCount == 1 && num5 == 1;
			if (_needFix && base.Height > 0)
			{
				FixShelf();
			}
			else
			{
				_stackShelves.LayoutParameters = new LayoutParams(-1, _height);
			}
		}

		private void FixShelf()
		{
			if (_needFix)
			{
				if (base.Height > _height)
				{
					_stackShelves.LayoutParameters = new LayoutParams(-1, base.Height);
				}
				_needFix = false;
			}
		}

		protected override void OnLayout(bool changed, int left, int top, int right, int bottom)
		{
			base.OnLayout(changed, left, top, right, bottom);
			if (changed)
			{
				Update();
				FixShelf();
			}
		}
	}
	public class BaseTabbedView<T> : BaseView<T>, IFullscreenView, ITabbedView where T : BaseViewModel
	{
		protected readonly TabsView TabsView;

		public BaseTabbedView(Context context)
			: base(context)
		{
			TabsView = new TabsView(context)
			{
				HasLeftInset = true,
				HasRightInset = true
			};
			SetContent(TabsView);
		}

		protected void AddTab(string name, View view, string tag = null)
		{
			TabsView.AddTab(name, view, tag);
		}

		public void SelectTab(int tabIndex)
		{
			TabsView.SelectTab(tabIndex);
		}

		protected void SetTabTitle(int tabIndex, string text)
		{
			TabsView.SetTabTitle(tabIndex, text);
		}

		protected void SetTabNotificationsCount(int tabIndex, int count)
		{
			TabsView.SetTabNotificationsCount(tabIndex, count);
		}

		public override void OnAppearing()
		{
			base.OnAppearing();
			foreach (View view in TabsView.GetViews())
			{
				if (view is ICleanView cleanView)
				{
					cleanView.OnAppearing();
				}
			}
		}

		public override void OnDisappearing()
		{
			base.OnDisappearing();
			foreach (View view in TabsView.GetViews())
			{
				if (view is ICleanView cleanView)
				{
					cleanView.OnDisappearing();
				}
				if (view is ITabView tabView)
				{
					tabView.OnTabDisappearing();
				}
			}
		}
	}
	public class BaseView<T> : BaseUIElement<T>, ICleanView where T : BaseViewModel
	{
		private bool _isInited;

		private IShell _shell;

		private List<ICleanView> _children;

		protected bool AutoFadeIn { get; set; } = true;

		public BaseView(Context context)
			: base(context)
		{
			Initialize();
		}

		public BaseView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public BaseView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			Alpha = 0f;
			_shell = ComponentFactory.Resolve<IShell>();
			SetBindingContext(ComponentFactory.Resolve<T>());
		}

		protected void AddChild(ICleanView view)
		{
			if (_children == null)
			{
				_children = new List<ICleanView>();
			}
			_children.Add(view);
		}

		public virtual void OnAppearing()
		{
			Start();
			Resume().FireAndForgetSafeAsync();
			_children?.ForEach(delegate(ICleanView x)
			{
				x.OnAppearing();
			});
		}

		private async Task Resume()
		{
			if (!_isInited)
			{
				_isInited = true;
				await base.ViewModel.Init();
				MakeAutoFadeIn();
			}
			else
			{
				MakeAutoFadeIn();
				await base.ViewModel.Update();
			}
			base.ViewModel.ApplyBinding();
			OnDidAppear();
		}

		private void MakeAutoFadeIn()
		{
			if (AutoFadeIn)
			{
				this.FadeIn();
			}
		}

		public virtual void OnDidAppear()
		{
			_children?.ForEach(delegate(ICleanView x)
			{
				x.OnDidAppear();
			});
		}

		public virtual void OnDisappearing()
		{
			Stop();
			base.ViewModel.Pause();
			_children?.ForEach(delegate(ICleanView x)
			{
				x.OnDisappearing();
			});
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "IsBusy")
			{
				if (base.ViewModel.IsBusy)
				{
					_shell.StartProgress();
				}
				else
				{
					_shell.StopProgress();
				}
			}
		}
	}
