			_lastMatchAwayStrength = view.FindViewById<GTStrengthStarsView>(2131296301);
			_lastMatchHomeStrength.ForPlayer = false;
			_lastMatchAwayStrength.ForPlayer = false;
			_lastMatchHomeStrength.Strength = 0m;
			_lastMatchAwayStrength.Strength = 0m;
			_activeButtonColor = Color.Rgb(255, 255, 255);
			_inactiveButtonColor = Color.Rgb(200, 200, 200);
			_lastMatchButton = view.FindViewById<Button>(2131296680);
			_nextMatchButton = view.FindViewById<Button>(2131296686);
			_lineupButton = view.FindViewById<Button>(2131297160);
			_compareButton = view.FindViewById<Button>(2131297156);
			AddTab("MyClub".Translate(), view, "tab_club");
			AddTab("Sponsors".Translate(), new SponsorsView(context), "tab_sponsors");
			AddMailList();
