			Bind(_lineupButton, base.ViewModel.ShowLineupCommand);
			Bind(_lineupButton, "Visibility", "IsNextMatchInfoVisible", (object x) => x.ToVisibility());
			Bind(_lastMatchButton, "Selected", "IsNextMatchSelected", (object x) => !(bool)x);
			Bind(_nextMatchButton, "Selected", "IsNextMatchSelected");
			Bind(view2, "Accomplishments", "Accomplishments");
			Bind(_lastMatchHomeStrength, "Strength", "LastMatch", (object x) => (x as MatchData)?.HomeStrength ?? 0);
			Bind(_lastMatchAwayStrength, "Strength", "LastMatch", (object x) => (x as MatchData)?.AwayStrength ?? 0);
			Bind(_lastMatchHomeStrength, "Visibility", "IsLastMatchInfoVisible", (object x) => x.ToVisibility());
			Bind(_lastMatchAwayStrength, "Visibility", "IsLastMatchInfoVisible", (object x) => x.ToVisibility());
