			Bind(view, 2131297155, "Text", "AwayTeamName");
			Bind(view, 2131297155, "Visibility", "AwayTeamName", (object x) => x.HideIfNullOrEmpty());
			Bind(view, 2131297157, "Text", "MatchDate");
			Bind(view, 2131296681, "DataSource", "ClubInfo");
		}

		private void AddMailList()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493047, null, attachToRoot: false);
			AddTab("Inbox".Translate(), view);
			GTTableView gTTableView = view.FindViewById<GTTableView>(2131297138);
			gTTableView.HeaderRow = base.ViewModel.MailsHeader;
			Bind(gTTableView, "Visibility", "Mails", (object x) => x.HideIfListIsNullOrEmpty());
			Bind(gTTableView, "Rows", "Mails");
			Bind(view, 2131297260, "Visibility", "Mails", (object x) => x.ShowIfListIsNullOrEmpty());
		}

		private void InitClubNewsList(View parent)
		{
			GTListView gTListView = parent.FindViewById<GTListView>(2131296690);
			gTListView.ItemTemplate = 2131492905;
			gTListView.SetContentPadding(0, Resources.GetDimensionPixelSize(2131100232));
			gTListView.Bind(2131296691, "Text", "Text");
			gTListView.Bind(2131296689, "Text", "Date", (object x) => x.ToString().ParseToDate().ToGTDateTimeString());
			gTListView.Bind(2131296692, "Text", "Title");
			Bind(gTListView, "DataSource", "ClubNews", null, showLog: true);
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			switch (propertyName)
			{
			case "StadiumLevel":
				_stadiumImage.SetImageResource($"stadium{base.ViewModel.StadiumLevel}".GetImageId(base.Context));
				break;
			case "TeamData":
				if (base.ViewModel.TeamData != null)
				{
					_teamLogo.ImageResource = base.ViewModel.TeamData.Logo.GetTeamLogoId(base.Context);
					_homeTrikot.ImageResource = base.ViewModel.TeamData.HomeTrikot.GetTrikotId(base.Context);
					_awayTrikot.ImageResource = base.ViewModel.TeamData.AwayTrikot.GetTrikotId(base.Context);
				}
				break;
			case "LastMatch":
			case "NextMatch":
				UpdateMatchInfo();
				break;
			case "ShowScore":
				_matchInfoStatus.SetTextSize(ComplexUnitType.Dip, base.ViewModel.ShowScore ? 26 : 16);
				break;
			case "IsNextMatchSelected":
			{
				UpdateMatchInfo();
				Button button;
				Button button2;
				if (base.ViewModel.IsNextMatchSelected)
				{
					button = _nextMatchButton;
					button2 = _lastMatchButton;
				}
				else
				{
					button = _lastMatchButton;
					button2 = _nextMatchButton;
				}
				button.BringToFront();
				button.SetTextColor(_activeButtonColor);
				button2.SetTextColor(_inactiveButtonColor);
				break;
			}
			case "NewMails":
				SetTabNotificationsCount(2, base.ViewModel.NewMails);
				break;
			case "SponsorsCount":
				SetTabNotificationsCount(1, base.ViewModel.SponsorsCount);
				break;
			}
		}

		private void UpdateMatchInfo()
		{
			if (base.ViewModel.IsNextMatchSelected)
			{
				UpdateMatchInfo(base.ViewModel.NextMatch);
			}
			else
			{
				UpdateMatchInfo(base.ViewModel.LastMatch);
			}
		}

		private void UpdateMatchInfo(MatchData match)
		{
			if (match == null)
			{
				_homeTeamLogo.Visibility = ViewStates.Invisible;
				_awayTeamLogo.Visibility = ViewStates.Invisible;
				return;
			}
			_homeTeamLogo.SetImageResource(match.HomeLogo.GetTeamLogoId(base.Context));
			_awayTeamLogo.SetImageResource(match.AwayLogo.GetTeamLogoId(base.Context));
			_homeTeamLogo.Visibility = ViewStates.Visible;
			_awayTeamLogo.Visibility = ViewStates.Visible;
		}
	}
