			_strengthView.Visibility = strength.HideIfNullOrEmpty();
		}

		public bool HandleTouch(MotionEvent e)
		{
			switch (e.ActionMasked)
			{
			case MotionEventActions.Move:
				SetX(e.RawX - (float)base.Width);
				SetY(e.RawY - (float)base.Height);
				CheckIntersectionWithDrops();
				break;
			case MotionEventActions.Up:
			case MotionEventActions.Cancel:
			case MotionEventActions.Outside:
				if (_selectedDrop != null && (!TutorialManager.Instance.InProgress || _selectedDrop.Player == null))
				{
					MoveToDrop();
				}
				else
				{
					MoveToStart();
				}
				break;
			}
			return true;
		}

		private void MoveToStart()
		{
			MoveToPoint(_startLocation.X, _startLocation.Y, OnMoveToStartFinished);
		}

		private void OnMoveToStartFinished()
		{
			if (UnselectCommand != null && UnselectCommand.CanExecute(Player))
			{
				UnselectCommand.Execute(Player);
			}
			Player = null;
			Visibility = ViewStates.Invisible;
		}

		private void MoveToDrop()
		{
			MoveToPoint(_selectedDrop.GetX(), _selectedDrop.GetY(), OnMoveToDropFinished);
		}

		private void OnMoveToDropFinished()
		{
			if (_selectedDrop != null)
			{
				_selectedDrop.Player = Player;
				Visibility = ViewStates.Invisible;
				if (SelectCommand != null && SelectCommand.CanExecute(_selectedDrop.MatchSystemField))
				{
					SelectCommand.Execute(_selectedDrop.MatchSystemField);
				}
				_selectedDrop = null;
			}
		}

		private void MoveToPoint(float x, float y, Action onFinished)
		{
			if (GetDistance((int)GetX(), (int)GetY(), (int)x, (int)y) < 15)
			{
				onFinished?.Invoke();
			}
			else
			{
				Animate().SetDuration(200L).X(x).Y(y)
					.SetInterpolator(_interpolator)
					.WithEndAction(new Runnable(onFinished));
			}
		}

		private void CheckIntersectionWithDrops()
		{
			if (GetDistance((int)GetX(), (int)GetY(), (int)_previousLocation.X, (int)_previousLocation.Y) < 15)
			{
				return;
			}
			_previousLocation.Set(GetX(), GetY());
			Rect rect = new Rect();
			GetGlobalVisibleRect(rect);
			IEnumerable<KeyValuePair<DropView, Rect>> source = _allDrops.Where((KeyValuePair<DropView, Rect> x) => Rect.Intersects(rect, x.Value));
			_selectedDrop?.Unhighlight();
			if (!source.Any())
			{
				_selectedDrop = null;
				SetStrength(string.Empty);
				return;
			}
			if (source.Count() == 1)
			{
				_selectedDrop = source.FirstOrDefault().Key;
			}
			else
			{
				_selectedDrop = source.OrderBy((KeyValuePair<DropView, Rect> x) => GetDistance(rect, x.Value)).FirstOrDefault().Key;
			}
			decimal strengthForPositionId = _player.GetStrengthForPositionId(_selectedDrop.MatchSystemField.PositionId);
			SetStrength((strengthForPositionId > 0m) ? strengthForPositionId.ToString("N1") : string.Empty);
			_selectedDrop.Highlight();
		}

		private int GetDistance(Rect rect1, Rect rect2)
		{
			return GetDistance(rect1.CenterX(), rect1.CenterY(), rect2.CenterX(), rect2.CenterY());
		}

		private int GetDistance(int x1, int y1, int x2, int y2)
		{
			return Math.Abs(x1 - x2) + Math.Abs(y1 - y2);
		}

		public void SetDropContainers(List<DropView> drops)
		{
			_allDrops.Clear();
			foreach (DropView drop in drops)
			{
				Rect rect = new Rect();
				drop.GetGlobalVisibleRect(rect);
				_allDrops.Add(drop, rect);
			}
		}

		public void Start(LineupPlayerData player, float x, float y)
		{
			Player = player;
			SetX(x);
			SetY(y);
			Visibility = ViewStates.Visible;
			_startLocation = new PointF(x, y);
			_selectedDrop = null;
			foreach (DropView key in _allDrops.Keys)
			{
				key.Unhighlight();
			}
		}
	}
