		public DropView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
			Initialize(attrs);
		}

		private void Initialize(IAttributeSet attrs)
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493115, this, attachToRoot: true);
			_strengthView = view.FindViewById<TextView>(2131296352);
			_text = view.FindViewById<TextView>(2131296350);
			_roundAvatar = view.FindViewById<PlayerRoundAvatar>(2131296351);
			_border = _roundAvatar.FindViewById<FrameLayout>(2131296582);
			_border.SetBackgroundResource(2131165315);
			if (attrs != null)
			{
				TypedArray typedArray = base.Context.ObtainStyledAttributes(attrs, Resource.Styleable.DropView);
				Position = typedArray.GetString(1);
				IsBench = typedArray.GetBoolean(0, defValue: false);
				typedArray.Recycle();
			}
			_roundAvatar.LongClick += OnLongCLicked;
		}

		private void OnLongCLicked(object sender, LongClickEventArgs e)
		{
			if (Player != null && LongClickCommand != null && LongClickCommand.CanExecute(Player))
			{
				LongClickCommand.Execute(Player);
			}
		}

		public void Reset()
		{
			Player = null;
		}

		public void Highlight()
		{
			if (_dropCircleColor != DropCircleColor.Highlighted)
			{
				_dropCircleColor = DropCircleColor.Highlighted;
				_border.SetBackgroundResource(2131165316);
			}
		}

		public void Unhighlight()
		{
			if ((_dropCircleColor != DropCircleColor.Empty || Player != null) && (_dropCircleColor != DropCircleColor.WithPlayer || Player == null))
			{
				_dropCircleColor = ((Player != null) ? DropCircleColor.WithPlayer : DropCircleColor.Empty);
				_border.SetBackgroundResource((Player == null) ? 2131165315 : 2131165319);
			}
		}
	}
