	public class LineupFormationView : BaseView<LineupFormationViewModel>
	{
		private readonly List<DropView> _allDrops;

		private readonly DraggableView _dragView;

		private readonly GTTableView _table;

		private readonly ConstraintLayout _field;

		private readonly ComboBox _systemComboBox;

		private readonly ComboBox _tacticComboBox;

		private DropView _tutorialEmptyDrop;

		private PointF _touchPoint;

		public LineupFormationView(Context context)
			: base(context)
		{
			SetContent(2131493040);
			_allDrops = new List<DropView>();
			for (int i = 1; i <= 17; i++)
			{
				DropView dropView = FindViewById<DropView>(base.Context.Resources.GetIdentifier($"LineupFormationPosition_{i}", "id", base.Context.PackageName));
				if (dropView != null)
				{
					dropView.LongClickCommand = base.ViewModel.SelectPlayerCommand;
					_allDrops.Add(dropView);
				}
			}
			Bind(2131296322, "Visibility", "IsLocked", (object x) => x.ToVisibility());
			Bind(2131296328, "Text", "TotalStrength", (object x) => $"{x:N1}");
			_table = FindViewById<GTTableView>(2131296325);
			_table.RowHeight = 60;
			_table.HeaderRow = base.ViewModel.PlayersTableHeader;
			Bind(_table, "Rows", "PlayerTableRows");
			_dragView = FindViewById<DraggableView>(2131296323);
			_dragView.SelectCommand = base.ViewModel.PlaceToLineupCommand;
			_dragView.UnselectCommand = base.ViewModel.UnselectPlayerCommand;
			_field = FindViewById<ConstraintLayout>(2131296321);
			_systemComboBox = FindViewById<ComboBox>(2131296326);
			_systemComboBox.FocusChanged += OnComboBoxFocusChanged;
			Bind(_systemComboBox, "Enabled", "IsLocked", (object x) => !(bool)x);
			Bind(_systemComboBox, "Items", "Systems");
			Bind(_systemComboBox, "SelectedValue", "VisibleSystem");
			_tacticComboBox = FindViewById<ComboBox>(2131296327);
			_tacticComboBox.FocusChanged += OnComboBoxFocusChanged;
			Bind(_tacticComboBox, "Enabled", "IsLocked", (object x) => !(bool)x);
			Bind(_tacticComboBox, "Items", "Tactics");
			Bind(_tacticComboBox, "SelectedValue", "SelectedTactic");
		}

		public override bool OnInterceptTouchEvent(MotionEvent ev)
		{
			_touchPoint = new PointF(ev.RawX, ev.RawY);
			if (_dragView.Visibility == ViewStates.Visible)
			{
				_dragView.HandleTouch(ev);
				return true;
			}
			return false;
		}

		public override bool OnTouchEvent(MotionEvent e)
		{
			if (_dragView.Visibility == ViewStates.Visible)
			{
				_dragView.HandleTouch(e);
				return true;
			}
			return base.OnTouchEvent(e);
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			switch (propertyName)
			{
			case "SelectedPlayer":
				ShowDrag();
				break;
			case "SelectedVisibleSystem":
				UpdateDrops();
				break;
			case "FormationPlayers":
				UpdateFormation();
				break;
			case "TutorialPlayer":
				if (TutorialManager.Instance.ShouldChangeLineup())
				{
					int num = base.ViewModel.PlayerTableRows.FindIndex((ITableRow x) => x is PlayerRow playerRow && playerRow.Player == base.ViewModel.TutorialPlayer);
					_table.ScrollToPosition(num + 1);
				}
				break;
			}
		}

		private void ShowDrag()
		{
			if (base.ViewModel.SelectedPlayer == null)
			{
				_dragView.Visibility = ViewStates.Invisible;
				return;
			}
			_dragView.SetDropContainers(_allDrops);
			_dragView.Start(base.ViewModel.SelectedPlayer, _touchPoint.X - (float)_dragView.Width, _touchPoint.Y - (float)_dragView.Height);
			if (TutorialManager.Instance.InProgress && _tutorialEmptyDrop != null)
			{
				ComponentFactory.Resolve<ITutorialController>().ShowNextArea(_tutorialEmptyDrop.RoundAvatar);
			}
		}

		private void UpdateDrops()
		{
			if (base.ViewModel.SelectedVisibleSystem?.Fields == null || base.ViewModel.SelectedVisibleSystem.Fields.Count == 0)
			{
				return;
			}
			foreach (DropView allDrop in _allDrops)
			{
				allDrop.Reset();
			}
			ConstraintSet constraintSet = new ConstraintSet();
			constraintSet.Clone(_field);
			foreach (MatchSystemFieldData field in base.ViewModel.SelectedVisibleSystem.Fields)
			{
				(int, GT.Core.Point) dropInfo = field.DropInfo;
				if (IsDropOnScreen(dropInfo.Item1))
				{
					DropView dropView = _allDrops[dropInfo.Item1];
					dropView.MatchSystemField = field;
					if (dropInfo.Item2 != GT.Core.Point.Zero)
					{
						int id = dropView.Id;
						constraintSet.SetHorizontalBias(id, dropInfo.Item2.X);
						constraintSet.SetVerticalBias(id, dropInfo.Item2.Y);
					}
				}
			}
			constraintSet.ApplyTo(_field);
			UpdateFormation();
		}

		private bool IsDropOnScreen(int index)
		{
			if (index >= 0)
			{
				return index < _allDrops.Count;
			}
			return false;
		}

		private void UpdateFormation()
		{
			if (base.ViewModel.SelectedVisibleSystem?.Fields == null)
			{
				return;
			}
			foreach (MatchSystemFieldData field in base.ViewModel.SelectedVisibleSystem.Fields)
			{
				int item = field.DropInfo.Index;
				if (IsDropOnScreen(item))
				{
					_allDrops[item].Player = (base.ViewModel.FormationPlayers.TryGetValue(field, out var value) ? value : null);
					if (value == null)
					{
						_tutorialEmptyDrop = _allDrops[item];
					}
				}
			}
		}

		private void OnComboBoxFocusChanged(object sender, bool isFocused)
		{
			if (sender == _systemComboBox && isFocused)
			{
				_tacticComboBox.CloseMenu();
			}
			else if (sender == _tacticComboBox && isFocused)
			{
				_systemComboBox.CloseMenu();
			}
		}

		public override void OnDisappearing()
		{
			base.OnDisappearing();
			ResetUI();
		}

		private void ResetUI()
		{
			_systemComboBox.CloseMenu();
			_tacticComboBox.CloseMenu();
		}
