	public class MultiImageView : LinearLayout
	{
		private string _imageName;

		private int _repeats;

		public string ImageName
		{
			get
			{
				return _imageName;
			}
			set
			{
				_imageName = value;
			}
		}

		public int Repeats
		{
			get
			{
				return _repeats;
			}
			set
			{
				_repeats = value;
				Update();
			}
		}

		public MultiImageView(Context context)
			: base(context)
		{
		}

		public MultiImageView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
		}

		public MultiImageView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
		}

		public MultiImageView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
		}

		protected MultiImageView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
		}

		private void Update()
		{
			if (ChildCount != Repeats)
			{
				RemoveAllViews();
				for (int i = 0; i < Repeats; i++)
				{
					ImageView imageView = new ImageView(base.Context)
					{
						LayoutParameters = new LayoutParams(15.FromDPToPx(base.Context), 15.FromDPToPx(base.Context))
					};
					imageView.SetScaleType(ImageView.ScaleType.CenterInside);
					imageView.SetImageResource(ImageName.GetImageId(base.Context));
					AddView(imageView);
				}
				RequestLayout();
			}
		}
	}
