	public class SponsorDetailsView<T> : BaseView<T> where T : SponsorDetailsViewModel
	{
		private readonly FrameLayout _sign;

		private readonly View _stamp;

		private readonly TextView _manager;

		private readonly View _line;

		private readonly GTButton _buttonNegotiate;

		private readonly GTButton _buttonAccept;

		private readonly ValueAnimator _animator;

		public SponsorDetailsView(Context context)
			: base(context)
		{
			View view = SetContent(2131493161);
			Bind(2131297572, "Text", "Name");
			Bind(2131297554, "Text", "Description");
			Bind(2131297553, "Text", "DateTitle");
			Bind(2131297552, "Text", "Date");
			_manager = view.FindViewById<TextView>(2131297556);
			Bind(_manager, "Visibility", "Accepted", (object x) => x.ToVisibility());
			Bind(_manager, "Text", "ManagerName");
			_line = view.FindViewById<View>(2131297555);
			Bind(_line, "Visibility", "Accepted", (object x) => x.ToVisibility());
			_sign = view.FindViewById<FrameLayout>(2131297570);
			_stamp = view.FindViewById<View>(2131297571);
			Bind(_sign, "Visibility", "Accepted", (object x) => x.ToVisibility(goneIfHidden: false));
			Bind(_stamp, "Visibility", "Accepted", (object x) => x.ToVisibility());
			_buttonNegotiate = FindViewById<GTButton>(2131297550);
			Bind(_buttonNegotiate, "Value", "NegotiateCost");
			Bind(_buttonNegotiate, "Visibility", "Accepted", (object x) => x.ToInverseVisibility(goneIfHidden: false));
			Bind(_buttonNegotiate, base.ViewModel.NegotiateCommand);
			_buttonAccept = FindViewById<GTButton>(2131297549);
			_buttonAccept.Tag = (base.ViewModel.IsMainSponsor ? "accept_main_sponsor" : "accept_secondary_sponsor");
			Bind(_buttonAccept, "Visibility", "Accepted", (object x) => x.ToInverseVisibility(goneIfHidden: false));
			_buttonAccept.Click += OnAcceptButtonCLicked;
			(View, View, View) sponsorOfferViews = GetSponsorOfferViews(2131297557);
			Bind(sponsorOfferViews.Item1, "Text", "OfferTitle1");
			Bind(sponsorOfferViews.Item2, "Text", "OfferValue1", (object x) => string.Format("{0:N0} {1}", x, "€"));
			Bind(sponsorOfferViews.Item3, "Value", "PreviousValue1");
			Bind(sponsorOfferViews.Item3, "Visibility", "PreviousValueVisible", (object x) => x.ToVisibility());
			(View, View, View) sponsorOfferViews2 = GetSponsorOfferViews(2131297558);
			Bind(sponsorOfferViews2.Item1, "Text", "OfferTitle2");
			Bind(sponsorOfferViews2.Item2, "Text", "OfferValue2", (object x) => string.Format("{0:N0} {1}", x, "€"));
			Bind(sponsorOfferViews2.Item3, "Value", "PreviousValue2");
			Bind(sponsorOfferViews2.Item3, "Visibility", "PreviousValueVisible", (object x) => x.ToVisibility());
			(View, View, View) sponsorOfferViews3 = GetSponsorOfferViews(2131297559);
			Bind(sponsorOfferViews3.Item1, "Text", "OfferTitle3");
			Bind(sponsorOfferViews3.Item2, "Text", "OfferValue3", (object x) => string.Format("{0:N0} {1}", x, "€"));
			Bind(sponsorOfferViews3.Item3, "Value", "PreviousValue3");
			Bind(sponsorOfferViews3.Item3, "Visibility", "PreviousValueVisible", (object x) => x.ToVisibility());
			TextView view2 = FindViewById<TextView>(2131297563);
			Bind(view2, "Text", "CardsValue", (object x) => $"{x}");
			View view3 = FindViewById<View>(2131297560);
			TextView view4 = view3.FindViewById<TextView>(2131297568);
			TextView view5 = view3.FindViewById<TextView>(2131297569);
			Bind(view4, "Text", "PremiumTitle");
			Bind(view5, "Text", "PremiumValue", (object x) => $"{x:N0}");
			_animator = new ValueAnimator();
			_animator.SetDuration(1000L);
			_animator.Update += OnAnimatorUpdate;
			_animator.AnimationEnd += OnAnimationEnd;
		}

		private (View Title, View Value, View PreviousValue) GetSponsorOfferViews(int offerViewId)
		{
			View view = FindViewById<View>(offerViewId);
			TextView item = view.FindViewById<TextView>(2131297564);
			TextView item2 = view.FindViewById<TextView>(2131297565);
			TextView item3 = view.FindViewById<TextView>(2131297561);
			return (Title: item, Value: item2, PreviousValue: item3);
		}

		private void OnAcceptButtonCLicked(object sender, EventArgs e)
		{
			Sign().FireAndForgetSafeAsync();
		}

		private async Task Sign()
		{
			_buttonNegotiate.Visibility = ViewStates.Invisible;
			_buttonAccept.Visibility = ViewStates.Invisible;
			_line.Alpha = 0f;
			_manager.Alpha = 0f;
			_sign.Alpha = 0f;
			_stamp.Alpha = 0f;
			if (!(await base.ViewModel.Accept()))
			{
				_buttonNegotiate.Visibility = ViewStates.Visible;
				_buttonAccept.Visibility = ViewStates.Visible;
				_line.Alpha = 1f;
				_manager.Alpha = 1f;
				_sign.Alpha = 1f;
				_stamp.Alpha = 1f;
			}
			else
			{
				RunSignAnimation();
			}
		}

		private void RunSignAnimation()
		{
			_line.FadeIn();
			_manager.FadeIn();
			View childAt = _sign.GetChildAt(0);
			_sign.SetSize(0, childAt.LayoutParameters.Height);
			GT.Core.Log.Info($"start sign size = {_sign.LayoutParameters.Width}, {_sign.LayoutParameters.Height}");
			_sign.Alpha = 1f;
			_sign.Visibility = ViewStates.Visible;
			ComponentFactory.Resolve<ISoundManager>().PlaySound(Sounds.Signature);
			_animator.SetIntValues(0, childAt.LayoutParameters.Width);
			_animator.Start();
		}

		private void OnAnimatorUpdate(object sender, ValueAnimator.AnimatorUpdateEventArgs e)
		{
			_sign.SetSize((int)e.Animation.AnimatedValue, _sign.LayoutParameters.Height);
			GT.Core.Log.Info($"sign size = {_sign.LayoutParameters.Width}, {_sign.LayoutParameters.Height}");
		}

		private void OnAnimationEnd(object sender, EventArgs e)
		{
			_stamp.ScaleX = 3f;
			_stamp.ScaleY = 3f;
			_stamp.Visibility = ViewStates.Visible;
			ComponentFactory.Resolve<ISoundManager>().PlaySound(Sounds.Stamp);
			_stamp.Animate().SetDuration(500L).ScaleX(1f)
				.ScaleY(1f)
				.Alpha(1f)
				.WithEndAction(new Runnable(delegate
				{
					base.ViewModel.ShowReward().FireAndForgetSafeAsync();
