	public class StadiumView : BaseView<StadiumViewModel>, GestureDetector.IOnGestureListener, IJavaObject, IDisposable, IJavaPeerable, IFullscreenView
	{
		private readonly CustomScrollView _scrollView;

		private readonly CustomHorizontalScrollView _horizontalScrollView;

		private readonly View _map;

		private readonly ViewGroup _mainLayout;

		private readonly ViewGroup _mapContainer;

		private View _progressView;

		private Building _progressBuilding;

		private const float _heightRatio = 0.563f;

		private const float _mapSizeFactor = 2f;

		private bool _firstScrolled;

		private int _screenWidth;

		private int _screenHeight;

		private GestureDetector _gestureDetector;

		private List<Building> _buildings;

		private Building _selectedBuilding;

		public List<Building> Buildings
		{
			get
			{
				return _buildings;
			}
			set
			{
				_buildings = value;
				UpdateBuildings();
			}
		}

		public Building SelectedBuilding
		{
			get
			{
				return _selectedBuilding;
			}
			set
			{
				_selectedBuilding = value;
				ScrollToSelectedBuilding();
			}
		}

		public ICommand BuildingSelectedCommand { get; set; }

		public StadiumView(Context context)
			: base(context)
		{
			SetContent(2131493174);
			_gestureDetector = new GestureDetector(context, this);
			_scrollView = FindViewById<CustomScrollView>(2131296410);
			_horizontalScrollView = FindViewById<CustomHorizontalScrollView>(2131296398);
			_mainLayout = FindViewById<ViewGroup>(2131296399);
			_mapContainer = FindViewById<ViewGroup>(2131296401);
			_map = FindViewById<View>(2131296400);
			_progressView = FindViewById<View>(2131296402);
			GTProgressBar gTProgressBar = FindViewById<GTProgressBar>(2131296403);
			gTProgressBar.MaxValue = 100m;
			Bind(this, "Buildings", "Buildings");
			Bind(this, "BuildingSelectedCommand", "SelectBuildingCommand");
			Bind(this, "SelectedBuilding", "SelectedBuilding");
			Bind(2131296402, "Visibility", "IsBuildInProgress", (object x) => ((bool)x).ToVisibility());
			Bind(2131296406, "Visibility", "IsBuildInProgress", (object x) => ((bool)x).ToVisibility());
			Bind(2131296406, base.ViewModel.SelectedInProgressBuildingCommand);
			Bind(2131296404, "Text", "TimeLeftText");
			Bind(2131296405, "Text", "BuildProgress", (object x) => $"{x:N2}%");
			Bind(2131296409, "Text", "TimeLeftText");
			Bind(2131296408, "Text", "BuildProgress", (object x) => $"{x:N2}%");
			Bind(2131296407, "Text", "ConstructedBuildingName");
			Bind(gTProgressBar, "Progress", "BuildProgress");
		}

		private void UpdateBuildings()
		{
			_mainLayout.RemoveAllViews();
			if (Buildings == null)
			{
				return;
			}
			_progressBuilding = null;
			foreach (Building building in Buildings)
			{
				BuildingView child = new BuildingView(base.Context)
				{
					Building = building
				};
				if (building.IsUnderConstruction)
				{
					_progressBuilding = building;
				}
				_mainLayout.AddView(child);
			}
			UpdateBuildingSizes();
		}

		private void ScrollToSelectedBuilding()
		{
			if (SelectedBuilding == null || _screenWidth == 0 || _screenHeight == 0)
			{
				return;
			}
			for (int i = 0; i < _mainLayout.ChildCount; i++)
			{
				if (_mainLayout.GetChildAt(i) is BuildingView buildingView && SelectedBuilding == buildingView.Building)
				{
					RelativeLayout.LayoutParams layoutParams = (RelativeLayout.LayoutParams)buildingView.LayoutParameters;
					int x = layoutParams.LeftMargin + (layoutParams.Width - base.Width) / 2;
					int y = layoutParams.TopMargin + (layoutParams.Height - base.Height) / 2;
					if (!_firstScrolled)
					{
						_firstScrolled = true;
						_horizontalScrollView.ScrollTo(x, 0);
						_scrollView.ScrollTo(0, y);
					}
					else
					{
						_horizontalScrollView.SmoothScrollTo(x, 0);
						_scrollView.SmoothScrollTo(0, y);
					}
				}
			}
		}

		protected override void OnLayout(bool changed, int left, int top, int right, int bottom)
		{
			base.OnLayout(changed, left, top, right, bottom);
			if (changed)
			{
				int num = (int)((float)(right - left) * 2f);
				int num2 = (int)((float)num * 0.563f);
				UpdateViewSize(_mapContainer, num, num2);
				UpdateViewSize(_map, num, num2);
				UpdateViewSize(_mainLayout, num, num2);
				_screenWidth = num;
				_screenHeight = num2;
				UpdateBuildingSizes();
				ScrollToSelectedBuilding();
			}
		}

		private void UpdateViewSize(View view, int width, int height)
		{
			ViewGroup.LayoutParams layoutParameters = view.LayoutParameters;
			layoutParameters.Width = width;
			layoutParameters.Height = height;
			view.LayoutParameters = layoutParameters;
		}

		private void UpdateBuildingSizes()
		{
			if (_screenWidth == 0 || _screenHeight == 0)
			{
				return;
			}
			for (int i = 0; i < _mainLayout.ChildCount; i++)
			{
				if (_mainLayout.GetChildAt(i) is BuildingView buildingView)
				{
					ViewGroup.LayoutParams layoutParams = buildingView.UpdateLayoutParameters(_screenWidth, _screenHeight);
					if (_progressBuilding != null && buildingView.Building == _progressBuilding && layoutParams is RelativeLayout.LayoutParams layoutParams2 && _progressView.LayoutParameters is RelativeLayout.LayoutParams layoutParams3)
					{
						layoutParams3.Width = layoutParams2.Width;
						layoutParams3.Height = layoutParams2.Height;
						layoutParams3.LeftMargin = layoutParams2.LeftMargin;
						layoutParams3.TopMargin = layoutParams2.TopMargin;
						_progressView.LayoutParameters = layoutParams3;
					}
				}
			}
		}

		public override bool OnTouchEvent(MotionEvent e)
		{
			if (_gestureDetector.OnTouchEvent(e))
			{
				return true;
			}
			return base.OnTouchEvent(e);
		}

		public bool OnDown(MotionEvent e)
		{
			return true;
		}

		public bool OnFling(MotionEvent e1, MotionEvent e2, float velocityX, float velocityY)
		{
			return true;
		}

		public void OnLongPress(MotionEvent e)
		{
		}

		public bool OnScroll(MotionEvent e1, MotionEvent e2, float distanceX, float distanceY)
		{
			_horizontalScrollView.ScrollBy((int)distanceX, (int)distanceY);
			_scrollView.ScrollBy((int)distanceX, (int)distanceY);
			base.ViewModel.SelectedBuilding = null;
			return true;
		}

		public void OnShowPress(MotionEvent e)
		{
		}

		public bool OnSingleTapUp(MotionEvent e)
		{
			float touchX = e.GetX() + (float)_horizontalScrollView.ScrollX;
			float touchY = e.GetY() + (float)_scrollView.ScrollY;
			for (int i = 0; i < _mainLayout.ChildCount; i++)
			{
				if (_mainLayout.GetChildAt(i) is BuildingView buildingView && buildingView.IsTouchInside(touchX, touchY))
				{
					if (BuildingSelectedCommand != null && BuildingSelectedCommand.CanExecute(buildingView.Building))
					{
						BuildingSelectedCommand.Execute(buildingView.Building);
					}
					return true;
				}
			}
			return true;
		}
	}
