			{
				_subSkillComboBox.CloseMenu();
			}
		}

		private int GetColor(object x)
		{
			if (x is TeamTrainingStatus teamTrainingStatus)
			{
				switch (teamTrainingStatus)
				{
				case TeamTrainingStatus.EffectiveTraining:
					return 2131034164;
				case TeamTrainingStatus.IneffectiveTraining:
					return 2131034180;
				}
			}
			return 2131034206;
		}

		private int GetDecreaseColor(object x)
		{
			if (x is GeneralStatus generalStatus)
			{
