	public class TrainingProgressView : BaseView<TrainingProgressViewModel>
	{
		private SKTypeface _font;

		private readonly int _fontSize;

		private readonly int _chartMargin;

		private ChartView _skillProgressChart;

		private GTTableView _selectSkill;

		public TrainingProgressView(Context context)
			: base(context)
		{
			_chartMargin = 10.FromDPToPx(base.Context);
			_fontSize = 12.FromDPToPx(base.Context);
			SetContent(2131493219);
			_skillProgressChart = ((View)this).FindViewById<ChartView>(2131296425);
			_selectSkill = FindViewById<GTTableView>(2131296426);
			_selectSkill.RowHeight = 40;
			_selectSkill.HeaderRow = base.ViewModel.SkillsTableHeader;
			Bind(_selectSkill, "Rows", "SkillTableRows");
			Bind((View)(object)_skillProgressChart, "Chart", "SelectedSkill", (object x) => GetChart((x as SkillTrainingData).TrainingProgress, SKColors.Gold));
		}

		private SKTypeface GetSkiaTypefaceFromAssetFont()
		{
			using Stream stream = base.Context.Assets.Open("roboto_bold.ttf");
			MemoryStream memoryStream = new MemoryStream();
			stream.CopyTo(memoryStream);
			memoryStream.Flush();
			memoryStream.Position = 0L;
			return SKTypeface.FromStream(memoryStream);
		}

		private Chart GetChart(object data, SKColor color)
		{
			if (!(data is List<ChartData> source))
			{
				return null;
			}
			return new LineChart
			{
				Entries = source.Select((ChartData x) => GetChartEntry(x, color)),
				LineMode = LineMode.Straight,
				BackgroundColor = SKColors.Transparent,
				LabelTextSize = _fontSize,
				LabelColor = SKColors.White,
				Margin = _chartMargin,
				EnableYFadeOutGradient = true,
				Typeface = (_font ?? (_font = GetSkiaTypefaceFromAssetFont())),
				LabelOrientation = Microcharts.Orientation.Horizontal,
				ValueLabelOrientation = Microcharts.Orientation.Horizontal
			};
		}

		private ChartEntry GetChartEntry(ChartData chartData, SKColor color)
		{
			return new ChartEntry(chartData.Value)
			{
				Label = chartData.Label,
				ValueLabel = chartData.ValueLabel,
				Color = color,
				ValueLabelColor = color
			};
		}
	}
