		private void AddTransfermarketTable(string tabName, string listPropertyName, GT.Core.Character character, string noDataMessage, string noDataButton1Text, string noDataButton2Text, ICommand noDataButton1Command, ICommand noDataButton2Command)
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493220, null, attachToRoot: false);
			AddTab(tabName, view);
			GTTableView gTTableView = view.FindViewById<GTTableView>(2131297741);
			gTTableView.RowHeight = 60;
			gTTableView.HeaderRow = base.ViewModel.PlayersListHeader;
			Bind(gTTableView, "Visibility", listPropertyName, (object x) => x.HideIfListIsNullOrEmpty());
			Bind(gTTableView, "Rows", listPropertyName);
			NoDataView noDataView = view.FindViewById<NoDataView>(2131297740);
			noDataView.Character = character;
			noDataView.Message = noDataMessage;
			noDataView.Button1Text = noDataButton1Text;
			noDataView.Button2Text = noDataButton2Text;
			noDataView.Command1 = noDataButton1Command;
			noDataView.Command2 = noDataButton2Command;
			Bind(noDataView, "Visibility", listPropertyName, (object x) => x.ShowIfListIsNullOrEmpty());
		}

		private void AddQuickSearch()
		{
			QuickSearchView quickSearchView = new QuickSearchView(base.Context);
			AddTab("QuickSearch".Translate(), quickSearchView, "tab_quick_search");
			_positionComboBox = quickSearchView.FindViewById<ComboBox>(2131297739);
			_positionComboBox.TutorialControlId = "dropdown_position";
			_positionComboBox.Items = base.ViewModel.PositionsList;
			_positionComboBox.Text = "SelectPosition".Translate();
			Bind(_positionComboBox, "SelectedPosition");
			Bind(quickSearchView, 2131297382, base.ViewModel.SearchCommand);
			GTButton gTButton = quickSearchView.FindViewById<GTButton>(2131297383);
			gTButton.ButtonType = ButtonType.Inactive;
			Bind(gTButton, base.ViewModel.ResetCommand);
			_ageSlider = quickSearchView.FindViewById<GTRangeSlider>(2131296528);
			_ageSlider.MinValue = 16.0;
			_ageSlider.MaxValue = 34.0;
			_ageSlider.Name = "Age".Translate();
			Bind(_ageSlider, "SelectedAgeMin", "SelectedAgeMax");
			_strengthSlider = quickSearchView.FindViewById<GTRangeSlider>(2131297624);
			_strengthSlider.DisplayMax = true;
			_strengthSlider.MinValue = 1.0;
			_strengthSlider.MaxValue = 101.0;
			_strengthSlider.Name = "Strength".Translate();
			Bind(_strengthSlider, "SelectedStrengthMin", "SelectedStrengthMax");
			_talentSlider = quickSearchView.FindViewById<GTRangeSlider>(2131297678);
			_talentSlider.MinValue = 1.0;
			_talentSlider.MaxValue = 10.0;
			_talentSlider.Name = "Talent".Translate();
			Bind(_talentSlider, "SelectedTalentMin", "SelectedTalentMax");
			_skillSlider = quickSearchView.FindViewById<GTRangeSlider>(2131297526);
			_skillSlider.DisplayMax = true;
			_skillSlider.MinValue = 1.0;
			_skillSlider.MaxValue = 101.0;
			_skillSlider.Name = "Skill".Translate();
			Bind(_skillSlider, "Visibility", "SkillIndex", (object x) => ((int)x == -1) ? ViewStates.Invisible : ViewStates.Visible);
			Bind(_skillSlider, "SelectedSkillMin", "SelectedSkillMax");
			GTSwitcher switcher = quickSearchView.FindViewById<GTSwitcher>(2131296595);
			Bind(switcher, "IsBudgetLimited");
			if (!TutorialManager.Instance.InProgress && base.ViewModel.LoadedSettings != null)
			{
				_ageSlider.SetSelection(base.ViewModel.LoadedSettings.SelectedAgeMin, base.ViewModel.LoadedSettings.SelectedAgeMax);
				_talentSlider.SetSelection(base.ViewModel.LoadedSettings.SelectedTalentMin, base.ViewModel.LoadedSettings.SelectedTalentMax);
				_strengthSlider.SetSelection(base.ViewModel.LoadedSettings.SelectedStrengthMin, base.ViewModel.LoadedSettings.SelectedStrengthMax);
				_skillSlider.SetSelection(base.ViewModel.LoadedSettings.SelectedSkillMin, base.ViewModel.LoadedSettings.SelectedSkillMax);
			}
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "WasReset")
			{
				_ageSlider.Reset();
				_strengthSlider.Reset();
				_skillSlider.Reset();
				_talentSlider.Reset();
			}
		}
	}
