		private void AddIndividualTrainingTable()
		{
			GTTableView gTTableView = FindViewById<GTTableView>(2131297029);
			gTTableView.HeaderRow = base.ViewModel.PlayersListHeader;
			gTTableView.NoDataMessage = base.ViewModel.NoPlayersMessage;
			gTTableView.RowHeight = 60;
			Bind(gTTableView, "Rows", "TrainedPlayersList");
		}

		public override void OnDisappearing()
		{
			base.OnDisappearing();
			ResetUI();
		}

		public void OnTabDisappearing()
		{
			ResetUI();
		}

		private void OnComboBoxFocusChanged(object sender, bool isFocused)
		{
			if (sender == _freePlayers && isFocused)
			{
				_selectSkills.CloseMenu();
			}
			else if (sender == _selectSkills && isFocused)
			{
				_freePlayers.CloseMenu();
			}
		}

		private void ResetUI()
		{
			_freePlayers.CloseMenu();
			_selectSkills.CloseMenu();
		}
	}
