			Bind(view, 2131296578, "Visibility", "IsAuctionFinished", (object x) => x.ToInverseVisibility(goneIfHidden: false));
			Bind(view, 2131296575, "Visibility", "IsAuctionFinished", (object x) => x.ToInverseVisibility());
