		public override void OnAppearing()
		{
			Alpha = 0f;
			base.OnAppearing();
		}

		public override void OnDidAppear()
		{
			base.OnDidAppear();
			this.FadeIn();
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (!(propertyName == "IsMyBid"))
			{
				if (propertyName == "BidDifference")
				{
					AnimateBid();
				}
			}
			else
			{
				_bidTeamName.SetTextColor((base.ViewModel.IsMyBid ? TableCellColor.Positive : TableCellColor.Negative).ToColor(base.Context));
			}
		}

		private void AnimateBid()
		{
			if (base.ViewModel.BidDifference <= 0m)
			{
				return;
			}
			TextView label = new TextView(base.Context)
			{
				Text = string.Format("+{0:N0} {1}", base.ViewModel.BidDifference, "€"),
				LayoutParameters = new LayoutParams(-2, -2)
				{
					Gravity = GravityFlags.Center
				},
				Alpha = 0f
			};
			label.SetTextAppearance(2131886357);
			label.SetTextColor(2131034164.ToColor(base.Context));
			_bidFrame.AddView(label);
			label.Animate().SetInterpolator(_interpolator).ScaleXBy(0.5f)
				.ScaleYBy(0.5f)
				.TranslationY(-60f)
				.Alpha(1f)
				.SetDuration(1000L)
				.WithEndAction(new Runnable(delegate
				{
					label.Animate().TranslationY(-70f).Alpha(0f)
						.SetDuration(1000L)
						.WithEndAction(new Runnable(delegate
						{
							_bidFrame.RemoveView(label);
							label = null;
						}));
				}));
		}
	}
