	public class ShareService : IShareService
	{
		private readonly Context _context;

		public ShareService(Context context)
		{
			_context = context;
		}

		public void ShareInvite(string url, string text, SocialNetworkType type)
		{
			switch (type)
			{
			case SocialNetworkType.WhatsApp:
				ShareViaWhatsApp(url, text);
				break;
			case SocialNetworkType.Facebook:
				ShareViaFacebook(url, text);
				break;
			case SocialNetworkType.Messenger:
				ShareViaMessenger(url, text);
				break;
			case SocialNetworkType.Other:
				ShareViaOthers(url, text);
				break;
			}
		}

		private void ShareViaWhatsApp(string url, string text)
		{
			Intent intent = new Intent();
			intent.SetAction("android.intent.action.SEND");
			intent.PutExtra("android.intent.extra.TEXT", text + Environment.NewLine + url);
			intent.SetType("text/plain");
			intent.SetPackage("com.whatsapp");
			try
			{
				_context.StartActivity(intent);
			}
			catch (ActivityNotFoundException)
			{
				Toast.MakeText(_context, "Please Install WhatsApp", ToastLength.Long).Show();
			}
		}

		private void ShareViaFacebook(string url, string text)
		{
		}

		private void ShareViaMessenger(string url, string text)
		{
			Intent intent = new Intent();
			intent.SetAction("android.intent.action.SEND");
			intent.PutExtra("android.intent.extra.TEXT", text + Environment.NewLine + url);
			intent.SetType("text/plain");
			intent.SetPackage("com.facebook.orca");
			try
			{
				_context.StartActivity(intent);
			}
			catch (ActivityNotFoundException)
			{
				Toast.MakeText(_context, "Please Install Facebook Messenger", ToastLength.Long).Show();
			}
		}

		private void ShareViaOthers(string url, string text)
		{
			Intent intent = new Intent();
			intent.SetAction("android.intent.action.SEND");
			intent.SetType("text/plain");
			intent.AddFlags(ActivityFlags.ClearWhenTaskReset);
			intent.PutExtra("android.intent.extra.TEXT", text + Environment.NewLine + url);
			_context.StartActivity(Intent.CreateChooser(intent, string.Empty));
		}
	}
	public class ListPaddingDecoration : RecyclerView.ItemDecoration
	{
		private readonly int _top;

		private readonly int _bottom;

		public ListPaddingDecoration(int topPadding, int bottomPadding)
		{
			_top = topPadding;
			_bottom = bottomPadding;
		}

		public override void GetItemOffsets(Rect outRect, View view, RecyclerView parent, RecyclerView.State state)
		{
			int childAdapterPosition = parent.GetChildAdapterPosition(view);
			switch (childAdapterPosition)
			{
			case -1:
				return;
			case 0:
				outRect.Top = _top;
				break;
			}
			RecyclerView.Adapter adapter = parent.GetAdapter();
			if (adapter != null && childAdapterPosition == adapter.ItemCount - 1)
			{
				outRect.Bottom = _bottom;
			}
		}
	}
	public abstract class BasePopup<T> : BaseUIElement<T> where T : BasePopupViewModel
	{
		private View _popupContainer;

		private PopupSize _popupSize;

		protected FrameLayout PopupContent { get; private set; }

		protected TaskCompletionSource<PopupResult> PopupTaskCompletionSource { get; private set; }

		public PopupSize PopupSize
		{
			get
			{
				return _popupSize;
			}
			set
			{
				_popupSize = value;
				UpdatePopupSize();
			}
		}

		public BasePopup(Context context)
			: base(context)
		{
			Initialize();
		}

		public BasePopup(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public BasePopup(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			SetContent(2131493123);
			ImageButton imageButton = FindViewById<ImageButton>(2131297349);
			imageButton.Click += OnCloseButtonClicked;
			imageButton.SetSoundEffect();
			Bind(imageButton, "Visibility", "IsCloseButtonHidden", (object x) => x.ToInverseVisibility());
			View view = FindViewById<View>(2131297355);
			view.Click += OnShadowClicked;
			view.SoundEffectsEnabled = false;
			View view2 = FindViewById<View>(2131297358);
			view2.ClipToOutline = true;
			view2.Click += delegate
			{
			};
			view2.SoundEffectsEnabled = false;
			Bind(2131297356, "Text", "Title");
			Bind(2131297345, "ImageName", "Background", GetBackgroundImageName);
			Bind(2131297347, "ImageName", "Character", (object x) => x.GetCharacterImageName());
			Bind(this, "PopupSize", "Size");
			_popupContainer = FindViewById<View>(2131297351);
			_popupContainer.Alpha = 0f;
			_popupContainer.TranslationY = Resources.GetDimensionPixelSize(2131100229);
		}

		protected void SetPopupContent(int layoutResourceId)
		{
			SetPopupContent(2131297352, layoutResourceId);
		}

		protected void SetSmallPopupContent(int layoutResourceId)
		{
			SetPopupContent(2131297353, layoutResourceId);
		}

		private void SetPopupContent(int containerId, int viewId)
		{
			PopupContent = FindViewById<FrameLayout>(containerId);
			LayoutInflater.From(base.Context).Inflate(viewId, PopupContent, attachToRoot: true);
		}

		protected void SetPopupContent(View view)
		{
			PopupContent = FindViewById<FrameLayout>(2131297352);
			PopupContent.AddView(view);
		}

		public Task<PopupResult> Show()
		{
			PopupTaskCompletionSource = new TaskCompletionSource<PopupResult>();
			AnimateAppearing();
			return PopupTaskCompletionSource.Task;
		}

		private void AnimateAppearing()
		{
			MainThread.BeginInvokeOnMainThread(delegate
			{
				_popupContainer.Animate().SetInterpolator(new DecelerateInterpolator()).SetDuration(300L)
					.TranslationY(0f)
					.Alpha(1f)
					.WithEndAction(new Runnable(OnDidAppear));
			});
		}

		protected virtual void OnDidAppear()
		{
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (!(propertyName == "CloseResult"))
			{
				if (propertyName == "Character")
				{
					SetCharacterPosition();
				}
			}
			else if (base.ViewModel.CloseResult != PopupResult.None)
			{
				ClosePopup(base.ViewModel.CloseResult);
			}
		}

		private string GetBackgroundImageName(object x)
		{
			if (x is PopupBackground)
			{
				switch ((PopupBackground)x)
				{
				case PopupBackground.Green:
					return "popup_background_green";
				case PopupBackground.Blue:
					return "popup_background_blue";
				case PopupBackground.Orange:
					return "popup_background_orange";
				case PopupBackground.Spotlights:
					return "background";
				}
			}
			return string.Empty;
		}

		private void OnShadowClicked(object sender, EventArgs eventArgs)
		{
			if (base.ViewModel.IsCloseOnShadowEnabled)
			{
				ClosePopup(PopupResult.None);
			}
		}

		private void OnCloseButtonClicked(object sender, EventArgs eventArgs)
		{
			ClosePopup(PopupResult.Closed);
		}

		protected void ClosePopup(PopupResult popupResult)
		{
			base.ViewModel.OnClose(popupResult);
			if (base.ViewModel.IsPossibleToClose)
			{
				PopupTaskCompletionSource?.TrySetResult(popupResult);
				if (base.Parent is ViewGroup viewGroup)
				{
					viewGroup.RemoveView(this);
				}
			}
		}

		private void UpdatePopupSize()
		{
			switch (PopupSize)
			{
			case PopupSize.Large:
				SetGuidePercent(2131297357, 0.05f);
				SetGuidePercent(2131297346, 0.95f);
				break;
			case PopupSize.Medium:
				SetGuidePercent(2131297357, 0.1f);
				SetGuidePercent(2131297346, 0.9f);
				break;
			default:
				SetGuidePercent(2131297357, 0.2f);
				SetGuidePercent(2131297346, 0.8f);
				break;
			}
		}

		private void SetCharacterPosition()
		{
			switch (base.ViewModel.Character)
			{
			case GT.Core.Character.AnnaCheer:
				SetGuidePercent(2131297348, 0.6f);
				break;
			case GT.Core.Character.ScoutPoint:
				SetGuidePercent(2131297348, 0.67f);
				break;
			case GT.Core.Character.ScoutCheer:
				SetGuidePercent(2131297348, 0.6f);
				break;
			case GT.Core.Character.CoachPoint:
				SetGuidePercent(2131297348, 0.67f);
				break;
			default:
				SetGuidePercent(2131297348, 0.57f);
				break;
			}
		}

		private void SetGuidePercent(int id, float percent)
		{
			Guideline guideline = FindViewById<Guideline>(id);
			if (guideline.LayoutParameters is ConstraintLayout.LayoutParams layoutParams)
			{
				layoutParams.GuidePercent = percent;
				guideline.LayoutParameters = layoutParams;
			}
		}
	}
