	public class BaseUIElement<T> : FrameLayout where T : NotifyObject
	{
		private BindingEngine _binding;

		protected T ViewModel { get; set; }

		public BaseUIElement(Context context)
			: base(context)
		{
			Initialize();
		}

		public BaseUIElement(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public BaseUIElement(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			_binding = new BindingEngine();
			_binding.PropertyChanged += OnBindingEnginePropertyChanged;
			LayoutParameters = new ViewGroup.LayoutParams(-1, -1);
		}

		protected View SetContent(int id)
		{
			return LayoutInflater.From(base.Context).Inflate(id, this, attachToRoot: true);
		}

		protected void SetContent(View view)
		{
			RemoveAllViews();
			AddView(view);
		}

		public void SetBindingContext(NotifyObject viewModel)
		{
			ViewModel = viewModel as T;
			_binding.SetBindingContext(ViewModel);
			Bind();
		}

		protected virtual void Bind()
		{
		}

		private void OnBindingEnginePropertyChanged(object sender, PropertyChangedEventArgs e)
		{
			OnPropertyChanged(e.PropertyName);
		}

		protected virtual void OnPropertyChanged(string propertyName)
		{
		}

		protected void Start()
		{
			_binding?.Start();
		}

		protected void Stop()
		{
			_binding?.Stop();
		}

		public void Bind(View view, ICommand command, object commandParameter = null)
		{
			command.CanExecuteChanged += delegate
			{
				Command_CanExecuteChanged(view, command, commandParameter);
			};
			view.Click += delegate
			{
				Button_Click(view, command, commandParameter);
			};
			if (!(view is GTButton))
			{
				view.SetSoundEffect();
			}
		}

		private void Command_CanExecuteChanged(View view, ICommand command, object commandParameter = null)
		{
			view.Enabled = command?.CanExecute(commandParameter) ?? true;
		}

		private void Button_Click(View view, ICommand command, object commandParameter = null)
		{
			object parameter = ((!(view is GTButton gTButton)) ? commandParameter : gTButton.CommandParameter);
			if (command != null && command.CanExecute(parameter))
			{
				command.Execute(parameter);
			}
		}

		public void Bind(EditText editText, string vmPropertyName)
		{
			_binding.Add(editText, "Text", vmPropertyName);
			editText.TextChanged += delegate
			{
				_binding.UpdateViewModel(vmPropertyName, editText.Text);
			};
		}

		public void Bind(GTSwitcher switcher, string vmPropertyName)
		{
			_binding.Add(switcher, "IsOn", vmPropertyName);
			switcher.IsOnChanged += delegate(object sender, SwitcherEventArgs e)
			{
				_binding.UpdateViewModel(vmPropertyName, e.IsOn);
			};
		}

		public void Bind(ComboBox comboBox, string selectedIndexPropertyName)
		{
			_binding.Add(comboBox, "SelectedIndex", selectedIndexPropertyName);
			comboBox.SelectedIndexChanged += delegate(object sender, SelectedIndexChangedEventArgs e)
			{
				_binding.UpdateViewModel(selectedIndexPropertyName, e.SelectedIndex);
			};
		}

		public void Bind(GTRangeSlider slider, string minValuePropertyName, string maxValuePropertyName)
		{
			slider.SelectedMinValueChanged += delegate(object sender, SliderValueChanged e)
			{
				_binding.UpdateViewModel(minValuePropertyName, e.Value);
			};
			slider.SelectedMaxValueChanged += delegate(object sender, SliderValueChanged e)
			{
				_binding.UpdateViewModel(maxValuePropertyName, e.Value);
			};
		}

		public void Bind(GTSlider slider, string vmPropertyName)
		{
			_binding.Add(slider, "Value", vmPropertyName);
			slider.ValueChanged += delegate(object sender, SliderValueChanged e)
			{
				_binding.UpdateViewModel(vmPropertyName, (decimal)e.Value);
			};
		}

		private View FindView(int viewId, View parent = null)
		{
			if (parent == null)
			{
				parent = this;
			}
			return parent.FindViewById(viewId) ?? throw new NullReferenceException($"View with id {viewId} not found");
		}

		public void Bind(int viewId, ICommand command)
		{
			View view = FindView(viewId);
			Bind(view, command);
		}

		public void Bind(View parent, int viewId, ICommand command)
		{
			View view = FindView(viewId, parent);
			Bind(view, command);
		}

		public void Bind(int viewId, string vmPropertyName)
		{
			View view = FindView(viewId);
			if (view is EditText editText)
			{
				Bind(editText, vmPropertyName);
			}
			else if (view is GTSwitcher switcher)
			{
				Bind(switcher, vmPropertyName);
			}
			else if (view is ComboBox comboBox)
			{
				Bind(comboBox, vmPropertyName);
			}
		}

		public void Bind(int viewId, string viewPropertyName, string vmPropertyName, Func<object, object> converter = null)
		{
			Bind(this, viewId, viewPropertyName, vmPropertyName, converter);
		}

		public void Bind(View parent, int viewId, string viewPropertyName, string vmPropertyName, Func<object, object> converter = null)
		{
			try
			{
				View view = FindView(viewId, parent);
				Bind(view, viewPropertyName, vmPropertyName, converter);
			}
			catch (System.Exception ex)
			{
				GT.Core.Log.Error(ex);
			}
		}

		public void Bind(View view, string viewPropertyName, string vmPropertyName, Func<object, object> converter = null, bool showLog = false)
		{
			if (view == null)
			{
				GT.Core.Log.Info("WARNING: view is null for " + vmPropertyName);
			}
			_binding.Add(view, viewPropertyName, vmPropertyName, converter, showLog);
			if (view is ComboBox comboBox && viewPropertyName == "SelectedValue")
			{
				comboBox.ItemSelected += delegate(object sender, ComboBoxItemSelectedEventArgs e)
				{
					_binding.UpdateViewModel(vmPropertyName, e.SelectedItem?.Value);
				};
			}
			if (view is GTSwitcher gTSwitcher && viewPropertyName == "IsOn" && converter == null)
			{
				gTSwitcher.IsOnChanged += delegate(object sender, SwitcherEventArgs e)
				{
					_binding.UpdateViewModel(vmPropertyName, e.IsOn);
				};
			}
		}
	}
