		}

		protected override void Bind()
		{
			Bind(2131297349, "Enabled", "IsGameNotRunning");
			Bind(2131297076, "Text", "LadderNameHome");
			Bind(2131297075, "Text", "LadderNameAway");
			Bind(2131297081, "ImageName", "LadderShirtHome");
			Bind(2131297080, "ImageName", "LadderShirtAway");
			Bind(2131297091, "ImageName", "LadderWappenHome");
			Bind(2131297090, "ImageName", "LadderWappenAway");
			GTStrengthStarsView gTStrengthStarsView = base.PopupContent.FindViewById<GTStrengthStarsView>(2131297084);
			gTStrengthStarsView.ForPlayer = false;
			Bind(gTStrengthStarsView, "Strength", "LadderStarsHome");
			GTStrengthStarsView gTStrengthStarsView2 = base.PopupContent.FindViewById<GTStrengthStarsView>(2131297083);
			gTStrengthStarsView2.ForPlayer = false;
			Bind(gTStrengthStarsView2, "Strength", "LadderStarsAway");
			Bind(2131297087, "Text", "LadderTacticHome");
			Bind(2131297086, "Text", "LadderTacticAway");
			Bind(2131297092, "Text", "LadderWinPts");
			Bind(2131297073, "Text", "LadderLosePts");
			GTButton view = base.PopupContent.FindViewById<GTButton>(2131297079);
			Bind(view, "Value", "Price");
			Bind(view, "Enabled", "IsRestoreButtonEnabled");
			Bind(view, base.ViewModel.RestoreStaminaCommand);
			Bind(this, "LadderStamina", "LadderStamina");
			Bind(2131297072, "Text", "HomeScore");
			Bind(2131297068, "Text", "AwayScore");
			_ladderTime = base.PopupContent.FindViewById<TextView>(2131297088);
			Bind(_ladderTime, "Text", "MatchTime", (object x) => x.ToString() + "'");
			_ladderMatchSpeedButton = base.PopupContent.FindViewById<TextView>(2131297074);
			Bind(_ladderMatchSpeedButton, "Text", "MatchSpeedMode", (object x) => GetMatchSpeedString((LadderMatchSpeed)x));
			Bind(_ladderMatchSpeedButton, base.ViewModel.UpMatchSpeedCommand);
			_ladderMatchSpeedButton.AddTouchEffect();
			GTButton view2 = base.PopupContent.FindViewById<GTButton>(2131297085);
			Bind(view2, "Title", "MatchCost", (object x) => string.Format("LadderStartGame".Translate(), x));
			Bind(view2, "Enabled", "IsRunButtonEnabled");
			Bind(view2, base.ViewModel.RunMatchCommand);
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			switch (propertyName)
			{
			case "IsGameStarted":
				if (base.ViewModel.IsGameStarted)
				{
					StartAnimation();
				}
				break;
			case "IsGameEnded":
				if (base.ViewModel.IsGameEnded)
				{
					ShowMatchResult();
				}
				break;
			case "CurrentEvent":
				if (base.ViewModel.CurrentEvent != null)
				{
					AddMessage(base.ViewModel.CurrentEvent);
				}
				break;
			}
		}

		private void StartAnimation()
		{
			ConstraintSet constraintSet = new ConstraintSet();
			constraintSet.Clone(base.Context, 2131493039);
			TransitionManager.BeginDelayedTransition(_layout);
			constraintSet.ApplyTo(_layout);
		}

		private void AddMessage(LadderEvent ladderEvent)
		{
			GT.Core.Log.Info($"{ladderEvent.Minute} : {ladderEvent.Message}");
			LadderMessageView ladderMessageView = new LadderMessageView(base.Context)
			{
				Id = View.GenerateViewId(),
				Text = ladderEvent.Message,
				Time = ladderEvent.Minute,
				IsHome = ladderEvent.IsHome,
				LayoutParameters = new ViewGroup.LayoutParams(0, -2),
				Alpha = 0f
			};
			_layout.AddView(ladderMessageView);
			ConstraintSet constraintSet = new ConstraintSet();
			constraintSet.Clone(_layout);
			constraintSet.Connect(ladderMessageView.Id, 3, _ladderTime.Id, 3);
			if (ladderEvent.IsHome)
			{
				constraintSet.Connect(ladderMessageView.Id, 1, _layout.Id, 1, 16);
				constraintSet.Connect(ladderMessageView.Id, 2, _ladderMatchSpeedButton.Id, 1);
			}
			else
			{
				constraintSet.Connect(ladderMessageView.Id, 2, _layout.Id, 2, 16);
				constraintSet.Connect(ladderMessageView.Id, 1, _ladderMatchSpeedButton.Id, 2);
			}
			ladderMessageView.Animate().Alpha(1f).SetDuration(350L);
			if (_lastMessage != null)
			{
				constraintSet.Clear(_lastMessage.Id, 3);
				constraintSet.Connect(_lastMessage.Id, 3, ladderMessageView.Id, 4);
			}
			TransitionManager.BeginDelayedTransition(_layout);
			constraintSet.ApplyTo(_layout);
			_lastMessage = ladderMessageView;
		}

		private string GetMatchSpeedString(LadderMatchSpeed speed)
		{
			string result = null;
			switch (speed)
			{
			case LadderMatchSpeed.x1:
				result = "x1";
				_ladderMatchSpeedButton.SetTextColor(2131034200.ToColor(base.Context));
				break;
			case LadderMatchSpeed.x2:
				result = "x2";
				_ladderMatchSpeedButton.SetTextColor(2131034164.ToColor(base.Context));
				break;
			case LadderMatchSpeed.x3:
				result = "x3";
				_ladderMatchSpeedButton.SetTextColor(2131034180.ToColor(base.Context));
				break;
			}
			return result;
		}

		private void ShowMatchResult()
		{
			decimal num = Math.Max(base.ViewModel.ResultHomeStrength + base.ViewModel.ResultAwayStrength, 1m);
			LadderMatchResult ladderMatchResult = new LadderMatchResult(base.Context)
			{
				Id = View.GenerateViewId(),
				HomeStrength = (int)base.ViewModel.ResultHomeStrength,
				AwayStrength = (int)base.ViewModel.ResultAwayStrength,
				HomePossession = (int)(base.ViewModel.ResultHomeStrength / num * 100m),
				AwayPossession = (int)(base.ViewModel.ResultAwayStrength / num * 100m)
			};
			if (base.ViewModel.CurrentEvent.HomeScore > base.ViewModel.CurrentEvent.AwayScore)
			{
				ladderMatchResult.Result = "Victory".Translate();
				ladderMatchResult.IsVictory = true;
			}
			if (base.ViewModel.CurrentEvent.HomeScore < base.ViewModel.CurrentEvent.AwayScore)
			{
				ladderMatchResult.Result = "Defeat".Translate();
				ladderMatchResult.IsVictory = false;
			}
			if (base.ViewModel.CurrentEvent.HomeScore == base.ViewModel.CurrentEvent.AwayScore)
			{
				ladderMatchResult.Result = "Draw".Translate();
			}
			_layout.AddView(ladderMatchResult);
			ConstraintSet constraintSet = new ConstraintSet();
			constraintSet.Clone(_layout);
			constraintSet.Connect(ladderMatchResult.Id, 3, _layout.Id, 3);
			constraintSet.Connect(ladderMatchResult.Id, 4, _layout.Id, 4);
			constraintSet.Connect(ladderMatchResult.Id, 2, _layout.Id, 2);
			constraintSet.Connect(ladderMatchResult.Id, 1, _layout.Id, 1);
			constraintSet.ApplyTo(_layout);
		}

		public void Close()
		{
			ClosePopup(PopupResult.None);
		}
	}
