		{
			Bind(_doneButton, "Title", "ConfirmButtonTitle");
			Bind(_doneButton, "IsPremium", "IsButtonPremium");
			Bind(_doneButton, "Value", "PriceValue");
			Bind(_message, "Text", "Message");
