		private void InitShirts()
		{
			_container.RemoveAllViews();
			for (int i = 1; i <= 99; i++)
			{
				ScrollTapItemView view = new ScrollTapItemView(base.Context)
				{
					Image = base.ViewModel.Shirt,
					Number = i
				};
				view.Click += delegate
				{
					OnViewClicked(view);
				};
				view.SetSoundEffect();
				_container.AddView(view);
			}
		}

