		{
			if (_container.ChildCount == 0)
			{
				return;
			}
			for (int i = 0; i < _container.ChildCount; i++)
			{
				ScrollTapItemView scrollTapItemView = _container.GetChildAt(i) as ScrollTapItemView;
				if (scrollTapItemView.IsSelected)
				{
					scrollTapItemView.IsSelected = false;
				}
			}
			view.IsSelected = !view.IsSelected;
			base.ViewModel.SelectedNumber = view.Number;
		}
	}
