	public class SelectionPopup : BasePopup<SelectionPopupViewModel>
	{
		private LinearLayout _container;

		public SelectionPopup(Context context)
			: base(context)
		{
			Initialize();
		}

		public SelectionPopup(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public SelectionPopup(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			SetPopupContent(2131493160);
			_container = FindViewById<LinearLayout>(2131297524);
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (!(propertyName == "SelectionItems"))
			{
				return;
			}
			_container.RemoveAllViews();
			if (base.ViewModel.SelectionItems == null)
			{
				return;
			}
			for (int i = 0; i < base.ViewModel.SelectionItems.Length; i++)
			{
				SelectionPopupItem selectionPopupItem = base.ViewModel.SelectionItems[i];
				SkillView view = new SkillView(base.Context)
				{
					Text = selectionPopupItem.Text,
					ImageName = selectionPopupItem.ImageName,
					LayoutParameters = new LinearLayout.LayoutParams(-2, -2),
					Tag = ((i == 0) ? "mainskill_set" : null)
				};
				int index = i;
				view.Click += delegate
				{
					OnViewClicked(view, index);
				};
				view.SetSoundEffect();
				_container.AddView(view);
			}
		}

		private void OnViewClicked(View view, int index)
		{
			base.ViewModel.SelectedIndex = index;
			if (!string.IsNullOrEmpty(view.Tag?.ToString()))
			{
				TutorialManager.Instance.ControlActivated(view.Tag.ToString());
			}
			ClosePopup(PopupResult.Done);
		}
	}
