	public class HelpshiftService : IHelpshiftService
	{
		private const string MANAGER_NAME = "Manager Name";

		private const string CLUB_NAME = "Club Name";

		private const string CREATION_DATE = "Creation Date";

		private const string LEAGUE = "League";

		private const string RANK = "Rank";

		private const string LIFETIME_VALUE = "Lifetime Value";

		private const string TOTAL_PURCHASES = "Total Purchases";

		private const string PLATFORM_NAME = "android";

		private const string PAYER = "payer";

		private const string NON_PAYER = "non-payer";

		private const string NEWBIE = "newbie";

		private const string VETERAN = "veteran";

		private const string VIP = "vip";

		private const string NO_LOGIN = "no-login";

		private readonly Context _context;

		public HelpshiftService(Context context)
		{
			_context = context;
		}

		public async Task ShowHelp(HelpSection helpSection)
		{
			bool num = await ComponentFactory.Resolve<ICredentialService>().IsLoggedIn();
			HelpshiftUserResponse helpshiftUserResponse = null;
			if (num)
			{
				helpshiftUserResponse = await ComponentFactory.Resolve<IUserService>().GetHelpshiftUserInfo();
			}
			List<string> list = new List<string> { "android" };
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			if (helpshiftUserResponse != null)
			{
				HelpshiftCore.Login(new HelpshiftUser.Builder(helpshiftUserResponse.UserId.ToString(), string.Empty).SetName(helpshiftUserResponse.ManagerName).Build());
				list.Add((helpshiftUserResponse.PurchasesAmount > 0) ? "payer" : "non-payer");
				DateTime dateTime = helpshiftUserResponse.CreationDate.ParseToDate();
				if (dateTime > DateTime.UtcNow.AddDays(-7.0))
				{
					list.Add("newbie");
				}
				else if (dateTime < DateTime.UtcNow.AddDays(-60.0))
				{
					list.Add("veteran");
				}
				if (helpshiftUserResponse.PurchasesLTV > 1000m)
				{
					list.Add("vip");
				}
				dictionary.Add("Manager Name", helpshiftUserResponse.ManagerName);
				dictionary.Add("Club Name", helpshiftUserResponse.ClubName);
				dictionary.Add("Creation Date", helpshiftUserResponse.CreationDate);
				dictionary.Add("League", helpshiftUserResponse.LeagueName);
				dictionary.Add("Rank", helpshiftUserResponse.UserLevel);
				dictionary.Add("Lifetime Value", $"{helpshiftUserResponse.PurchasesLTV:N2} EUR");
				dictionary.Add("Total Purchases", $"{helpshiftUserResponse.PurchasesAmount:N0}");
			}
			else
			{
				HelpshiftCore.ClearAnonymousUser();
				list.Add("no-login");
			}
			HelpshiftSupportMetadata customMetadata = new HelpshiftSupportMetadata(dictionary, list.ToArray());
			HelpshiftAPIConfig config = new HelpshiftAPIConfig.Builder().SetCustomMetadata(customMetadata).SetEnableContactUs(HsEnableContactUs.Always).SetEnableFullPrivacy(enableFullPrivacy: false)
				.Build();
			GT.Core.Log.Info($"display help: {helpSection}");
			if (helpSection == HelpSection.Contents)
			{
				HelpshiftSupport.ShowFAQs(_context, config);
				return;
			}
			int num2 = (int)helpSection;
			HelpshiftSupport.ShowSingleFAQ(num2.ToString(), _context, config);
		}
	}
