				{
					GT.Core.Log.Info("... WARNING! view not found: " + controlId);
				}
				else
				{
					GT.Core.Log.Info("... view " + controlId + " is hidden or disabled");
				}
				return false;
			}
			AddShadows(view);
			return true;
		}

		private void AddShadows(View control)
		{
			GT.Core.Log.Info("... will add shadow");
			_shadowLayout = CurrentMainContainer.FindViewWithTag("tutorial_shadow_layout") as TutorialShadowLayout;
