			Rect rect = new Rect();
			control.GetGlobalVisibleRect(rect);
			rect.Offset(-RootMainContainer.PaddingLeft, 0);
			_shadowLayout.SetHolePosition(rect);
			_shadowLayout.Show();
			GT.Core.Log.Info($"... added shadow with hole in {rect}");
