	public class TutorialArrow : ImageView
	{
		private readonly TranslateAnimation _animation;

		private AnimatorSet _moveAnimationSet;

		public TutorialArrow(Context context)
			: base(context)
		{
			SetImageResource(2131166172);
			SetScaleType(ScaleType.CenterInside);
			_animation = new TranslateAnimation(0f, 0f, -30f, 30f)
			{
				Duration = 500L,
				RepeatMode = RepeatMode.Reverse,
				RepeatCount = -1
			};
		}

		public void StartAnimation()
		{
			StartAnimation(_animation);
			GT.Core.Log.Info("... arrow animation started");
		}

		public void StopAnimation()
		{
			ClearAnimation();
			_moveAnimationSet?.Cancel();
			TranslationX = 0f;
			TranslationY = 0f;
			Rotation = 0f;
			GT.Core.Log.Info("... arrow animation is stopped");
		}

		public void StartMoveAnimation(float dx, float dy)
		{
			StopAnimation();
			ObjectAnimator objectAnimator = ObjectAnimator.OfFloat(this, "translationX", dx);
			objectAnimator.SetDuration(2000L);
			objectAnimator.RepeatMode = ValueAnimatorRepeatMode.Restart;
			objectAnimator.RepeatCount = -1;
			ObjectAnimator objectAnimator2 = ObjectAnimator.OfFloat(this, "translationY", dy);
			objectAnimator2.SetDuration(2000L);
			objectAnimator2.RepeatMode = ValueAnimatorRepeatMode.Restart;
			objectAnimator2.RepeatCount = -1;
			ObjectAnimator objectAnimator3 = ObjectAnimator.OfFloat(this, "rotation", 90f);
			objectAnimator3.SetDuration(2000L);
			objectAnimator3.RepeatMode = ValueAnimatorRepeatMode.Restart;
			objectAnimator3.RepeatCount = -1;
			_moveAnimationSet = new AnimatorSet();
			_moveAnimationSet.Play(objectAnimator).With(objectAnimator2).With(objectAnimator3);
			_moveAnimationSet.Start();
		}
	}
	public class TutorialShadowLayout : FrameLayout
	{
		public const float ShadowAlpha = 0.6f;

		private readonly TutorialShadowHole _hole;

		private readonly TutorialShadow _left;

		private readonly TutorialShadow _right;

		private readonly TutorialShadow _top;

		private readonly TutorialShadow _bottom;

		private readonly TutorialArrow _arrow;

		private Rect _holeRect;

		public TutorialShadowLayout(Context context)
			: base(context)
		{
			_left = AddShadowView();
			_right = AddShadowView();
			_top = AddShadowView();
			_bottom = AddShadowView();
			_hole = new TutorialShadowHole(context);
			AddView(_hole);
			_arrow = new TutorialArrow(context);
			AddView(_arrow);
		}

		private TutorialShadow AddShadowView()
		{
			TutorialShadow tutorialShadow = new TutorialShadow(base.Context);
			AddView(tutorialShadow);
			return tutorialShadow;
		}

		public void SetHolePosition(Rect rect)
		{
			_holeRect = rect;
			ForceLayout();
		}

		public void Show()
		{
			GT.Core.Log.Info("... show shadow layout");
			SetAlpha(transparent: false);
			Visibility = ViewStates.Visible;
			_arrow.StartAnimation();
		}

		private void SetAlpha(bool transparent)
		{
			float alpha = (transparent ? 0f : 0.6f);
			_left.Alpha = alpha;
			_right.Alpha = alpha;
			_top.Alpha = alpha;
			_bottom.Alpha = alpha;
			_hole.Alpha = alpha;
		}

		public void ShowNextArea(Rect rect)
		{
			GT.Core.Log.Info($"... try to run animation to next area: {rect}");
			SetAlpha(transparent: true);
			int num = rect.Bottom - _holeRect.Top;
			_arrow.StartMoveAnimation(rect.Right - _holeRect.CenterX(), num);
		}

		public void Hide(bool hideArrow, Action callback)
		{
			GT.Core.Log.Info("... hide shadow layout");
			_arrow.StopAnimation();
			Visibility = ViewStates.Gone;
			callback?.Invoke();
		}

		protected override void OnLayout(bool changed, int left, int top, int right, int bottom)
		{
			GT.Core.Log.Info($"... shadow layout ltrb: {left}, {top}, {right}, {bottom}");
			_hole.Layout(_holeRect.Left, _holeRect.Top, _holeRect.Right, _holeRect.Bottom);
			_left.Layout(0, 0, _holeRect.Left, bottom);
			_right.Layout(_holeRect.Right, 0, right, bottom);
			_top.Layout(_holeRect.Left, 0, _holeRect.Right, _holeRect.Top);
			_bottom.Layout(_holeRect.Left, _holeRect.Bottom, _holeRect.Right, bottom);
			bool flag = (double)(_holeRect.Top + _holeRect.Bottom) * 0.5 < (double)bottom * 0.5;
			int num = bottom / 6;
			int num2 = (int)((double)(_holeRect.Right + _holeRect.Left - num) * 0.5);
			int num3 = (flag ? _holeRect.Bottom : (_holeRect.Top - num));
			_arrow.Layout(num2, num3, num2 + num, num3 + num);
			_arrow.ScaleY = ((!flag) ? 1 : (-1));
		}
	}
