	public class SoundManager : ISoundManager
	{
		private MediaPlayer _musicPlayer;

		private readonly Dictionary<Sounds, MediaPlayer> _soundPlayers;

		private readonly Context _context;

		private IPreferencesService _preferencesService;

		private bool _isSoundEnabled;

		private IPreferencesService PreferencesService => _preferencesService ?? (_preferencesService = ComponentFactory.Resolve<IPreferencesService>());

		public SoundManager(Context context)
		{
			_context = context;
			_soundPlayers = new Dictionary<Sounds, MediaPlayer>();
		}

		public void SetSoundEnabled(bool isEnabled)
		{
			_isSoundEnabled = isEnabled;
		}

		private void CreatePlayer()
		{
			_musicPlayer = MediaPlayer.Create(_context, 2131755012);
			_musicPlayer.Looping = true;
			_musicPlayer.SetVolume(100f, 100f);
		}

		public void PauseMusic()
		{
			if (_musicPlayer != null && _musicPlayer.IsPlaying)
			{
				_musicPlayer.Pause();
			}
		}

		public void PlayMusic()
		{
			SetSoundEnabled(PreferencesService.IsSoundEnabled);
			if (PreferencesService.IsMusicEnabled)
			{
				if (_musicPlayer == null)
				{
					CreatePlayer();
				}
				if (!_musicPlayer.IsPlaying)
				{
					_musicPlayer.Start();
				}
			}
		}

		private int GetSoundId(Sounds sound)
		{
			return sound switch
			{
				Sounds.Menu => 2131755009, 
				Sounds.Money => 2131755011, 
				Sounds.Stamp => 2131755014, 
				Sounds.Signature => 2131755013, 
				Sounds.Swipe => 2131755015, 
				_ => 2131755008, 
			};
		}

		public void PlaySound(Sounds sound)
		{
			if (_isSoundEnabled)
			{
				if (!_soundPlayers.TryGetValue(sound, out var value))
				{
					value = MediaPlayer.Create(_context, GetSoundId(sound));
					value.SetVolume(100f, 100f);
					_soundPlayers[sound] = value;
				}
				if (value.IsPlaying)
				{
					value.Pause();
					value.SeekTo(0);
				}
				value.Start();
			}
		}
	}
	public class FacebookCallback : Java.Lang.Object, IFacebookCallback, IJavaObject, IDisposable, IJavaPeerable, GraphRequest.IGraphJSONObjectCallback
	{
		private const string ID_FIELD_KEY = "id";

		private const string EMAIL_FIELD_KEY = "email";

		private const string FIELDS_KEY = "fields";

		private readonly FacebookAccessTokenTracker _accessTokenTracker;

		public Action<FacebookAuthResult> Connected { get; set; }

		public FacebookCallback()
		{
			_accessTokenTracker = new FacebookAccessTokenTracker
			{
				TokenChanged = OnTokenChangedAction
			};
			_accessTokenTracker.StartTracking();
		}

		public void OnCancel()
		{
			GT.Core.Log.Info("Facebook on cancel");
			Connected?.Invoke(new FacebookAuthResult
			{
				CallBack = CallbackType.Cancelled
			});
		}

		public void OnCompleted(JSONObject @object, GraphResponse response)
		{
			string userId = string.Empty;
			string email = string.Empty;
			if (@object != null && @object.Has("id"))
			{
				userId = @object.GetString("id");
			}
			if (@object != null && @object.Has("email"))
			{
				email = @object.GetString("email");
			}
			FacebookAuthResult obj = new FacebookAuthResult
			{
				CallBack = CallbackType.Success,
				UserId = userId,
				Email = email
			};
			Connected?.Invoke(obj);
		}

		public void OnError(FacebookException error)
		{
			GT.Core.Log.Info("Facebook on error: " + error?.Message);
			Connected?.Invoke(new FacebookAuthResult
			{
				CallBack = CallbackType.Failed
			});
		}

		public void OnSuccess(Java.Lang.Object result)
		{
			GT.Core.Log.Info($"Facebook on success: {result}, {result.GetType()}");
			if (result is LoginResult loginResult)
			{
				MakeGraphRequest(loginResult.AccessToken);
			}
		}

		private void MakeGraphRequest(AccessToken token)
		{
			Bundle bundle = new Bundle();
			bundle.PutString("fields", "id, email");
			GraphRequest graphRequest = GraphRequest.NewMeRequest(token, this);
			graphRequest.Parameters = bundle;
			graphRequest.ExecuteAsync();
		}

		private void OnTokenChangedAction(AccessToken token)
		{
			GT.Core.Log.Info($"Facebook token changed: {token}");
			if (token == null)
			{
				Connected?.Invoke(new FacebookAuthResult
				{
					CallBack = CallbackType.LoggedOut
				});
			}
			else
			{
				MakeGraphRequest(token);
			}
		}
	}
