	public class FacebookService : IFacebookService
	{
		private readonly MainActivity _context;

		private readonly FacebookCallback _facebookCallback;

		private TaskCompletionSource<FacebookAuthResult> _taskCompletionSource;

		private Action<FacebookAuthResult> _actionCallback;

		public string UserId { get; private set; }

		public FacebookService(MainActivity context)
		{
			_context = context;
			_facebookCallback = new FacebookCallback
			{
				Connected = OnFacebookConnected
			};
			LoginManager.Instance.RegisterCallback(_context.FacebookCallbackManager, _facebookCallback);
			UserId = AccessToken.CurrentAccessToken?.UserId;
		}

		public Task<FacebookAuthResult> LoginAsync()
		{
			_taskCompletionSource = new TaskCompletionSource<FacebookAuthResult>();
			LoginManager.Instance.LogInWithReadPermissions((Activity)(object)_context, Settings.FacebookExtendedPermissions);
			return _taskCompletionSource.Task;
		}

		public void Logout()
		{
			LoginManager.Instance.LogOut();
		}

		private void OnFacebookConnected(FacebookAuthResult facebookAuthResult)
		{
			GT.Core.Log.Info($"Facebook service on connected: {facebookAuthResult}");
			UserId = facebookAuthResult.UserId;
			_actionCallback?.Invoke(facebookAuthResult);
			_taskCompletionSource?.TrySetResult(facebookAuthResult);
		}

		public void SetCallback(Action<FacebookAuthResult> callback)
		{
			_actionCallback = callback;
		}
	}
