	public class GradientProgressBar : FrameLayout
	{
		private TextView _textView;

		private TextView _largeTextView;

		private StadiumProgressBar _progressBar;

		private ValueAnimator _animator;

		private decimal _progress;

		public string Text { get; set; }

		public string Sign { get; set; }

		public decimal Progress
		{
			get
			{
				return _progress;
			}
			set
			{
				_animator.SetFloatValues((float)_progress, (float)value);
				_animator.Start();
				_progress = value;
			}
		}

		public GradientProgressBar(Context context)
			: base(context)
		{
			Initialize();
		}

		public GradientProgressBar(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public GradientProgressBar(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.FromContext(base.Context).Inflate(2131492950, this, attachToRoot: true);
			_textView = view.FindViewById<TextView>(2131296905);
			_largeTextView = view.FindViewById<TextView>(2131296902);
			_progressBar = view.FindViewById<StadiumProgressBar>(2131296903);
			view.FindViewById<View>(2131296904).ClipToOutline = true;
			_animator = new ValueAnimator();
			_animator.SetDuration(1000L);
			_animator.SetInterpolator(new DecelerateInterpolator());
			_animator.Update += OnAnimatorUpdate;
			RefreshProgress(0f);
		}

		private void RefreshProgress(float value)
		{
			_progressBar.Progress = (decimal)value;
			if (string.IsNullOrEmpty(Text))
			{
				_largeTextView.Text = $"{value:N1}{Sign}";
				_largeTextView.Visibility = ViewStates.Visible;
				_textView.Visibility = ViewStates.Gone;
			}
			else
			{
				_textView.Text = $"{Text}: {value:N1}{Sign}";
				_textView.Visibility = ViewStates.Visible;
				_largeTextView.Visibility = ViewStates.Gone;
			}
		}

		private void OnAnimatorUpdate(object sender, ValueAnimator.AnimatorUpdateEventArgs e)
		{
			float value = (float)e.Animation.AnimatedValue;
			RefreshProgress(value);
		}

		protected override void Dispose(bool disposing)
		{
			base.Dispose(disposing);
			if (disposing && _animator != null)
			{
				_animator.Cancel();
				_animator.Update -= OnAnimatorUpdate;
				_animator.Dispose();
			}
		}
	}
	public class TouchListener : Java.Lang.Object, View.IOnTouchListener, IJavaObject, IDisposable, IJavaPeerable
	{
		public ICommand Command { get; set; }

		public object CommandParameter { get; set; }

		public Action Callback { get; set; }

		public bool OnTouch(View v, MotionEvent e)
		{
			if (e.Action == MotionEventActions.Down)
			{
				if (Callback != null)
				{
					Callback();
					return true;
				}
				if (Command != null && Command.CanExecute(CommandParameter))
				{
					Command.Execute(CommandParameter);
					return true;
				}
			}
			return false;
		}
	}
