	public class AndroidNotificationManager : INotificationManager
	{
		private class IdMapping
		{
			public string Key { get; set; }

			public int Id { get; set; }

			public DateTime Date { get; set; }

			public IdMapping()
			{
			}

			public IdMapping(string key, int id)
			{
				Key = key;
				Id = id;
				Date = DateTime.Today;
			}
		}

		private const string idMappingPreferenceKey = "notification_id_mapping";

		private const string channelId = "default";

		private const string channelName = "Default";

		private const string channelDescription = "The default channel for notifications.";

		public const string IdKey = "id";

		public const string TitleKey = "title";

		public const string MessageKey = "message";

		public const string IconKey = "icon";

		public const string ParameterKey = "parameter";

		private bool _isManagerInitialized;

		private NotificationManager _manager;

		private List<IdMapping> _map;

		public static AndroidNotificationManager Instance { get; private set; }

		public AndroidNotificationManager()
		{
			if (Instance == null)
			{
				InitializeManager();
				Instance = this;
			}
			ReadOrCreateMap();
			DateTime oldDate = DateTime.Today.AddDays(-31.0);
			IdMapping[] array = _map.Where((IdMapping x) => x.Date < oldDate).ToArray();
			foreach (IdMapping item in array)
			{
				_map.Remove(item);
			}
		}

		public void SendNotification(NotificationData notification, DateTime? notifyTime = null)
		{
			if (!notifyTime.HasValue || !(notifyTime.Value < DateTime.Now))
			{
				if (!_isManagerInitialized)
				{
					InitializeManager();
				}
				if (notifyTime.HasValue)
				{
					DelayNotification(notifyTime.Value, notification);
				}
				else
				{
					ShowInApp(notification);
				}
			}
		}

		private Intent GetIntentFromNotificationData(NotificationData notification)
		{
			Intent intent = new Intent(Application.Context, typeof(AlarmHandler));
			intent.PutExtra("id", notification.Id);
			intent.PutExtra("title", notification.Title);
			intent.PutExtra("message", notification.Message);
			intent.PutExtra("icon", notification.Icon);
			intent.PutExtra("parameter", notification.Parameter);
			return intent;
		}

		private void DelayNotification(DateTime dateTime, NotificationData notification)
		{
			TryGetIntId(notification.Id, remove: false, out var id);
			PendingIntent broadcast = PendingIntent.GetBroadcast(Application.Context, id, GetIntentFromNotificationData(notification), GetFlags());
			long notifyTime = GetNotifyTime(dateTime);
			(Application.Context.GetSystemService("alarm") as AlarmManager).Set(AlarmType.RtcWakeup, notifyTime, broadcast);
		}

		private void CancelAlarm(int id)
		{
			Intent intent = new Intent(Application.Context, typeof(AlarmHandler));
			PendingIntent broadcast = PendingIntent.GetBroadcast(Application.Context, id, intent, GetFlags());
			(Application.Context.GetSystemService("alarm") as AlarmManager).Cancel(broadcast);
		}

		private void ReadOrCreateMap()
		{
			if (_map != null)
			{
				return;
			}
			string value = Preferences.Get("notification_id_mapping", string.Empty);
			if (string.IsNullOrEmpty(value))
			{
				_map = new List<IdMapping>();
				return;
			}
			try
			{
				_map = JsonConvert.DeserializeObject<List<IdMapping>>(value);
			}
			catch
			{
				_map = new List<IdMapping>();
			}
		}

		private bool TryGetIntId(string key, bool remove, out int id)
		{
			ReadOrCreateMap();
			id = 0;
			IdMapping idMapping = _map.FirstOrDefault((IdMapping x) => x.Key == key);
			if (idMapping == null && remove)
			{
				return false;
			}
			id = idMapping?.Id ?? ((_map.Count <= 0) ? 1 : (_map.Max((IdMapping x) => x.Id) + 1));
			bool flag = false;
			if (idMapping == null && !remove)
			{
				_map.Add(new IdMapping(key, id));
				flag = true;
			}
			if (idMapping != null && remove)
			{
				_map.Remove(idMapping);
				flag = true;
			}
			if (flag)
			{
				string text = JsonConvert.SerializeObject(_map);
				Preferences.Set("notification_id_mapping", text);
				GT.Core.Log.Info("set id preference: " + text);
			}
			return true;
		}

		public void ShowNotification(NotificationData notification)
		{
			ActivityManager.RunningAppProcessInfo runningAppProcessInfo = new ActivityManager.RunningAppProcessInfo();
			ActivityManager.GetMyMemoryState(runningAppProcessInfo);
			if (runningAppProcessInfo.Importance == Importance.Foreground || runningAppProcessInfo.Importance == Importance.Visible)
			{
				ShowInApp(notification);
				CancelNotification(notification.Id);
			}
			else
			{
				ShowInBackground(notification);
			}
		}

		private void ShowInApp(NotificationData notification)
		{
			ComponentFactory.Resolve<IShell>().ShowNotification(notification);
		}

		private void ShowInBackground(NotificationData data)
		{
			if (!_isManagerInitialized)
			{
				InitializeManager();
			}
			TryGetIntId(data.Id, remove: true, out var id);
			PendingIntent activity = PendingIntent.GetActivity(Application.Context, id, new Intent(Application.Context, typeof(MainActivity)), GetFlags());
			Notification notification = new NotificationCompat.Builder(Application.Context, "default").SetContentIntent(activity).SetContentTitle(data.Title).SetContentText(data.Message)
				.SetSmallIcon(2131165842)
				.SetDefaults(3)
				.SetAutoCancel(autoCancel: true)
				.Build();
			_manager.Notify(id, notification);
		}

		private PendingIntentFlags GetFlags()
		{
			if (Build.VERSION.SdkInt < BuildVersionCodes.S)
			{
				return PendingIntentFlags.UpdateCurrent;
			}
			return PendingIntentFlags.Immutable | PendingIntentFlags.UpdateCurrent;
		}

		private void InitializeManager()
		{
			_manager = (NotificationManager)Application.Context.GetSystemService("notification");
			if (Build.VERSION.SdkInt >= BuildVersionCodes.O)
			{
				Java.Lang.String name = new Java.Lang.String("Default");
				NotificationChannel channel = new NotificationChannel("default", name, NotificationImportance.Default)
				{
					Description = "The default channel for notifications."
				};
				_manager.CreateNotificationChannel(channel);
			}
			_isManagerInitialized = true;
		}

		private long GetNotifyTime(DateTime notifyTime)
		{
			DateTime dateTime = TimeZoneInfo.ConvertTimeToUtc(notifyTime);
			double totalSeconds = (new DateTime(1970, 1, 1) - DateTime.MinValue).TotalSeconds;
			return dateTime.AddSeconds(0.0 - totalSeconds).Ticks / 10000;
		}

		public void CancelNotification(params string[] ids)
		{
			if (!_isManagerInitialized)
			{
				InitializeManager();
			}
			if (ids == null || ids.Length == 0)
			{
				_manager.CancelAll();
				return;
			}
			foreach (string key in ids)
			{
				if (TryGetIntId(key, remove: true, out var id))
				{
					_manager.Cancel(id);
					CancelAlarm(id);
				}
			}
		}

		public void SubscribeToChannel(string userId)
		{
			FirebaseMessaging.Instance.SubscribeToTopic("global");
			FirebaseMessaging.Instance.SubscribeToTopic(userId);
			GT.Core.Log.Info("FCM - subscribed to channels: global, " + userId);
		}

		public void Unsubscribe(string userId)
		{
			FirebaseMessaging.Instance.UnsubscribeFromTopic(userId);
		}

		public void RequestPermissions()
		{
		}
	}
	[BroadcastReceiver(Enabled = true, Label = "Local Notifications Broadcast Receiver")]
	public class AlarmHandler : BroadcastReceiver
	{
		public override void OnReceive(Context context, Intent intent)
		{
			if (intent?.Extras != null)
			{
				string stringExtra = intent.GetStringExtra("id");
				string stringExtra2 = intent.GetStringExtra("title");
				string stringExtra3 = intent.GetStringExtra("message");
				string stringExtra4 = intent.GetStringExtra("icon");
				string stringExtra5 = intent.GetStringExtra("parameter");
				(AndroidNotificationManager.Instance ?? new AndroidNotificationManager()).ShowNotification(new NotificationData(stringExtra, stringExtra2, stringExtra3, stringExtra4, stringExtra5));
			}
		}
	}
	public class SoundTouchListener : Java.Lang.Object, View.IOnTouchListener, IJavaObject, IDisposable, IJavaPeerable
	{
		private readonly ISoundManager _soundManager;

		private readonly Sounds _sound;

		private bool _isPressed;

		public SoundTouchListener(Sounds sound = Sounds.Button)
		{
			_soundManager = ComponentFactory.Resolve<ISoundManager>();
			_sound = sound;
		}

		public bool OnTouch(View v, MotionEvent e)
		{
			if (!v.Enabled || v.Selected)
			{
				return false;
			}
			switch (e.Action)
			{
			case MotionEventActions.Up:
				if (_isPressed)
				{
					_soundManager.PlaySound(_sound);
				}
				break;
			case MotionEventActions.Outside:
				_isPressed = false;
				break;
			case MotionEventActions.Down:
				_isPressed = true;
				break;
			}
			return false;
		}
	}
