		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493035, this, attachToRoot: true);
			_surfaceView = view.FindViewById<SurfaceView>(2131297055);
			_surfaceView.Click += OnDummyClick;
			_surfaceView.SoundEffectsEnabled = false;
			_button = view.FindViewById<GTButton>(2131297054);
			_button.Click += OnSkipButtonClick;
			if (!IsInEditMode)
			{
				Visibility = ComponentFactory.Resolve<IPreferencesService>().IntroVideoPlayed.ToInverseVisibility();
			}
		}

		private void OnSkipButtonClick(object sender, EventArgs e)
		{
			_button.Enabled = false;
			MediaPlayer player = _player;
			if (player != null && player.IsPlaying)
			{
				_player?.Stop();
			}
			OnVideoEnded();
		}

		private void OnDummyClick(object sender, EventArgs e)
		{
		}

		public void StartVideo()
		{
			if (Visibility == ViewStates.Visible)
			{
				ComponentFactory.Resolve<IShell>().HideTopBar();
				_player = MediaPlayer.Create(base.Context, 2131755010);
				_player.SetVolume(100f, 100f);
				_player.SetVideoScalingMode(VideoScalingMode.ScaleToFitWithCropping);
				_player.SetOnCompletionListener(new OnCompletionListener(delegate
				{
					OnVideoEnded();
				}));
				_surfaceView.Holder.AddCallback(new SurfaceCallback(_player));
			}
		}

		private void OnVideoEnded()
		{
			_button.Enabled = false;
			View shadow = FindViewById<View>(2131297053);
			shadow.Click += OnDummyClick;
			shadow.SoundEffectsEnabled = false;
			shadow.Alpha = 0f;
			shadow.Visibility = ViewStates.Visible;
			ComponentFactory.Resolve<IPreferencesService>().IntroVideoPlayed = true;
			ComponentFactory.Resolve<ISoundManager>().PlayMusic();
			shadow.FadeIn(delegate
			{
				_surfaceView.Visibility = ViewStates.Gone;
				_button.Visibility = ViewStates.Gone;
				ComponentFactory.Resolve<IShell>().ShowTopBar();
				shadow.FadeOut(delegate
				{
					Visibility = ViewStates.Gone;
					if (base.Parent is ViewGroup viewGroup)
					{
						viewGroup.RemoveView(this);
					}
				}, 1000);
			}, 1000);
		}
	}
