	public class SideNotificationView : FrameLayout
	{
		private const long _animationDuration = 300L;

		private const long _viewDuration = 9000L;

		private const long _viewDurationShort = 3000L;

		private readonly DecelerateInterpolator _decelerate = new DecelerateInterpolator();

		private readonly AccelerateInterpolator _accelerate = new AccelerateInterpolator();

		private ISoundManager _soundManager;

		private IDeviceService _deviceService;

		private TextView _titleLabel;

		private TextView _textLabel;

		private ImageView _icon;

		public bool IsSpecial { get; private set; }

		public event EventHandler Finished;

		public SideNotificationView(Context context)
			: base(context)
		{
			Initialize();
		}

		public SideNotificationView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public SideNotificationView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493156, this, attachToRoot: true);
			_titleLabel = view.FindViewById<TextView>(2131297274);
			_textLabel = view.FindViewById<TextView>(2131297273);
			_icon = view.FindViewById<ImageView>(2131297270);
			base.Click += OnClick;
			SoundEffectsEnabled = false;
			if (!IsInEditMode)
			{
				_soundManager = ComponentFactory.Resolve<ISoundManager>();
				_deviceService = ComponentFactory.Resolve<IDeviceService>();
			}
		}

		private void OnClick(object sender, EventArgs e)
		{
			Hide();
		}

		public void Show(NotificationData notification)
		{
			IsSpecial = notification.IsSpecial;
			TranslationX = -base.Width;
			Visibility = ViewStates.Visible;
			_icon.SetImageResource(notification.Icon.GetImageId(base.Context));
			_titleLabel.Text = string.Empty;
			_titleLabel.Visibility = notification.Title.HideIfNullOrEmpty();
			_textLabel.Text = notification.Message;
			Animate().SetDuration(300L).TranslationX(0f).SetInterpolator(_decelerate);
			_soundManager.PlaySound(Sounds.Swipe);
			_deviceService.PerformAfterDelay(Hide, notification.IsSpecial ? 3000 : 9000);
		}

		private void Hide()
		{
			if (!(TranslationX < 0f))
			{
				Animate().SetDuration(300L).TranslationX(-base.Width).SetInterpolator(_accelerate)
					.WithEndAction(new Runnable(OnFinished));
				_soundManager.PlaySound(Sounds.Swipe);
			}
		}

		private void OnFinished()
		{
			IsSpecial = false;
			Visibility = ViewStates.Gone;
			this.Finished?.Invoke(this, EventArgs.Empty);
		}
	}
