	public class SkillsView : LinearLayout
	{
		private Dictionary<TableCellColor, Color> _colors;

		private List<SkillProgressData> _skills;

		public List<SkillProgressData> Skills
		{
			get
			{
				return _skills;
			}
			set
			{
				_skills = value;
				Update();
			}
		}

		public SkillsView(Context context)
			: base(context)
		{
			Initialize(null);
		}

		public SkillsView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize(attrs);
		}

		public SkillsView(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize(attrs);
		}

		private void Initialize(IAttributeSet attrs)
		{
			Orientation = Android.Widget.Orientation.Vertical;
			_colors = new Dictionary<TableCellColor, Color>
			{
				[TableCellColor.Default] = 2131034200.ToColor(base.Context),
				[TableCellColor.Highlight] = 2131034180.ToColor(base.Context),
				[TableCellColor.Accent] = 2131034164.ToColor(base.Context)
			};
		}

		private void Update()
		{
			RemoveAllViews();
			if (Skills == null)
			{
				return;
			}
			foreach (SkillProgressData skill in Skills)
			{
				View view = LayoutInflater.From(base.Context).Inflate(2131493167, null);
				if (!skill.IsVisible)
				{
					view.Visibility = ViewStates.Invisible;
				}
				else
				{
					TextView textView = view.FindViewById<TextView>(2131297590);
					TextView textView2 = view.FindViewById<TextView>(2131297592);
					TextView textView3 = view.FindViewById<TextView>(2131297589);
					GTProgressBar gTProgressBar = view.FindViewById<GTProgressBar>(2131297591);
					textView.Text = skill.Name;
					textView.SetTextColor(_colors[skill.Color]);
					textView2.Text = skill.Text;
					if (skill.IsHighlighted)
					{
						textView2.SetTextColor(_colors[TableCellColor.Highlight]);
					}
					textView3.Text = $"+{skill.Increase:N2}";
					textView3.Visibility = (Math.Round(skill.Increase, 2) > 0m).ToVisibility();
					gTProgressBar.MaxValue = skill.MaxValue;
					gTProgressBar.Progress = skill.Value;
				}
				AddView(view);
			}
		}
	}
	public class SkillCardsCollection : GTRecyclerView
	{
		public SkillCardsCollection(Context context)
			: base(context)
		{
			Initialize();
		}

		private void Initialize()
		{
			OverScrollMode = OverScrollMode.Never;
			base.HeaderTemplate = 2131493171;
			base.ItemTemplate = 2131493158;
			base.ItemType = typeof(SkillCardView);
			BindHeader();
			(int, int) screenSize = base.Context.GetScreenSize();
			int item = screenSize.Item1;
			int num = (int)((double)screenSize.Item2 * 0.42);
			double num2 = 0.7142857142857143 * (double)item;
			double num3 = (double)num / 1.4;
			int num4 = (int)(num2 / num3);
			GridLayoutManager gridLayoutManager = new GridLayoutManager(base.Context, num4, 1, reverseLayout: false);
			gridLayoutManager.SetSpanSizeLookup(new HeaderSpanLookup(num4));
			SetLayoutManager(gridLayoutManager);
		}

		private void BindHeader()
		{
			Bind(2131297579, "Enabled", "SelectedPlayer", (object x) => false);
			Bind(2131297580, "Value", "SelectedPlayer", (object x) => $"{(x as SquadPlayerData)?.Age}");
