	public static class ContextExtension
	{
		public static (int, int) GetScreenSize(this Context context)
		{
			if (!(context is Activity activity))
			{
				return (-1, -1);
			}
			int item;
			int item2;
			if (Build.VERSION.SdkInt >= BuildVersionCodes.R)
			{
				Rect bounds = activity.WindowManager.MaximumWindowMetrics.Bounds;
				item = bounds.Width();
				item2 = bounds.Height();
			}
			else
			{
				Android.Graphics.Point point = new Android.Graphics.Point();
				activity.WindowManager.DefaultDisplay.GetRealSize(point);
				item2 = point.Y;
				item = point.X;
			}
			return (item, item2);
		}
	}
	public static class DrawableExtension
	{
		public static Drawable WithFade(this Drawable drawable, int alpha)
		{
			if (drawable == null)
			{
				return drawable;
			}
			Drawable drawable2 = drawable.GetConstantState().NewDrawable();
			PorterDuffColorFilter colorFilter = new PorterDuffColorFilter(new Color(0, 0, 0, alpha), PorterDuff.Mode.SrcAtop);
			drawable2.Mutate();
			drawable2.SetColorFilter(colorFilter);
			return drawable2;
		}
	}
	public class SkillCardView : FrameLayout, ICollectionCellView
	{
		private SkillCard _card;

		private readonly TextView _name;

		private readonly TextView _bonus;

		private readonly GTImageView _image;

		private readonly View _star1;

		private readonly View _star2;

		private readonly TextView _count;

		private readonly View _frame;

		private readonly View _frame1;

		private readonly View _frame2;

		private readonly View _frame3;

		public SkillCard Card
		{
			get
			{
				return _card;
			}
			set
			{
				_card = value;
				Update(_card);
			}
		}

		public SkillCardView(Context context)
			: base(context)
		{
			View view = LayoutInflater.From(base.Context).Inflate(2131493158, this, attachToRoot: true);
			_name = view.FindViewById<TextView>(2131297510);
			_bonus = view.FindViewById<TextView>(2131297506);
			_image = view.FindViewById<GTImageView>(2131297509);
			_star1 = view.FindViewById<View>(2131297512);
			_star2 = view.FindViewById<View>(2131297513);
			_count = view.FindViewById<TextView>(2131297508);
			_frame = view.FindViewById<View>(2131297514);
			_frame1 = view.FindViewById<View>(2131297515);
			_frame2 = view.FindViewById<View>(2131297516);
			_frame3 = view.FindViewById<View>(2131297517);
		}

		public void Update(object model)
		{
			if (model is SkillCard skillCard)
			{
				Alpha = (skillCard.IsAvailable ? 1f : 0.6f);
				Enabled = skillCard.IsAvailable;
				_name.Text = skillCard.Name;
				_bonus.Text = $"+{skillCard.Bonus}";
				_image.ImageName = $"skill{skillCard.Skill}";
				_star2.Visibility = (skillCard.Rarity >= 2).ToVisibility();
				_star1.Visibility = (skillCard.Rarity >= 1).ToVisibility();
				_count.Text = $"{skillCard.Count}";
				_count.Visibility = (skillCard.Count > 1).ToVisibility();
				_frame3.Visibility = (skillCard.Count >= 4).ToVisibility(goneIfHidden: false);
				_frame2.Visibility = (skillCard.Count >= 3).ToVisibility(goneIfHidden: false);
				_frame1.Visibility = (skillCard.Count >= 2).ToVisibility(goneIfHidden: false);
				_frame.Background = GetFrameBackground(skillCard.Rarity, 0);
				_frame1.Background = GetFrameBackground(skillCard.Rarity, 1);
				_frame2.Background = GetFrameBackground(skillCard.Rarity, 2);
				_frame3.Background = GetFrameBackground(skillCard.Rarity, 3);
			}
		}

		private Drawable GetFrameBackground(int rarity, int number)
		{
			Drawable drawable = base.Context.GetDrawable(GetFrameResource(rarity));
			if (number > 0)
			{
				drawable = drawable.WithFade(50 * number);
			}
			Drawable pressed = drawable.WithFade(128);
			return GetStateListBackground(drawable, pressed);
		}

		private Drawable GetStateListBackground(Drawable drawable, Drawable pressed)
		{
			StateListDrawable stateListDrawable = new StateListDrawable();
			stateListDrawable.AddState(new int[1] { 16842919 }, pressed);
			stateListDrawable.AddState(new int[0], drawable);
			return stateListDrawable;
		}

		private int GetFrameResource(int rarity)
		{
			return rarity switch
			{
				2 => 2131165923, 
				1 => 2131165922, 
				_ => 2131165921, 
			};
		}
	}
	[ViewFor(typeof(SkillCardsPopupViewModel))]
	public class SkillCardsPopup : BasePopup<SkillCardsPopupViewModel>
	{
		private LinearLayout _container;

		public SkillCardsPopup(Context context)
			: base(context)
		{
			Initialize();
		}

		public SkillCardsPopup(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
			Initialize();
		}

		public SkillCardsPopup(Context context, IAttributeSet attrs, int defStyle)
			: base(context, attrs, defStyle)
		{
			Initialize();
		}

		private void Initialize()
		{
			SetPopupContent(2131493159);
			GTButton gTButton = base.PopupContent.FindViewById<GTButton>(2131297519);
			gTButton.Click += OnDoneButtonClicked;
			Bind(gTButton, "Title", "ConfirmButtonTitle");
			_container = base.PopupContent.FindViewById<LinearLayout>(2131297520);
		}

		private void AddCards()
		{
			int num = (int)((double)base.Context.GetScreenSize().Item2 * 0.42);
			int width = (int)((double)num / 1.4);
			foreach (SkillCard card in base.ViewModel.Cards)
			{
				SkillCardView child = new SkillCardView(base.Context)
				{
					Card = card,
					LayoutParameters = new LinearLayout.LayoutParams(width, num),
					Alpha = 0f
				};
				_container.AddView(child);
			}
		}

		private void OnDoneButtonClicked(object sender, EventArgs eventArgs)
		{
			ClosePopup(PopupResult.Done);
		}

		protected override void OnDidAppear()
		{
			AddCards();
			ISoundManager soundManager = ComponentFactory.Resolve<ISoundManager>();
			for (int i = 0; i < _container.ChildCount; i++)
			{
				_container.GetChildAt(i).Animate().SetDuration(300L)
					.SetStartDelay(300 * i)
					.Alpha(1f)
					.WithStartAction(new Runnable(delegate
					{
						soundManager.PlaySound(Sounds.Swipe);
					}));
			}
		}
	}
}
