	{
		private Building _building;

		public Building Building
		{
			get
			{
				return _building;
			}
			set
			{
				_building = value;
				SetAdjustViewBounds(adjustViewBounds: true);
				SetImageResource(_building.CurrentImageName.GetImageId(base.Context));
			}
		}

		public BuildingView(Context context)
			: base(context)
		{
		}

		public BuildingView(Context context, IAttributeSet attrs)
			: base(context, attrs)
		{
		}

		public BuildingView(Context context, IAttributeSet attrs, int defStyleAttr)
			: base(context, attrs, defStyleAttr)
		{
		}

		public BuildingView(Context context, IAttributeSet attrs, int defStyleAttr, int defStyleRes)
			: base(context, attrs, defStyleAttr, defStyleRes)
		{
		}

		protected BuildingView(IntPtr javaReference, JniHandleOwnership transfer)
			: base(javaReference, transfer)
		{
		}

		public ViewGroup.LayoutParams UpdateLayoutParameters(int width, int height)
		{
			if (Building == null)
			{
				return LayoutParameters;
			}
			RelativeLayout.LayoutParams layoutParameters = new RelativeLayout.LayoutParams((int)((float)width * Building.Width), (int)((float)height * Building.Height))
			{
				LeftMargin = (int)((float)width * Building.X),
				TopMargin = (int)((float)height * Building.Y)
			};
			LayoutParameters = layoutParameters;
			return LayoutParameters;
		}

		public bool IsTouchInside(float touchX, float touchY)
		{
			if (base.Width <= 0 || base.Height <= 0)
			{
				return false;
			}
			if (!(Drawable is BitmapDrawable { Bitmap: var bitmap }))
			{
				return false;
			}
			if (bitmap == null)
			{
				return false;
			}
			if (touchX < GetX() || touchX > GetX() + (float)base.Width || touchY < GetY() || touchY > GetY() + (float)base.Height)
			{
				return false;
			}
			if (bitmap.Width <= 0 || bitmap.Height <= 0)
			{
				return false;
			}
			int value = (int)((touchX - GetX()) * (float)bitmap.Width / (float)base.Width);
			int value2 = (int)((touchY - GetY()) * (float)bitmap.Height / (float)base.Height);
			value = value.Clamp(0, bitmap.Width - 1);
			value2 = value2.Clamp(0, bitmap.Height - 1);
			return bitmap.GetPixel(value, value2) != 0;
		}
	}
